insert into public.lectures (slug, skill_id, title, summary, body, reading_minutes, updated_at)
select v.slug, s.id, v.title, v.summary, v.body, v.reading_minutes, now() from (values
  ('angular', 'angular', '{"en":"Angular fundamentals: components, bindings, DI and change detection","uk":"Основи Angular: компоненти, прив''язки, DI та виявлення змін"}'::jsonb, '{"en":"How Angular components talk to each other, how dependency injection works, what triggers change detection and why OnPush matters.","uk":"Як компоненти Angular взаємодіють, як працює впровадження залежностей, що запускає виявлення змін і чому важливий OnPush."}'::jsonb, '{"en":"Angular is a full framework: components, templates, dependency injection (DI), routing and forms come in one package. Interviews focus on data flow and change detection.\n\n## Components and templates\n\nA component is a class with a template. Bindings connect them:\n\n| Syntax | Direction | Example |\n| --- | --- | --- |\n| `{{ value }}` | class → view (text) | `{{ user.name }}` |\n| `[prop]=\"expr\"` | class → view (property) | `[disabled]=\"isSaving\"` |\n| `(event)=\"handler($event)\"` | view → class | `(click)=\"save()\"` |\n| `[(ngModel)]=\"field\"` | two-way | form inputs |\n\nStructural directives change the DOM shape: `*ngIf`, `*ngFor` (newer versions also have `@if` / `@for` blocks).\n\n## Parent ↔ child communication\n\n```ts\n@Component({ selector: \"app-stepper\", template: `\n  <button (click)=\"change(-1)\" [disabled]=\"value <= min\">−</button>\n  <span>{{ value }}</span>\n  <button (click)=\"change(1)\">+</button>` })\nexport class StepperComponent {\n  @Input() value = 0;\n  @Input() min = 0;\n  @Output() valueChange = new EventEmitter<number>();\n\n  change(delta: number) {\n    this.valueChange.emit(this.value + delta);\n  }\n}\n```\n\nThe parent writes `<app-stepper [(value)]=\"qty\" />`. The pair `value` + `valueChange` enables banana-in-a-box two-way binding. For shared state across distant components, use a service.\n\n## Dependency injection\n\nServices are classes registered with an injector:\n\n```ts\n@Injectable({ providedIn: \"root\" })   // one app-wide singleton\nexport class CartService { /* ... */ }\n\nconstructor(private cart: CartService) {}  // or: cart = inject(CartService)\n```\n\nProviders can also live on a module or a component. A component-level provider gives every component instance its own service instance. DI makes code testable: tests swap in a fake provider.\n\n## Lifecycle hooks\n\n- `ngOnChanges`: before `ngOnInit` and whenever an `@Input` reference changes.\n- `ngOnInit`: once, after the first inputs are set. Start data loading here, not in the constructor.\n- `ngOnDestroy`: unsubscribe, clear timers.\n\n## Change detection\n\nZone.js patches async APIs (events, timers, XHR). After each task, Angular checks the component tree top-down and updates changed bindings.\n\nWith `ChangeDetectionStrategy.OnPush`, a component is checked only when:\n\n- an `@Input` gets a **new reference**,\n- an event fires inside it,\n- an `async` pipe emits,\n- you call `markForCheck()`.\n\nSo with OnPush, never mutate input objects or arrays: `this.items.push(x)` will not update the child. Replace them instead: `this.items = [...this.items, x]`.\n\nNewer versions add **signals**: reactive values that let Angular update exactly what changed, and an optional zoneless mode.\n\n## RxJS in Angular\n\n`HttpClient` returns Observables. Prefer the `async` pipe in templates, because it subscribes and unsubscribes for you. Otherwise unsubscribe in `ngOnDestroy`, or use `takeUntilDestroyed`.\n\n## Interview checklist\n\n- Show `@Input`/`@Output` and explain when you''d use a service instead.\n- Explain `providedIn: \"root\"` vs component-level providers.\n- Describe what OnPush checks and why immutability matters.\n- Avoid manual subscriptions when the `async` pipe will do.","uk":"Angular є повноцінним фреймворком: компоненти, шаблони, впровадження залежностей (DI), маршрутизація та форми в одному пакеті. Співбесіди зосереджуються на потоках даних і виявленні змін.\n\n## Компоненти та шаблони\n\nКомпонент є класом із шаблоном. Прив''язки з''єднують їх:\n\n| Синтаксис | Напрям | Приклад |\n| --- | --- | --- |\n| `{{ value }}` | клас → вигляд (текст) | `{{ user.name }}` |\n| `[prop]=\"expr\"` | клас → вигляд (властивість) | `[disabled]=\"isSaving\"` |\n| `(event)=\"handler($event)\"` | вигляд → клас | `(click)=\"save()\"` |\n| `[(ngModel)]=\"field\"` | двостороння | поля форм |\n\nСтруктурні директиви змінюють форму DOM: `*ngIf`, `*ngFor` (у нових версіях також блоки `@if` / `@for`).\n\n## Взаємодія батька й дитини\n\n```ts\n@Component({ selector: \"app-stepper\", template: `\n  <button (click)=\"change(-1)\" [disabled]=\"value <= min\">−</button>\n  <span>{{ value }}</span>\n  <button (click)=\"change(1)\">+</button>` })\nexport class StepperComponent {\n  @Input() value = 0;\n  @Input() min = 0;\n  @Output() valueChange = new EventEmitter<number>();\n\n  change(delta: number) {\n    this.valueChange.emit(this.value + delta);\n  }\n}\n```\n\nБатько пише `<app-stepper [(value)]=\"qty\" />`. Пара `value` + `valueChange` дає двосторонню прив''язку «банан у коробці». Для спільного стану між віддаленими компонентами використовуйте сервіс.\n\n## Впровадження залежностей\n\nСервіси є класами, зареєстрованими в інжекторі:\n\n```ts\n@Injectable({ providedIn: \"root\" })   // один синглтон на застосунок\nexport class CartService { /* ... */ }\n\nconstructor(private cart: CartService) {}  // або: cart = inject(CartService)\n```\n\nПровайдери можуть також бути на рівні модуля чи компонента. Провайдер на рівні компонента дає кожному екземпляру компонента власний екземпляр сервісу. DI робить код тестованим: у тестах підставляють фейковий провайдер.\n\n## Хуки життєвого циклу\n\n- `ngOnChanges`: перед `ngOnInit` і щоразу, коли змінюється посилання `@Input`.\n- `ngOnInit`: один раз, після встановлення перших вхідних даних. Завантаження даних починайте тут, а не в конструкторі.\n- `ngOnDestroy`: відпишіться, очистіть таймери.\n\n## Виявлення змін\n\nZone.js перехоплює асинхронні API (події, таймери, XHR). Після кожної задачі Angular перевіряє дерево компонентів згори донизу й оновлює змінені прив''язки.\n\nЗі `ChangeDetectionStrategy.OnPush` компонент перевіряється лише коли:\n\n- `@Input` отримує **нове посилання**,\n- усередині спрацювала подія,\n- `async` pipe видав значення,\n- ви викликали `markForCheck()`.\n\nТож з OnPush ніколи не змінюйте вхідні об''єкти чи масиви: `this.items.push(x)` не оновить дочірній компонент. Замінюйте їх: `this.items = [...this.items, x]`.\n\nНові версії додали **сигнали**: реактивні значення, що дозволяють оновлювати саме те, що змінилося, і опційний режим без zone.js.\n\n## RxJS в Angular\n\n`HttpClient` повертає Observable. У шаблонах обирайте `async` pipe: він підписується й відписується автоматично. Інакше відписуйтеся в `ngOnDestroy` або використовуйте `takeUntilDestroyed`.\n\n## Чек-лист для співбесіди\n\n- Покажіть `@Input`/`@Output` і поясніть, коли краще використати сервіс.\n- Поясніть різницю між `providedIn: \"root\"` і провайдерами на рівні компонента.\n- Опишіть, що перевіряє OnPush і чому важлива незмінність.\n- Уникайте ручних підписок там, де впорається `async` pipe."}'::jsonb, 9),
  ('arrays-strings', 'arrays-strings', '{"en":"Arrays and strings: idiomatic transformations","uk":"Масиви й рядки: ідіоматичні перетворення"}'::jsonb, '{"en":"map, filter, reduce and friends; mutating vs non-mutating methods; sorting pitfalls; and string tricks for the classic warm-up questions.","uk":"map, filter, reduce та інші; методи, що змінюють і не змінюють масив; пастки сортування; прийоми з рядками для класичних розминкових задач."}'::jsonb, '{"en":"Most coding warm-ups are array or string transformations. Interviewers look for idiomatic, readable code, and for whether you know which methods **mutate**.\n\n## Transform, don''t loop by hand\n\n```js\nconst active = users.filter((u) => u.active);\nconst names = active.map((u) => u.name);\nconst total = orders.reduce((sum, o) => sum + o.amount, 0);\nconst hasAdmin = users.some((u) => u.role === \"admin\");\nconst allPaid = orders.every((o) => o.paid);\nconst firstBig = orders.find((o) => o.amount > 100);\n```\n\nGive `reduce` an **initial value**: without one it throws on an empty array and treats the first element as the accumulator.\n\n## Mutating vs non-mutating\n\n| Mutates the array | Returns a new array |\n| --- | --- |\n| `push`, `pop`, `shift`, `unshift` | `concat`, spread `[...a, x]` |\n| `splice` | `slice`, `toSpliced` |\n| `sort`, `reverse` | `toSorted`, `toReversed` |\n| `fill`, `copyWithin` | `map`, `filter`, `with(i, v)` |\n\nIn React or Redux state, never mutate. `arr.sort()` sorts **in place** and returns the same array, so copy first or use `toSorted`.\n\n## Sorting pitfalls\n\n```js\n[10, 9, 1].sort();               // [1, 10, 9]: compares strings by default!\n[10, 9, 1].sort((a, b) => a - b); // [1, 9, 10]\nnames.sort((a, b) => a.localeCompare(b)); // locale-aware strings\n```\n\n`Array.prototype.sort` is stable, so equal elements keep their order. That lets you sort by several keys in turn.\n\n## Useful idioms\n\n```js\nconst unique = [...new Set(items)];\nconst byId = Object.fromEntries(users.map((u) => [u.id, u]));\nconst chunks = Array.from({ length: Math.ceil(a.length / n) }, (_, i) => a.slice(i * n, i * n + n));\nconst counts = words.reduce((m, w) => m.set(w, (m.get(w) ?? 0) + 1), new Map());\n```\n\n## Strings\n\nStrings are immutable. Every method returns a new string.\n\n- `split`, `join`, `slice`, `trim`, `padStart`, `replaceAll`, `includes`, `startsWith`.\n- Reverse with `[...s].reverse().join(\"\")`. Spreading splits by code points, so emoji survive; `split(\"\")` breaks them.\n- **Anagram check**: compare sorted letters, or better, count characters in a Map, which is O(n).\n- **Palindrome check**: normalise (lowercase, keep letters and digits), then compare with two pointers.\n\nBuilding a long string with `+=` in a loop is fine in modern engines. For many pieces, `array.join` is clearer.\n\n## Complexity awareness\n\n- `includes`/`indexOf` inside a loop is O(n²). Build a `Set` first.\n- `shift`/`unshift` are O(n), because they re-index the array. A queue with heavy use needs a better structure.\n\n## Interview checklist\n\n- Reach for `map`/`filter`/`reduce`, and say when a plain loop is clearer.\n- Know which methods mutate, and copy before sorting shared data.\n- Always pass a comparator to `sort` for numbers.\n- Use Map/Set to turn nested loops into linear passes.","uk":"Більшість розминкових задач є перетвореннями масивів чи рядків. Інтерв''юери шукають ідіоматичний, читабельний код і перевіряють, чи знаєте ви, які методи **змінюють** дані.\n\n## Перетворюйте, а не пишіть цикли вручну\n\n```js\nconst active = users.filter((u) => u.active);\nconst names = active.map((u) => u.name);\nconst total = orders.reduce((sum, o) => sum + o.amount, 0);\nconst hasAdmin = users.some((u) => u.role === \"admin\");\nconst allPaid = orders.every((o) => o.paid);\nconst firstBig = orders.find((o) => o.amount > 100);\n```\n\nПередавайте `reduce` **початкове значення**: без нього метод кидає помилку на порожньому масиві й бере перший елемент як акумулятор.\n\n## Змінюють чи ні\n\n| Змінюють масив | Повертають новий масив |\n| --- | --- |\n| `push`, `pop`, `shift`, `unshift` | `concat`, spread `[...a, x]` |\n| `splice` | `slice`, `toSpliced` |\n| `sort`, `reverse` | `toSorted`, `toReversed` |\n| `fill`, `copyWithin` | `map`, `filter`, `with(i, v)` |\n\nУ стані React чи Redux нічого не змінюйте напряму. `arr.sort()` сортує **на місці** й повертає той самий масив, тож спершу скопіюйте його або використайте `toSorted`.\n\n## Пастки сортування\n\n```js\n[10, 9, 1].sort();               // [1, 10, 9]: за замовчуванням порівнюються рядки!\n[10, 9, 1].sort((a, b) => a - b); // [1, 9, 10]\nnames.sort((a, b) => a.localeCompare(b)); // рядки з урахуванням локалі\n```\n\n`Array.prototype.sort` стабільний, тож рівні елементи зберігають порядок. Це дозволяє сортувати за кількома ключами по черзі.\n\n## Корисні ідіоми\n\n```js\nconst unique = [...new Set(items)];\nconst byId = Object.fromEntries(users.map((u) => [u.id, u]));\nconst chunks = Array.from({ length: Math.ceil(a.length / n) }, (_, i) => a.slice(i * n, i * n + n));\nconst counts = words.reduce((m, w) => m.set(w, (m.get(w) ?? 0) + 1), new Map());\n```\n\n## Рядки\n\nРядки незмінні. Кожен метод повертає новий рядок.\n\n- `split`, `join`, `slice`, `trim`, `padStart`, `replaceAll`, `includes`, `startsWith`.\n- Розворот: `[...s].reverse().join(\"\")`. Spread розбиває рядок на кодові точки, тож емодзі не ламаються; `split(\"\")` їх ламає.\n- **Перевірка анаграми**: порівняти відсортовані літери або, краще, порахувати символи в Map, що дає O(n).\n- **Перевірка паліндрому**: нормалізувати (нижній регістр, лише літери й цифри), потім порівняти двома вказівниками.\n\nПобудова довгого рядка через `+=` у циклі цілком нормальна для сучасних рушіїв. Для багатьох частин `array.join` читається краще.\n\n## Розуміння складності\n\n- `includes`/`indexOf` усередині циклу дає O(n²). Спершу побудуйте `Set`.\n- `shift`/`unshift` мають складність O(n), бо переіндексовують масив. Для інтенсивної черги потрібна інша структура.\n\n## Чек-лист для співбесіди\n\n- Використовуйте `map`/`filter`/`reduce` і пояснюйте, коли звичайний цикл зрозуміліший.\n- Знайте, які методи змінюють масив, і копіюйте перед сортуванням спільних даних.\n- Завжди передавайте компаратор у `sort` для чисел.\n- Використовуйте Map/Set, щоб перетворити вкладені цикли на лінійні проходи."}'::jsonb, 7),
  ('async-javascript', 'async-javascript', '{"en":"Async JavaScript: the event loop, promises and async/await","uk":"Асинхронний JavaScript: цикл подій, проміси та async/await"}'::jsonb, '{"en":"Why setTimeout(0) runs after a resolved promise, how to combine promises, and how to run async work with limited concurrency.","uk":"Чому setTimeout(0) виконується після вирішеного промісу, як комбінувати проміси та як запускати асинхронну роботу з обмеженою паралельністю."}'::jsonb, '{"en":"JavaScript runs your code on **one thread**. Asynchronous APIs let it start work (network, timers) and continue later without blocking.\n\n## The event loop in one picture\n\n1. Run the current script (the **call stack**) to completion.\n2. Run **all microtasks**: promise callbacks, `queueMicrotask`, `await` continuations.\n3. Render if needed (in browsers).\n4. Take **one macrotask** (a timer, an I/O callback, a UI event) and go back to step 1.\n\n```js\nconsole.log(\"A\");\nsetTimeout(() => console.log(\"B\"), 0);\nPromise.resolve().then(() => console.log(\"C\"));\nconsole.log(\"D\");\n// A, D, C, B\n```\n\nMicrotasks always drain before the next macrotask, so `C` comes before `B`. A long synchronous loop blocks everything, including rendering.\n\n## Promises\n\nA promise is pending, fulfilled or rejected, and settles only once. `then` returns a **new** promise, which is what makes chaining work. Return values flow forward; thrown errors jump to the next `catch`.\n\n| Combinator | Resolves when | Rejects when |\n| --- | --- | --- |\n| `Promise.all` | all fulfil (array of values) | any rejects (fail-fast) |\n| `Promise.allSettled` | all settle (status objects) | never |\n| `Promise.race` | the first settles | the first settles with an error |\n| `Promise.any` | the first fulfils | all reject (`AggregateError`) |\n\n## async/await\n\n`async` functions always return a promise. `await` pauses only that function, and the rest of the program keeps running.\n\n```ts\n// Sequential: total time = sum\nfor (const id of ids) results.push(await load(id));\n\n// Parallel: total time = slowest\nconst results = await Promise.all(ids.map(load));\n```\n\nCommon mistakes:\n\n- **Forgetting `await`**: you get a promise instead of a value, and errors become unhandled rejections.\n- **`await` inside `forEach`**: `forEach` ignores returned promises. Use `for…of` or `Promise.all`.\n- **Swallowing errors**: wrap awaits in `try/catch` at the level that can actually handle them.\n\n## Limiting concurrency\n\nFiring 1,000 requests at once can overload a server. Run at most `limit` at a time instead:\n\n```ts\nasync function mapLimit<T, R>(items: T[], limit: number, fn: (x: T) => Promise<R>) {\n  const results: R[] = new Array(items.length);\n  let next = 0;\n  async function worker() {\n    while (next < items.length) {\n      const i = next++;\n      results[i] = await fn(items[i]);\n    }\n  }\n  await Promise.all(Array.from({ length: Math.min(limit, items.length) }, worker));\n  return results;\n}\n```\n\nEach worker picks the next index synchronously (no race, because there is one thread). Results keep their input order.\n\n## Cancellation and timeouts\n\nUse `AbortController` with `fetch`. For a timeout, `Promise.race([work, timeoutPromise])` works, but remember the losing work keeps running unless you abort it.\n\n## Interview checklist\n\n- Predict the output order of mixed timers and promises.\n- Choose between `all`, `allSettled`, `race` and `any`.\n- Turn a sequential loop into parallel or limited-concurrency work.\n- Never leave a promise without error handling.","uk":"JavaScript виконує ваш код в **одному потоці**. Асинхронні API дозволяють почати роботу (мережа, таймери) й продовжити пізніше без блокування.\n\n## Цикл подій на одній картинці\n\n1. Виконати поточний скрипт (**стек викликів**) до кінця.\n2. Виконати **всі мікрозадачі**: колбеки промісів, `queueMicrotask`, продовження після `await`.\n3. Перемалювати сторінку за потреби (у браузері).\n4. Взяти **одну макрозадачу** (таймер, колбек вводу-виводу, подію UI) й повернутися до кроку 1.\n\n```js\nconsole.log(\"A\");\nsetTimeout(() => console.log(\"B\"), 0);\nPromise.resolve().then(() => console.log(\"C\"));\nconsole.log(\"D\");\n// A, D, C, B\n```\n\nМікрозадачі завжди виконуються до наступної макрозадачі, тому `C` іде перед `B`. Довгий синхронний цикл блокує все, включно з рендерингом.\n\n## Проміси\n\nПроміс буває в стані pending, fulfilled або rejected і завершується лише один раз. `then` повертає **новий** проміс, завдяки чому працюють ланцюжки. Повернені значення передаються далі; кинуті помилки перестрибують до найближчого `catch`.\n\n| Комбінатор | Вирішується, коли | Відхиляється, коли |\n| --- | --- | --- |\n| `Promise.all` | усі виконані (масив значень) | будь-який відхилено (fail-fast) |\n| `Promise.allSettled` | усі завершені (об''єкти статусів) | ніколи |\n| `Promise.race` | перший завершився | перший завершився з помилкою |\n| `Promise.any` | перший виконався | усі відхилені (`AggregateError`) |\n\n## async/await\n\nФункції `async` завжди повертають проміс. `await` призупиняє лише цю функцію, а решта програми продовжує працювати.\n\n```ts\n// Послідовно: загальний час = сума\nfor (const id of ids) results.push(await load(id));\n\n// Паралельно: загальний час = найповільніший\nconst results = await Promise.all(ids.map(load));\n```\n\nТипові помилки:\n\n- **Забутий `await`**: ви отримуєте проміс замість значення, а помилки стають необробленими відхиленнями.\n- **`await` усередині `forEach`**: `forEach` ігнорує повернені проміси. Використовуйте `for…of` або `Promise.all`.\n- **Проковтування помилок**: обгортайте `await` у `try/catch` на тому рівні, який справді може їх обробити.\n\n## Обмеження паралельності\n\nВідправити 1000 запитів одночасно означає перевантажити сервер. Натомість запускайте не більше `limit` за раз:\n\n```ts\nasync function mapLimit<T, R>(items: T[], limit: number, fn: (x: T) => Promise<R>) {\n  const results: R[] = new Array(items.length);\n  let next = 0;\n  async function worker() {\n    while (next < items.length) {\n      const i = next++;\n      results[i] = await fn(items[i]);\n    }\n  }\n  await Promise.all(Array.from({ length: Math.min(limit, items.length) }, worker));\n  return results;\n}\n```\n\nКожен воркер синхронно бере наступний індекс (гонки немає, бо потік один). Результати зберігають порядок вхідних даних.\n\n## Скасування й тайм-аути\n\nВикористовуйте `AbortController` разом із `fetch`. Для тайм-ауту підійде `Promise.race([work, timeoutPromise])`, але пам''ятайте: робота, що програла, продовжується, якщо її не скасувати.\n\n## Чек-лист для співбесіди\n\n- Передбачайте порядок виводу для змішаних таймерів і промісів.\n- Обирайте між `all`, `allSettled`, `race` і `any`.\n- Перетворюйте послідовний цикл на паралельну роботу чи роботу з обмеженою паралельністю.\n- Не залишайте жодного промісу без обробки помилок."}'::jsonb, 8),
  ('big-o', 'big-o', '{"en":"Big-O complexity: reasoning about time and space","uk":"Складність Big-O: як оцінювати час і пам''ять"}'::jsonb, '{"en":"What Big-O measures, the common classes from O(1) to O(2ⁿ), how to analyse loops and recursion, and the hidden costs in everyday JavaScript.","uk":"Що вимірює Big-O, поширені класи від O(1) до O(2ⁿ), як аналізувати цикли та рекурсію, і приховані витрати в повсякденному JavaScript."}'::jsonb, '{"en":"Big-O describes how an algorithm''s cost **grows** as the input grows. It ignores constants and lower-order terms, so it describes scaling, not speed.\n\n## Common classes\n\n| Class | Name | Example | n = 1,000,000 |\n| --- | --- | --- | --- |\n| O(1) | constant | array index, `Map.get` | 1 step |\n| O(log n) | logarithmic | binary search | ~20 |\n| O(n) | linear | single loop, `includes` | 10⁶ |\n| O(n log n) | linearithmic | good sorts | ~2·10⁷ |\n| O(n²) | quadratic | nested loops over the same data | 10¹² ✗ |\n| O(2ⁿ) | exponential | all subsets, naive Fibonacci | ✗✗ |\n\nA rough rule: about 10⁸ simple operations per second. If your formula gives more than that for the real input size, look for a better algorithm.\n\n## How to analyse code\n\n- **Sequential blocks add**: O(n) + O(n log n) = O(n log n), because the biggest term wins.\n- **Nested loops multiply**: a loop over `n` inside a loop over `m` is O(n·m).\n- **Halving** the problem each step gives O(log n).\n- **Recursion**: count the calls times the work per call. Two branches per level, n levels deep, is O(2ⁿ).\n- Use different letters for different inputs: comparing two lists is O(n + m) or O(n·m), not O(n²).\n\n## Hidden costs in JavaScript\n\n```js\nfor (const id of ids) {\n  if (list.includes(id)) …     // O(n) inside a loop → O(n·m)\n}\nconst set = new Set(list);      // build once: O(n)\nfor (const id of ids) if (set.has(id)) … // O(m)\n```\n\nOther traps: `array.shift()`/`unshift()` are O(n); `slice`, spread, `concat` and `JSON.stringify` copy everything (O(n)); string concatenation in nested loops; `sort` is O(n log n).\n\n## Space complexity\n\nCount the extra memory beyond the input: new arrays, Maps, recursion depth (the call stack!). Merge sort uses O(n) extra memory, an iterative binary search O(1), a recursive DFS on a tree O(height).\n\n## Amortised cost\n\n`array.push` is O(1) **amortised**. Occasionally the engine reallocates and copies (O(n)), but averaged over many pushes the cost per push stays constant.\n\n## Best, average, worst\n\nQuicksort is O(n log n) on average but O(n²) in the worst case. Hash maps are O(1) on average but degrade with many collisions. When asked \"what''s the complexity\", state which case you mean.\n\n## Interview checklist\n\n- State time **and** space complexity unprompted.\n- Explain where the dominant term comes from.\n- Remove an O(n) lookup from inside a loop with a Set/Map.\n- Mention best, average and worst case when they differ.","uk":"Big-O описує, як **зростає** вартість алгоритму зі збільшенням вхідних даних. Вона ігнорує константи й молодші доданки, тож описує масштабування, а не швидкість.\n\n## Поширені класи\n\n| Клас | Назва | Приклад | n = 1 000 000 |\n| --- | --- | --- | --- |\n| O(1) | стала | доступ за індексом, `Map.get` | 1 крок |\n| O(log n) | логарифмічна | бінарний пошук | ~20 |\n| O(n) | лінійна | один цикл, `includes` | 10⁶ |\n| O(n log n) | лінійно-логарифмічна | хороші сортування | ~2·10⁷ |\n| O(n²) | квадратична | вкладені цикли по тих самих даних | 10¹² ✗ |\n| O(2ⁿ) | експоненційна | усі підмножини, наївне Фібоначчі | ✗✗ |\n\nГрубе правило: близько 10⁸ простих операцій за секунду. Якщо ваша формула дає більше для реального розміру даних, шукайте кращий алгоритм.\n\n## Як аналізувати код\n\n- **Послідовні блоки додаються**: O(n) + O(n log n) = O(n log n), бо перемагає найбільший доданок.\n- **Вкладені цикли множаться**: цикл по `n` усередині циклу по `m` дає O(n·m).\n- **Ділення** задачі навпіл на кожному кроці дає O(log n).\n- **Рекурсія**: кількість викликів помножена на роботу в кожному. Дві гілки на рівень і n рівнів дають O(2ⁿ).\n- Для різних вхідних даних беріть різні літери: порівняння двох списків коштує O(n + m) або O(n·m), а не O(n²).\n\n## Приховані витрати в JavaScript\n\n```js\nfor (const id of ids) {\n  if (list.includes(id)) …     // O(n) усередині циклу → O(n·m)\n}\nconst set = new Set(list);      // побудувати один раз: O(n)\nfor (const id of ids) if (set.has(id)) … // O(m)\n```\n\nІнші пастки: `array.shift()`/`unshift()` коштують O(n); `slice`, spread, `concat` і `JSON.stringify` копіюють усе (O(n)); конкатенація рядків у вкладених циклах; `sort` коштує O(n log n).\n\n## Складність за пам''яттю\n\nРахуйте додаткову пам''ять понад вхідні дані: нові масиви, Map, глибину рекурсії (стек викликів!). Сортування злиттям використовує O(n) додаткової пам''яті, ітеративний бінарний пошук O(1), рекурсивний DFS по дереву O(висота).\n\n## Амортизована вартість\n\n`array.push` коштує O(1) **амортизовано**. Інколи рушій перевиділяє пам''ять і копіює масив (O(n)), але в середньому на багато push вартість одного залишається сталою.\n\n## Найкращий, середній, найгірший\n\nQuicksort у середньому має O(n log n), але в найгіршому випадку O(n²). Хеш-таблиці в середньому мають O(1), але деградують за великої кількості колізій. Коли питають про складність, уточніть, який випадок маєте на увазі.\n\n## Чек-лист для співбесіди\n\n- Самі називайте складність за часом **і** за пам''яттю.\n- Пояснюйте, звідки береться домінантний доданок.\n- Прибирайте пошук O(n) з циклу за допомогою Set/Map.\n- Згадуйте найкращий, середній і найгірший випадки, коли вони різні."}'::jsonb, 7),
  ('browser-apis', 'browser-apis', '{"en":"Browser APIs: storage, fetch, workers and observers","uk":"API браузера: сховища, fetch, воркери та спостерігачі"}'::jsonb, '{"en":"Where to keep data in the browser, how fetch really reports errors, when to use workers, and the observer APIs that replace scroll and resize hacks.","uk":"Де зберігати дані в браузері, як fetch насправді повідомляє про помилки, коли використовувати воркери та API спостерігачів, що замінюють хаки зі scroll і resize."}'::jsonb, '{"en":"The browser is a platform with dozens of APIs. Interviews focus on the ones you use daily and on their sharp edges.\n\n## Storing data\n\n| API | Size | Lifetime | Access | Notes |\n| --- | --- | --- | --- | --- |\n| Cookies | ~4 KB | configurable | sent with every request | use `HttpOnly; Secure; SameSite` for sessions |\n| `localStorage` | ~5 MB | until cleared | sync, strings only, same origin | blocks the main thread |\n| `sessionStorage` | ~5 MB | per tab | sync, strings only | survives reloads, not new tabs |\n| IndexedDB | large | until cleared | async, structured data | offline apps, big caches |\n| Cache API | large | until cleared | async, Request/Response pairs | service workers |\n\n`localStorage` stores **strings**. Serialise with `JSON.stringify` and wrap `JSON.parse` in `try/catch`. Writes can throw (`QuotaExceededError`, or private mode in some browsers). Never store auth tokens where XSS can read them; an `HttpOnly` cookie is safer.\n\n## fetch\n\n```js\nconst res = await fetch(\"/api/items\", {\n  method: \"POST\",\n  headers: { \"Content-Type\": \"application/json\" },\n  body: JSON.stringify(item),\n  signal: AbortSignal.timeout(5000),\n});\nif (!res.ok) throw new Error(`HTTP ${res.status}`); // fetch does NOT reject on 404/500!\nconst data = await res.json();\n```\n\n`fetch` rejects only on network failures or aborts. HTTP errors resolve normally, so check `res.ok`. Use `AbortController` to cancel stale requests, for example when the user types a new search query.\n\n## Workers\n\n- **Web Workers** run JavaScript on another thread: parsing large files, image processing, ML models. They talk to the page via `postMessage` and have no DOM access.\n- **Service Workers** sit between the page and the network: offline caching, background sync, push notifications. They''re the backbone of PWAs and require HTTPS.\n\n## Observers\n\nThey replace polling and expensive scroll/resize listeners:\n\n```js\nconst io = new IntersectionObserver((entries) => {\n  for (const e of entries) if (e.isIntersecting) loadImage(e.target);\n}, { rootMargin: \"200px\" });\ndocument.querySelectorAll(\"img[data-src]\").forEach((img) => io.observe(img));\n```\n\n- `IntersectionObserver`: lazy loading, infinite scroll, analytics impressions.\n- `ResizeObserver`: react to an element''s size (container-aware components).\n- `MutationObserver`: react to DOM changes made by third-party code.\n\n## Other everyday APIs\n\n`URL`/`URLSearchParams` for parsing query strings, `structuredClone` for deep copies, `navigator.clipboard`, `history.pushState` for SPA routing, `requestAnimationFrame` for animations, and `BroadcastChannel` to sync tabs.\n\n## Interview checklist\n\n- Pick the right storage and explain its limits and security implications.\n- Remember that `fetch` resolves on HTTP errors; check `res.ok`.\n- Cancel outdated requests with `AbortController`.\n- Use observers instead of scroll/resize polling.","uk":"Браузер є платформою з десятками API. Співбесіди зосереджуються на тих, якими ви користуєтеся щодня, і на їхніх гострих кутах.\n\n## Зберігання даних\n\n| API | Розмір | Тривалість | Доступ | Примітки |\n| --- | --- | --- | --- | --- |\n| Cookies | ~4 КБ | налаштовується | надсилаються з кожним запитом | для сесій `HttpOnly; Secure; SameSite` |\n| `localStorage` | ~5 МБ | доки не очищено | синхронний, лише рядки, одне джерело | блокує головний потік |\n| `sessionStorage` | ~5 МБ | на вкладку | синхронний, лише рядки | переживає перезавантаження, але не нові вкладки |\n| IndexedDB | великий | доки не очищено | асинхронний, структуровані дані | офлайн-застосунки, великі кеші |\n| Cache API | великий | доки не очищено | асинхронний, пари Request/Response | service workers |\n\n`localStorage` зберігає **рядки**. Серіалізуйте через `JSON.stringify` і обгортайте `JSON.parse` у `try/catch`. Запис може кинути помилку (`QuotaExceededError` або приватний режим у деяких браузерах). Ніколи не зберігайте токени автентифікації там, де їх може прочитати XSS; cookie з `HttpOnly` безпечніший.\n\n## fetch\n\n```js\nconst res = await fetch(\"/api/items\", {\n  method: \"POST\",\n  headers: { \"Content-Type\": \"application/json\" },\n  body: JSON.stringify(item),\n  signal: AbortSignal.timeout(5000),\n});\nif (!res.ok) throw new Error(`HTTP ${res.status}`); // fetch НЕ відхиляється на 404/500!\nconst data = await res.json();\n```\n\n`fetch` відхиляється лише при мережевих збоях або скасуванні. HTTP-помилки вирішуються звичайно, тож перевіряйте `res.ok`. Використовуйте `AbortController`, щоб скасовувати застарілі запити, наприклад коли користувач вводить новий пошуковий запит.\n\n## Воркери\n\n- **Web Workers** виконують JavaScript в іншому потоці: розбір великих файлів, обробка зображень, ML-моделі. Вони спілкуються зі сторінкою через `postMessage` і не мають доступу до DOM.\n- **Service Workers** стоять між сторінкою й мережею: офлайн-кешування, фонова синхронізація, push-сповіщення. Вони є основою PWA й вимагають HTTPS.\n\n## Спостерігачі\n\nВони замінюють опитування й дорогі обробники scroll/resize:\n\n```js\nconst io = new IntersectionObserver((entries) => {\n  for (const e of entries) if (e.isIntersecting) loadImage(e.target);\n}, { rootMargin: \"200px\" });\ndocument.querySelectorAll(\"img[data-src]\").forEach((img) => io.observe(img));\n```\n\n- `IntersectionObserver`: ліниве завантаження, нескінченна прокрутка, аналітика показів.\n- `ResizeObserver`: реакція на розмір елемента (компоненти, що враховують контейнер).\n- `MutationObserver`: реакція на зміни DOM, зроблені стороннім кодом.\n\n## Інші щоденні API\n\n`URL`/`URLSearchParams` для розбору рядків запиту, `structuredClone` для глибоких копій, `navigator.clipboard`, `history.pushState` для маршрутизації SPA, `requestAnimationFrame` для анімацій, `BroadcastChannel` для синхронізації вкладок.\n\n## Чек-лист для співбесіди\n\n- Оберіть правильне сховище й поясніть його обмеження та наслідки для безпеки.\n- Пам''ятайте, що `fetch` вирішується при HTTP-помилках; перевіряйте `res.ok`.\n- Скасовуйте застарілі запити через `AbortController`.\n- Використовуйте спостерігачів замість опитування scroll/resize."}'::jsonb, 8),
  ('closures-scope', 'closures-scope', '{"en":"Closures and scope: what a function remembers","uk":"Замикання та область видимості: що пам''ятає функція"}'::jsonb, '{"en":"Lexical scope, hoisting, the temporal dead zone, the classic loop bug, and practical closures like memoize, once and private state.","uk":"Лексична область видимості, підняття, temporal dead zone, класична помилка з циклом і практичні замикання: memoize, once та приватний стан."}'::jsonb, '{"en":"A **closure** is a function together with the variables it captured from the scope where it was created. Closures power callbacks, React hooks, module privacy and memoisation.\n\n## Lexical scope\n\nScope is decided by **where code is written**, not where it runs. An inner function can read the variables of every enclosing function:\n\n```js\nfunction makeCounter() {\n  let count = 0;                 // private: only reachable through the closure\n  return {\n    inc: () => ++count,\n    get: () => count,\n  };\n}\nconst c = makeCounter();\nc.inc(); c.inc();\nc.get(); // 2\n```\n\nEvery call to `makeCounter` creates a **new** `count`. Closures capture variables (live bindings), not snapshots of values.\n\n## Hoisting and the temporal dead zone\n\n- `function` declarations are hoisted completely and can be called before the line they''re defined on.\n- `var` is hoisted as `undefined`.\n- `let`, `const` and `class` are hoisted but uninitialised. Touching them before the declaration throws a `ReferenceError`: that window is the *temporal dead zone*.\n\n## The classic loop bug\n\n```js\nfor (var i = 0; i < 3; i++) setTimeout(() => console.log(i));\n// 3 3 3: one shared `i`\n\nfor (let i = 0; i < 3; i++) setTimeout(() => console.log(i));\n// 0 1 2: `let` creates a fresh binding per iteration\n```\n\n## Practical closures\n\n```js\nfunction once(fn) {\n  let called = false, result;\n  return function (...args) {\n    if (!called) { called = true; result = fn.apply(this, args); }\n    return result;\n  };\n}\n\nfunction memoize(fn) {\n  const cache = new Map();\n  return (arg) => {\n    if (!cache.has(arg)) cache.set(arg, fn(arg));\n    return cache.get(arg);\n  };\n}\n```\n\nUse `cache.has` rather than a truthiness check, so cached `0`, `\"\"` or `undefined` results still count as hits. For multiple arguments you need a key strategy, such as nested Maps or a serialised key.\n\n## Stale closures\n\nA closure keeps seeing the variables from the render or call that created it. In React, an interval created once with `[]` dependencies reads the initial state forever. Fix it with updater functions, refs or correct dependencies.\n\n## Memory\n\nCaptured variables stay alive as long as the closure is reachable. Remove event listeners and clear timers you no longer need, or their closures (and everything they captured) can''t be collected.\n\n## Interview checklist\n\n- Explain why the `var` loop prints `3 3 3`.\n- Implement `once`, `memoize`, `debounce` or a private counter.\n- Describe the TDZ and what hoisting does for each declaration type.\n- Spot stale closures and explain the fix.","uk":"**Замикання** є функцією разом зі змінними, які вона захопила з області, де її створено. На замиканнях тримаються колбеки, хуки React, приватність модулів і мемоізація.\n\n## Лексична область видимості\n\nОбласть видимості визначається тим, **де код написано**, а не де він виконується. Внутрішня функція бачить змінні всіх зовнішніх функцій:\n\n```js\nfunction makeCounter() {\n  let count = 0;                 // приватна: доступна лише через замикання\n  return {\n    inc: () => ++count,\n    get: () => count,\n  };\n}\nconst c = makeCounter();\nc.inc(); c.inc();\nc.get(); // 2\n```\n\nКожен виклик `makeCounter` створює **новий** `count`. Замикання захоплюють змінні (живі прив''язки), а не знімки значень.\n\n## Підняття та temporal dead zone\n\n- Оголошення `function` піднімаються повністю, і їх можна викликати до рядка оголошення.\n- `var` піднімається зі значенням `undefined`.\n- `let`, `const` і `class` піднімаються, але не ініціалізуються. Звернення до них до оголошення кидає `ReferenceError`: це вікно називається *temporal dead zone*.\n\n## Класична помилка з циклом\n\n```js\nfor (var i = 0; i < 3; i++) setTimeout(() => console.log(i));\n// 3 3 3: один спільний `i`\n\nfor (let i = 0; i < 3; i++) setTimeout(() => console.log(i));\n// 0 1 2: `let` створює нову прив''язку на кожній ітерації\n```\n\n## Практичні замикання\n\n```js\nfunction once(fn) {\n  let called = false, result;\n  return function (...args) {\n    if (!called) { called = true; result = fn.apply(this, args); }\n    return result;\n  };\n}\n\nfunction memoize(fn) {\n  const cache = new Map();\n  return (arg) => {\n    if (!cache.has(arg)) cache.set(arg, fn(arg));\n    return cache.get(arg);\n  };\n}\n```\n\nВикористовуйте `cache.has`, а не перевірку на істинність, щоб закешовані `0`, `\"\"` чи `undefined` теж вважалися влученнями. Для кількох аргументів потрібна стратегія ключа, наприклад вкладені Map або серіалізований ключ.\n\n## Застарілі замикання\n\nЗамикання й далі бачить змінні з того рендеру чи виклику, що його створив. У React інтервал, створений один раз із залежностями `[]`, вічно читатиме початковий стан. Виправлення: функції-оновлювачі, ref або правильні залежності.\n\n## Пам''ять\n\nЗахоплені змінні живуть, поки замикання досяжне. Прибирайте непотрібні слухачі подій і таймери, інакше їхні замикання (і все захоплене) не зможе зібрати збирач сміття.\n\n## Чек-лист для співбесіди\n\n- Поясніть, чому цикл із `var` друкує `3 3 3`.\n- Реалізуйте `once`, `memoize`, `debounce` або приватний лічильник.\n- Опишіть TDZ і що робить підняття з кожним типом оголошення.\n- Помічайте застарілі замикання й пояснюйте виправлення."}'::jsonb, 7),
  ('css', 'css', '{"en":"CSS that interviewers ask about: cascade, box model, Flexbox and Grid","uk":"CSS, про який питають на співбесідах: каскад, блокова модель, Flexbox і Grid"}'::jsonb, '{"en":"How the cascade and specificity decide which rule wins, the box model, positioning and stacking, and when to use Flexbox or Grid.","uk":"Як каскад і специфічність визначають, яке правило перемагає, блокова модель, позиціювання й контексти накладання, і коли обирати Flexbox чи Grid."}'::jsonb, '{"en":"CSS questions test whether you can predict what the browser will do, not whether you memorised properties.\n\n## The cascade and specificity\n\nWhen several rules set the same property, the browser picks the winner by:\n\n1. **Origin and importance**: `!important` user-agent/user/author rules, then normal rules.\n2. **Cascade layers** (`@layer`): later layers win over earlier ones.\n3. **Specificity**: `(ids, classes/attributes/pseudo-classes, elements)`.\n4. **Source order**: the last declaration wins.\n\n| Selector | Specificity |\n| --- | --- |\n| `p` | (0,0,1) |\n| `.card p` | (0,1,1) |\n| `#main .card p` | (1,1,1) |\n| `a:hover` | (0,1,1) |\n| `:where(.x) p` | (0,0,1): `:where` adds nothing |\n\nInline styles beat all selectors. Prefer low, flat specificity (single classes) so overrides stay predictable.\n\n## The box model\n\nEach element is content + padding + border + margin. With the default `box-sizing: content-box`, `width` sets only the content box, so padding and border make the element wider. Most resets use:\n\n```css\n*, *::before, *::after { box-sizing: border-box; }\n```\n\nVertical margins of adjacent blocks **collapse** (the larger one wins). Flex and grid items don''t collapse margins.\n\n## Positioning and stacking\n\n- `relative`: offset from its normal place, and becomes the containing block for absolute children.\n- `absolute`: removed from flow and placed relative to the nearest positioned ancestor.\n- `fixed`: relative to the viewport. `sticky`: sticks within its scroll container.\n- `z-index` only compares elements within the same **stacking context**. `opacity < 1`, `transform`, `filter` and `position` with a z-index all create new contexts, which explains the classic \"my z-index: 9999 doesn''t work\".\n\n## Flexbox: one dimension\n\n```css\n.toolbar { display: flex; justify-content: space-between; align-items: center; gap: 1rem; }\n```\n\n`justify-content` works on the main axis, `align-items` on the cross axis. `flex: 1` lets items share the free space. Use Flexbox for rows of controls, nav bars and centring.\n\n## Grid: two dimensions\n\n```css\n.cards {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(16rem, 1fr));\n  gap: 1rem;\n}\n```\n\nGrid controls rows and columns together. `auto-fill` + `minmax` gives responsive columns without media queries. Use Grid for page layouts and card galleries.\n\n## Responsive and modern CSS\n\n- Mobile-first media queries (`min-width`), relative units (`rem`, `%`, `vw`) and `clamp()` for fluid type.\n- Container queries (`@container`) adapt components to their own width.\n- Custom properties (`--brand: #0b5a43`) cascade and can change at runtime.\n- Visually hidden text for screen readers: clip it with `position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0)`. Never use `display: none`, which hides it from assistive technology too.\n\n## Interview checklist\n\n- Calculate specificity and explain why a rule doesn''t apply.\n- Explain `border-box`, margin collapsing and stacking contexts.\n- Choose Flexbox vs Grid, and centre anything both ways.\n- Hide content visually without hiding it from screen readers.","uk":"Питання з CSS перевіряють, чи вмієте ви передбачити поведінку браузера, а не чи пам''ятаєте властивості напам''ять.\n\n## Каскад і специфічність\n\nКоли кілька правил задають ту саму властивість, браузер обирає переможця за:\n\n1. **Походженням і важливістю**: правила `!important` (браузера, користувача, автора), потім звичайні.\n2. **Каскадними шарами** (`@layer`): пізніші шари перемагають раніші.\n3. **Специфічністю**: `(id, класи/атрибути/псевдокласи, елементи)`.\n4. **Порядком у коді**: перемагає останнє оголошення.\n\n| Селектор | Специфічність |\n| --- | --- |\n| `p` | (0,0,1) |\n| `.card p` | (0,1,1) |\n| `#main .card p` | (1,1,1) |\n| `a:hover` | (0,1,1) |\n| `:where(.x) p` | (0,0,1): `:where` нічого не додає |\n\nВбудовані стилі (inline) перемагають усі селектори. Тримайте специфічність низькою й пласкою (окремі класи), щоб перевизначення лишалися передбачуваними.\n\n## Блокова модель\n\nКожен елемент складається з вмісту, padding, рамки та margin. З типовим `box-sizing: content-box` властивість `width` задає лише вміст, тож padding і рамка роблять елемент ширшим. Більшість скидань стилів використовує:\n\n```css\n*, *::before, *::after { box-sizing: border-box; }\n```\n\nВертикальні відступи сусідніх блоків **схлопуються** (перемагає більший). У flex- і grid-елементів відступи не схлопуються.\n\n## Позиціювання й накладання\n\n- `relative`: зсув від звичайного місця; стає контейнером для абсолютно позиціонованих нащадків.\n- `absolute`: вилучений з потоку, розміщується відносно найближчого позиціонованого предка.\n- `fixed`: відносно вікна перегляду. `sticky`: «прилипає» в межах свого контейнера прокрутки.\n- `z-index` порівнює лише елементи в межах одного **контексту накладання**. `opacity < 1`, `transform`, `filter` і `position` разом із z-index створюють нові контексти, що пояснює класичне «мій z-index: 9999 не працює».\n\n## Flexbox: один вимір\n\n```css\n.toolbar { display: flex; justify-content: space-between; align-items: center; gap: 1rem; }\n```\n\n`justify-content` працює на головній осі, `align-items` на поперечній. `flex: 1` дозволяє елементам ділити вільне місце. Flexbox підходить для рядків елементів керування, навігаційних панелей і центрування.\n\n## Grid: два виміри\n\n```css\n.cards {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(16rem, 1fr));\n  gap: 1rem;\n}\n```\n\nGrid керує рядками й колонками одночасно. `auto-fill` + `minmax` дає адаптивні колонки без медіазапитів. Grid підходить для макетів сторінок і галерей карток.\n\n## Адаптивний і сучасний CSS\n\n- Медіазапити mobile-first (`min-width`), відносні одиниці (`rem`, `%`, `vw`) і `clamp()` для плавної типографіки.\n- Запити до контейнера (`@container`) підлаштовують компоненти під власну ширину.\n- Користувацькі властивості (`--brand: #0b5a43`) успадковуються каскадом і можуть змінюватися під час роботи.\n- Візуально прихований текст для зчитувачів екрана: обріжте його через `position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0)`. Ніколи не використовуйте `display: none`, бо це приховує текст і від допоміжних технологій.\n\n## Чек-лист для співбесіди\n\n- Обчисліть специфічність і поясніть, чому правило не застосовується.\n- Поясніть `border-box`, схлопування відступів і контексти накладання.\n- Оберіть між Flexbox і Grid та відцентруйте будь-що обома способами.\n- Приховайте вміст візуально, не приховуючи його від зчитувачів екрана."}'::jsonb, 8),
  ('data-structures', 'data-structures', '{"en":"Data structures: choosing the right container","uk":"Структури даних: як обрати правильний контейнер"}'::jsonb, '{"en":"Arrays, hash maps, sets, stacks, queues, linked lists, trees, heaps and graphs: what each is fast at and when to reach for it.","uk":"Масиви, хеш-таблиці, множини, стеки, черги, зв''язні списки, дерева, купи й графи: у чому кожна структура швидка і коли її обирати."}'::jsonb, '{"en":"Choosing the right data structure usually decides the complexity before you write a line of code. Learn what each structure makes cheap.\n\n## The cheat sheet\n\n| Structure | Access | Search | Insert/delete | Typical use |\n| --- | --- | --- | --- | --- |\n| Array | O(1) by index | O(n) | O(n) in the middle, O(1) amortised at the end | ordered lists, stacks |\n| Hash map / `Map` | — | O(1) avg | O(1) avg | lookups by key, counting, caching |\n| Set | — | O(1) avg | O(1) avg | membership, de-duplication |\n| Stack | top O(1) | — | push/pop O(1) | undo, parsing, DFS |\n| Queue | front O(1) | — | enqueue/dequeue O(1)* | BFS, task scheduling |\n| Linked list | O(n) | O(n) | O(1) with a node reference | LRU caches, frequent splicing |\n| Binary search tree (balanced) | O(log n) | O(log n) | O(log n) | ordered data, ranges |\n| Heap | min/max O(1) | — | O(log n) | priority queues, top-k |\n\n*Using `array.shift()` is O(n). A real queue needs a head index or a linked list.\n\n## Hash maps\n\nJavaScript''s `Map` preserves insertion order, accepts any key type and has `size`. Use it instead of plain objects for dynamic keys. Typical patterns:\n\n- **Counting**: `count.set(x, (count.get(x) ?? 0) + 1)`.\n- **Two-sum**: store `value → index` while scanning, so each lookup is O(1).\n- **Grouping**: key → array of items.\n\n## Stacks and queues\n\nA stack is last-in, first-out. Use it to match brackets, evaluate expressions and drive DFS iteratively.\n\n```ts\nfunction balanced(s: string) {\n  const pairs: Record<string, string> = { \")\": \"(\", \"]\": \"[\", \"}\": \"{\" };\n  const stack: string[] = [];\n  for (const ch of s) {\n    if (\"([{\".includes(ch)) stack.push(ch);\n    else if (ch in pairs && stack.pop() !== pairs[ch]) return false;\n  }\n  return stack.length === 0;\n}\n```\n\nA queue is first-in, first-out. Breadth-first search uses one to visit nodes level by level.\n\n## Linked lists and the LRU cache\n\nA doubly linked list lets you remove a known node in O(1). Combine it with a Map (key → node) and you get an **LRU cache** with O(1) `get` and `put`. In JavaScript you can cheat elegantly: a `Map` keeps insertion order, so delete and re-insert a key to mark it most recent, and evict `map.keys().next().value`.\n\n## Trees\n\n- A **binary search tree** keeps left < node < right. It''s only fast when balanced (AVL, red-black).\n- Traversals: in-order (sorted output for a BST), pre-order (copying), post-order (deleting), level-order (BFS).\n- The DOM, JSON and file systems are trees. Recursion is the natural tool.\n\n## Heaps\n\nA binary heap stored in an array gives O(1) peek and O(log n) push/pop. Use it for \"k largest\", merging sorted lists and Dijkstra''s algorithm. JavaScript has no built-in heap, so be ready to sketch one.\n\n## Graphs\n\nRepresent a graph as an adjacency list (`Map<node, node[]>`). Use BFS for shortest paths in unweighted graphs and DFS for connectivity and cycle detection. Keep a `visited` Set to avoid infinite loops.\n\n## Interview checklist\n\n- State the operations you need and their frequency, then pick the structure.\n- Reach for a Map/Set to remove nested loops.\n- Know how to implement a queue without `shift`, an LRU cache and a bracket matcher.\n- Mention balance for trees and the array-backed heap.","uk":"Вибір структури даних зазвичай визначає складність ще до того, як ви напишете перший рядок коду. Вивчіть, які операції кожна структура робить дешевими.\n\n## Шпаргалка\n\n| Структура | Доступ | Пошук | Вставка/видалення | Типове використання |\n| --- | --- | --- | --- | --- |\n| Масив | O(1) за індексом | O(n) | O(n) у середині, амортизовано O(1) в кінці | упорядковані списки, стеки |\n| Хеш-таблиця / `Map` | — | O(1) у середньому | O(1) у середньому | пошук за ключем, підрахунок, кеш |\n| Множина (Set) | — | O(1) у середньому | O(1) у середньому | перевірка наявності, усунення дублікатів |\n| Стек | вершина O(1) | — | push/pop O(1) | скасування дій, розбір, DFS |\n| Черга | початок O(1) | — | додати/взяти O(1)* | BFS, планування задач |\n| Зв''язний список | O(n) | O(n) | O(1) за посиланням на вузол | LRU-кеші, часте вирізання |\n| Бінарне дерево пошуку (збалансоване) | O(log n) | O(log n) | O(log n) | упорядковані дані, діапазони |\n| Купа (heap) | min/max O(1) | — | O(log n) | черги з пріоритетом, top-k |\n\n*`array.shift()` має складність O(n). Справжня черга потребує індексу голови або зв''язного списку.\n\n## Хеш-таблиці\n\n`Map` у JavaScript зберігає порядок вставки, приймає ключі будь-якого типу й має `size`. Використовуйте його замість звичайних об''єктів для динамічних ключів. Типові патерни:\n\n- **Підрахунок**: `count.set(x, (count.get(x) ?? 0) + 1)`.\n- **Two-sum**: зберігайте `значення → індекс` під час проходу, тож кожен пошук коштує O(1).\n- **Групування**: ключ → масив елементів.\n\n## Стеки й черги\n\nСтек працює за принципом «останнім прийшов, першим вийшов». Він допомагає перевіряти дужки, обчислювати вирази й виконувати DFS ітеративно.\n\n```ts\nfunction balanced(s: string) {\n  const pairs: Record<string, string> = { \")\": \"(\", \"]\": \"[\", \"}\": \"{\" };\n  const stack: string[] = [];\n  for (const ch of s) {\n    if (\"([{\".includes(ch)) stack.push(ch);\n    else if (ch in pairs && stack.pop() !== pairs[ch]) return false;\n  }\n  return stack.length === 0;\n}\n```\n\nЧерга працює за принципом «першим прийшов, першим вийшов». Пошук ушир (BFS) використовує чергу, щоб обходити вузли рівень за рівнем.\n\n## Зв''язні списки та LRU-кеш\n\nДвозв''язний список дозволяє видалити відомий вузол за O(1). Поєднайте його з Map (ключ → вузол) і отримаєте **LRU-кеш** з `get` і `put` за O(1). У JavaScript можна елегантно «схитрувати»: `Map` зберігає порядок вставки, тож видаліть і знову вставте ключ, щоб позначити його найсвіжішим, а витісняйте `map.keys().next().value`.\n\n## Дерева\n\n- **Бінарне дерево пошуку** тримає ліве < вузол < праве. Воно швидке лише тоді, коли збалансоване (AVL, червоно-чорне).\n- Обходи: in-order (відсортований вивід для BST), pre-order (копіювання), post-order (видалення), level-order (BFS).\n- DOM, JSON і файлові системи є деревами. Рекурсія для них природний інструмент.\n\n## Купи\n\nБінарна купа, що зберігається в масиві, дає перегляд вершини за O(1) і push/pop за O(log n). Використовуйте її для «k найбільших», злиття відсортованих списків і алгоритму Дейкстри. У JavaScript немає вбудованої купи, тож будьте готові накидати її реалізацію.\n\n## Графи\n\nПредставляйте граф списком суміжності (`Map<вузол, вузол[]>`). BFS знаходить найкоротші шляхи в незважених графах, DFS перевіряє зв''язність і шукає цикли. Тримайте Set `visited`, щоб уникнути нескінченних циклів.\n\n## Чек-лист для співбесіди\n\n- Назвіть потрібні операції та їхню частоту, потім обирайте структуру.\n- Використовуйте Map/Set, щоб позбутися вкладених циклів.\n- Знайте, як реалізувати чергу без `shift`, LRU-кеш і перевірку дужок.\n- Згадайте про збалансованість дерев і купу на масиві."}'::jsonb, 9),
  ('dom-events', 'dom-events', '{"en":"DOM and events: propagation, delegation and default actions","uk":"DOM і події: поширення, делегування та дії за замовчуванням"}'::jsonb, '{"en":"How events travel through the DOM, how delegation keeps handlers cheap and dynamic, and how to query and update the DOM efficiently.","uk":"Як події проходять через DOM, як делегування робить обробники дешевими й динамічними та як ефективно шукати й змінювати DOM."}'::jsonb, '{"en":"Frameworks hide the DOM, but interviewers still expect you to know what they do underneath, especially how events flow.\n\n## Querying and updating\n\n```js\nconst list = document.querySelector(\"#todo\");          // first match or null\nconst items = document.querySelectorAll(\".item\");     // static NodeList\nconst li = document.createElement(\"li\");\nli.textContent = userInput;                             // safe: no HTML parsing\nlist.append(li);\n```\n\n- Use `textContent` for user data. `innerHTML` parses HTML and opens the door to **XSS**.\n- Batch DOM writes. Reading layout (`offsetHeight`, `getBoundingClientRect`) right after writing forces a synchronous reflow (\"layout thrashing\").\n- `classList.toggle(\"open\", isOpen)` and `dataset.id` are cleaner than string manipulation.\n\n## Event propagation\n\nAn event travels in three phases:\n\n1. **Capture**: from `window` down to the target''s parent.\n2. **Target**: on the element that was clicked.\n3. **Bubble**: back up to `window`.\n\n```js\nel.addEventListener(\"click\", handler);                    // bubbling phase (default)\nel.addEventListener(\"click\", handler, { capture: true }); // capture phase\nel.addEventListener(\"scroll\", onScroll, { passive: true }); // promise not to preventDefault\nel.addEventListener(\"click\", once, { once: true });        // auto-removed after first call\n```\n\n- `event.target` is the element where the event started. `event.currentTarget` is the element whose listener is running.\n- `stopPropagation()` stops the journey. Use it sparingly, because it breaks delegation and analytics higher up.\n- `preventDefault()` cancels the browser''s default action (following a link, submitting a form, checking a box). It does not stop propagation.\n\nNot every event bubbles: `focus`/`blur` don''t (use `focusin`/`focusout`), and neither do `mouseenter`/`mouseleave`.\n\n## Event delegation\n\nInstead of one listener per item, attach **one** listener to a container and find the item from `event.target`:\n\n```js\nlist.addEventListener(\"click\", (event) => {\n  const button = event.target.closest(\"button.delete\");\n  if (!button || !list.contains(button)) return;\n  removeTodo(button.closest(\"li\").dataset.id);\n});\n```\n\nBenefits: fewer listeners, and items added later work automatically. `closest` handles clicks on icons or spans inside the button.\n\n## Cleaning up\n\nRemove listeners you no longer need (`removeEventListener` with the same function reference, or an `AbortController` signal) to avoid leaks and duplicated handlers, which is common in SPAs.\n\n```js\nconst controller = new AbortController();\nwindow.addEventListener(\"resize\", onResize, { signal: controller.signal });\ncontroller.abort(); // removes it\n```\n\n## Interview checklist\n\n- Explain capture vs bubble, and `target` vs `currentTarget`.\n- Implement event delegation with `closest`.\n- Contrast `preventDefault` and `stopPropagation`.\n- Use `textContent` for untrusted strings and avoid layout thrashing.","uk":"Фреймворки приховують DOM, але інтерв''юери все одно очікують, що ви знаєте, що відбувається під капотом, особливо як рухаються події.\n\n## Пошук і зміна\n\n```js\nconst list = document.querySelector(\"#todo\");          // перший збіг або null\nconst items = document.querySelectorAll(\".item\");     // статичний NodeList\nconst li = document.createElement(\"li\");\nli.textContent = userInput;                             // безпечно: без розбору HTML\nlist.append(li);\n```\n\n- Для даних користувача використовуйте `textContent`. `innerHTML` розбирає HTML і відкриває шлях до **XSS**.\n- Групуйте записи в DOM. Читання геометрії (`offsetHeight`, `getBoundingClientRect`) одразу після запису змушує синхронно перераховувати розкладку («layout thrashing»).\n- `classList.toggle(\"open\", isOpen)` і `dataset.id` чистіші за роботу з рядками.\n\n## Поширення подій\n\nПодія проходить три фази:\n\n1. **Занурення (capture)**: від `window` донизу до батька цілі.\n2. **Ціль (target)**: на елементі, по якому клікнули.\n3. **Спливання (bubble)**: назад угору до `window`.\n\n```js\nel.addEventListener(\"click\", handler);                    // фаза спливання (за замовчуванням)\nel.addEventListener(\"click\", handler, { capture: true }); // фаза занурення\nel.addEventListener(\"scroll\", onScroll, { passive: true }); // обіцяємо не викликати preventDefault\nel.addEventListener(\"click\", once, { once: true });        // автоматично знімається після першого виклику\n```\n\n- `event.target` є елементом, де подія почалася. `event.currentTarget` є елементом, чий обробник зараз виконується.\n- `stopPropagation()` зупиняє рух події. Використовуйте обережно, бо це ламає делегування й аналітику вище за ієрархією.\n- `preventDefault()` скасовує дію браузера за замовчуванням (перехід за посиланням, надсилання форми, позначення чекбокса). Поширення події він не зупиняє.\n\nНе всі події спливають: `focus`/`blur` ні (використовуйте `focusin`/`focusout`), `mouseenter`/`mouseleave` теж ні.\n\n## Делегування подій\n\nЗамість окремого обробника на кожен елемент додайте **один** обробник на контейнер і знаходьте елемент через `event.target`:\n\n```js\nlist.addEventListener(\"click\", (event) => {\n  const button = event.target.closest(\"button.delete\");\n  if (!button || !list.contains(button)) return;\n  removeTodo(button.closest(\"li\").dataset.id);\n});\n```\n\nПереваги: менше обробників, а елементи, додані пізніше, працюють автоматично. `closest` обробляє кліки по іконках чи span усередині кнопки.\n\n## Прибирання\n\nЗнімайте непотрібні обробники (`removeEventListener` з тим самим посиланням на функцію або сигнал `AbortController`), щоб уникнути витоків пам''яті й дубльованих обробників, що часто трапляється в SPA.\n\n```js\nconst controller = new AbortController();\nwindow.addEventListener(\"resize\", onResize, { signal: controller.signal });\ncontroller.abort(); // знімає обробник\n```\n\n## Чек-лист для співбесіди\n\n- Поясніть занурення й спливання, а також `target` проти `currentTarget`.\n- Реалізуйте делегування подій через `closest`.\n- Порівняйте `preventDefault` і `stopPropagation`.\n- Використовуйте `textContent` для неперевірених рядків і уникайте layout thrashing."}'::jsonb, 7),
  ('es-modules', 'es-modules', '{"en":"ES modules: import/export, live bindings and code splitting","uk":"ES-модулі: import/export, живі прив''язки та розділення коду"}'::jsonb, '{"en":"How ESM differs from CommonJS, named vs default exports, live bindings, evaluation order, circular imports and dynamic import().","uk":"Чим ESM відрізняється від CommonJS, іменовані й типові експорти, живі прив''язки, порядок виконання, циклічні імпорти та динамічний import()."}'::jsonb, '{"en":"ES modules (ESM) are JavaScript''s standard module system, used natively by browsers, Node.js and every modern bundler.\n\n## Syntax\n\n```js\n// math.js\nexport const PI = 3.14159;\nexport function area(r) { return PI * r * r; }\nexport default class Circle { /* ... */ }\n\n// app.js\nimport Circle, { area, PI as pi } from \"./math.js\";\nimport * as math from \"./math.js\";       // namespace object\nexport { area } from \"./math.js\";          // re-export (barrel files)\n```\n\n- **Named exports** are explicit, so tooling can tree-shake them and rename-refactor them safely.\n- A **default export** is a single \"main\" value. Importers choose its name, which makes searching the codebase harder.\n\n## ESM vs CommonJS\n\n| | ESM | CommonJS |\n| --- | --- | --- |\n| Syntax | `import` / `export` | `require` / `module.exports` |\n| Analysis | static, at parse time | dynamic, at run time |\n| Loading | asynchronous, can use top-level `await` | synchronous |\n| Bindings | **live** (read-only views of the export) | value copies |\n| Tree-shaking | yes | limited |\n\nBecause imports are static, they must sit at the top level with string literals. Bundlers can then remove unused exports.\n\n## Live bindings\n\n```js\n// counter.js\nexport let count = 0;\nexport function inc() { count++; }\n\n// main.js\nimport { count, inc } from \"./counter.js\";\ninc();\nconsole.log(count); // 1: the import reflects the module''s current value\ncount = 5;          // TypeError: imports are read-only\n```\n\n## Evaluation order\n\nA module is evaluated **once**, the first time it''s imported, and every importer shares the same instance. That makes modules natural singletons. Dependencies are evaluated depth-first, before the importing module''s body.\n\n**Circular imports** work only if neither module uses the other''s exports during its top-level evaluation. Otherwise you hit the TDZ (`ReferenceError`) or see `undefined`. Break cycles by moving shared code into a third module.\n\n## Dynamic `import()`\n\n```js\nconst { Chart } = await import(\"./chart.js\"); // returns a promise of the namespace\n```\n\nUse it for code splitting (load heavy features on demand) and for conditional loading. Bundlers create a separate chunk for each dynamic import.\n\n## Interview checklist\n\n- Contrast ESM and CommonJS, and explain why static imports enable tree-shaking.\n- Explain live bindings, and that imports are read-only.\n- Describe what happens with circular dependencies and how to fix them.\n- Use `import()` for lazy loading heavy code.","uk":"ES-модулі (ESM) є стандартною системою модулів JavaScript. Їх нативно використовують браузери, Node.js і всі сучасні збирачі.\n\n## Синтаксис\n\n```js\n// math.js\nexport const PI = 3.14159;\nexport function area(r) { return PI * r * r; }\nexport default class Circle { /* ... */ }\n\n// app.js\nimport Circle, { area, PI as pi } from \"./math.js\";\nimport * as math from \"./math.js\";       // об''єкт простору імен\nexport { area } from \"./math.js\";          // повторний експорт (barrel-файли)\n```\n\n- **Іменовані експорти** явні, тож інструменти можуть безпечно прибирати невикористаний код (tree-shaking) і перейменовувати їх під час рефакторингу.\n- **Типовий експорт (default)** є єдиним «головним» значенням. Імпортер сам обирає назву, що ускладнює пошук у кодовій базі.\n\n## ESM проти CommonJS\n\n| | ESM | CommonJS |\n| --- | --- | --- |\n| Синтаксис | `import` / `export` | `require` / `module.exports` |\n| Аналіз | статичний, під час розбору | динамічний, під час виконання |\n| Завантаження | асинхронне, дозволяє `await` верхнього рівня | синхронне |\n| Прив''язки | **живі** (лише для читання) | копії значень |\n| Tree-shaking | так | обмежено |\n\nОскільки імпорти статичні, вони мають бути на верхньому рівні з рядковими літералами. Завдяки цьому збирачі прибирають невикористані експорти.\n\n## Живі прив''язки\n\n```js\n// counter.js\nexport let count = 0;\nexport function inc() { count++; }\n\n// main.js\nimport { count, inc } from \"./counter.js\";\ninc();\nconsole.log(count); // 1: імпорт відображає поточне значення модуля\ncount = 5;          // TypeError: імпорти лише для читання\n```\n\n## Порядок виконання\n\nМодуль виконується **один раз**, під час першого імпорту, і всі імпортери ділять той самий екземпляр. Тому модулі природно працюють як синглтони. Залежності виконуються вглиб, раніше за тіло модуля, що їх імпортує.\n\n**Циклічні імпорти** працюють, лише якщо жоден модуль не використовує експорти іншого під час свого виконання на верхньому рівні. Інакше ви отримаєте TDZ (`ReferenceError`) або `undefined`. Розривайте цикли, винісши спільний код у третій модуль.\n\n## Динамічний `import()`\n\n```js\nconst { Chart } = await import(\"./chart.js\"); // повертає проміс простору імен\n```\n\nВикористовуйте його для розділення коду (завантажувати важкі функції на вимогу) й умовного завантаження. Збирачі створюють окремий чанк для кожного динамічного імпорту.\n\n## Чек-лист для співбесіди\n\n- Порівняйте ESM і CommonJS та поясніть, чому статичні імпорти уможливлюють tree-shaking.\n- Поясніть живі прив''язки й те, що імпорти лише для читання.\n- Опишіть, що відбувається з циклічними залежностями й як це виправити.\n- Використовуйте `import()` для лінивого завантаження важкого коду."}'::jsonb, 6),
  ('git', 'git', '{"en":"Git for teams: commits, branches, merge vs rebase and recovery","uk":"Git для команд: коміти, гілки, merge проти rebase і відновлення"}'::jsonb, '{"en":"Git''s data model in plain words, branching workflows, when to merge or rebase, resolving conflicts, and how to undo almost anything safely.","uk":"Модель даних Git простими словами, процеси роботи з гілками, коли робити merge, а коли rebase, розв''язання конфліктів і як безпечно скасувати майже будь-що."}'::jsonb, '{"en":"Git questions check whether you can collaborate without losing work, and whether you can recover when something goes wrong.\n\n## The model in one paragraph\n\nA **commit** is a snapshot of the project plus metadata and a pointer to its parent(s). A **branch** is just a movable name pointing at a commit. `HEAD` is where you are now. Your work moves through three areas: the **working tree** → the **staging area** (`git add`) → the **repository** (`git commit`).\n\n## Everyday flow\n\n```bash\ngit switch -c feature/search      # new branch from the current commit\ngit add -p                        # stage hunks interactively\ngit commit -m \"feat: add search box\"\ngit fetch origin\ngit rebase origin/main            # replay your commits on the latest main\ngit push -u origin feature/search # open a pull request\n```\n\nWrite small, focused commits with messages that explain **why**. Conventional Commits (`feat:`, `fix:`) help with changelogs.\n\n## Merge vs rebase\n\n- **Merge** joins histories with a merge commit. It is non-destructive and shows exactly what happened, but history can get noisy.\n- **Rebase** replays your commits on top of another branch. History becomes linear, but commits get **new hashes**.\n\nThe golden rule: **don''t rebase commits that others already have** (shared/public branches). Rebasing your own local feature branch before a PR is fine. Squash-merging a PR gives `main` one commit per feature.\n\n## Conflicts\n\nConflicts happen when both sides changed the same lines. Git marks them:\n\n```\n<<<<<<< HEAD\nconst limit = 10;\n=======\nconst limit = 20;\n>>>>>>> feature\n```\n\nDecide on the correct code (it may combine both sides), remove the markers, run the tests, then `git add` and continue (`git merge --continue` or `git rebase --continue`).\n\n## Undoing things\n\n| Situation | Command |\n| --- | --- |\n| Discard unstaged changes in a file | `git restore file` |\n| Unstage a file | `git restore --staged file` |\n| Fix the last commit (not pushed) | `git commit --amend` |\n| Undo a pushed commit safely | `git revert <sha>` (creates an inverse commit) |\n| Move the branch back, keep changes | `git reset --soft HEAD~1` |\n| Throw away commits **locally** | `git reset --hard <sha>` (dangerous) |\n| \"I lost a commit!\" | `git reflog`, then branch from the old sha |\n\n`revert` is safe for shared history. `reset` rewrites it. `git stash` shelves work in progress temporarily.\n\n## Finding bugs\n\n`git bisect` binary-searches history for the commit that introduced a bug. `git blame` (or `git log -p -S \"text\"`) shows when and why a line changed.\n\n## Interview checklist\n\n- Explain merge vs rebase and the golden rule of rebasing.\n- Resolve a conflict and continue the operation.\n- Choose `revert` vs `reset` and recover with `reflog`.\n- Describe your team''s branching and PR workflow.","uk":"Питання про Git перевіряють, чи вмієте ви працювати в команді, не втрачаючи роботи, і чи зможете відновитися, коли щось пішло не так.\n\n## Модель в одному абзаці\n\n**Коміт** є знімком проєкту разом із метаданими й посиланням на батьківський коміт(и). **Гілка** є лише рухомою назвою, що вказує на коміт. `HEAD` показує, де ви зараз. Ваша робота проходить три зони: **робоча копія** → **індекс (staging)** (`git add`) → **репозиторій** (`git commit`).\n\n## Щоденний процес\n\n```bash\ngit switch -c feature/search      # нова гілка від поточного коміту\ngit add -p                        # інтерактивно додати фрагменти в індекс\ngit commit -m \"feat: add search box\"\ngit fetch origin\ngit rebase origin/main            # перенести ваші коміти на свіжий main\ngit push -u origin feature/search # відкрити pull request\n```\n\nРобіть невеликі сфокусовані коміти з повідомленнями, що пояснюють **чому**. Conventional Commits (`feat:`, `fix:`) допомагають зі списками змін.\n\n## Merge проти rebase\n\n- **Merge** об''єднує історії комітом злиття. Він нічого не руйнує й точно показує, що сталося, але історія може стати захаращеною.\n- **Rebase** відтворює ваші коміти поверх іншої гілки. Історія стає лінійною, але коміти отримують **нові хеші**.\n\nЗолоте правило: **не робіть rebase комітів, які вже є в інших** (спільні/публічні гілки). Rebase власної локальної гілки перед PR цілком нормальний. Squash-merge PR дає в `main` один коміт на функцію.\n\n## Конфлікти\n\nКонфлікти виникають, коли обидві сторони змінили ті самі рядки. Git позначає їх:\n\n```\n<<<<<<< HEAD\nconst limit = 10;\n=======\nconst limit = 20;\n>>>>>>> feature\n```\n\nВизначте правильний код (він може поєднувати обидві сторони), приберіть маркери, запустіть тести, потім `git add` і продовжте операцію (`git merge --continue` або `git rebase --continue`).\n\n## Скасування змін\n\n| Ситуація | Команда |\n| --- | --- |\n| Відкинути неіндексовані зміни у файлі | `git restore file` |\n| Прибрати файл з індексу | `git restore --staged file` |\n| Виправити останній коміт (ще не відправлений) | `git commit --amend` |\n| Безпечно скасувати відправлений коміт | `git revert <sha>` (створює обернений коміт) |\n| Повернути гілку назад, зберігши зміни | `git reset --soft HEAD~1` |\n| Викинути коміти **локально** | `git reset --hard <sha>` (небезпечно) |\n| «Я втратив коміт!» | `git reflog`, потім гілка від старого sha |\n\n`revert` безпечний для спільної історії. `reset` її переписує. `git stash` тимчасово відкладає незавершену роботу.\n\n## Пошук помилок\n\n`git bisect` бінарним пошуком знаходить в історії коміт, що вніс помилку. `git blame` (або `git log -p -S \"text\"`) показує, коли й чому змінився рядок.\n\n## Чек-лист для співбесіди\n\n- Поясніть різницю між merge і rebase та золоте правило rebase.\n- Розв''яжіть конфлікт і продовжте операцію.\n- Оберіть між `revert` і `reset` та відновіться через `reflog`.\n- Опишіть процес роботи з гілками й PR у вашій команді."}'::jsonb, 7),
  ('html', 'html', '{"en":"Semantic HTML: structure, forms and the parsing model","uk":"Семантичний HTML: структура, форми та модель розбору"}'::jsonb, '{"en":"Why the right element matters, document landmarks, accessible forms, and how browsers parse and load HTML, scripts and styles.","uk":"Чому важливий правильний елемент, орієнтири документа, доступні форми та як браузер розбирає й завантажує HTML, скрипти й стилі."}'::jsonb, '{"en":"HTML gives content meaning. Browsers, search engines and assistive technology all read that meaning, so choosing the right element is a feature, not decoration.\n\n## Semantic structure\n\n```html\n<header>…logo, site navigation…</header>\n<nav aria-label=\"Main\">…</nav>\n<main>\n  <article>\n    <h1>Page title</h1>\n    <section aria-labelledby=\"pricing\">\n      <h2 id=\"pricing\">Pricing</h2>\n    </section>\n  </article>\n  <aside>…related links…</aside>\n</main>\n<footer>…</footer>\n```\n\n- Use **one `<h1>`** per page and don''t skip heading levels: screen-reader users navigate by headings.\n- Landmarks (`header`, `nav`, `main`, `aside`, `footer`) let users jump between regions.\n- Use `<button>` for actions and `<a href>` for navigation. A `<div onclick>` isn''t focusable, has no role and ignores Enter/Space.\n- Use `<ul>`/`<ol>` for lists, `<table>` with `<th scope>` for tabular data (never for layout), and `<time datetime>` for dates.\n\n## Forms\n\n```html\n<form>\n  <label for=\"email\">Email</label>\n  <input id=\"email\" name=\"email\" type=\"email\" autocomplete=\"email\" required\n         aria-describedby=\"email-hint\" />\n  <p id=\"email-hint\">We''ll never share it.</p>\n\n  <fieldset>\n    <legend>Plan</legend>\n    <label><input type=\"radio\" name=\"plan\" value=\"free\" /> Free</label>\n    <label><input type=\"radio\" name=\"plan\" value=\"pro\" /> Pro</label>\n  </fieldset>\n\n  <button type=\"submit\">Sign up</button>\n</form>\n```\n\n- Every control needs a **label**. A placeholder is not a label: it disappears as you type.\n- The right `type` (`email`, `tel`, `number`, `date`) brings mobile keyboards and built-in validation. `autocomplete` speeds up filling.\n- `<button>` inside a form defaults to `type=\"submit\"`, so give other buttons `type=\"button\"`.\n- Group related radios and checkboxes with `<fieldset>` and `<legend>`.\n\n## How the browser loads a page\n\n1. HTML is parsed top to bottom into the DOM.\n2. A classic `<script>` **blocks parsing** until it is downloaded and executed.\n3. `<script defer>` downloads in parallel and runs after parsing, in order. `<script async>` runs as soon as it''s downloaded, in any order. `type=\"module\"` scripts are deferred by default.\n4. CSS blocks **rendering** (not parsing), because the browser needs styles before painting.\n\nPut critical CSS in the head, use `defer` for app scripts, and lazy-load below-the-fold images with `loading=\"lazy\"`.\n\n## Metadata that matters\n\n`<html lang>`, `<meta charset=\"utf-8\">`, `<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">`, a unique `<title>` and meta description, plus `alt` text on every meaningful image (`alt=\"\"` for decorative ones).\n\n## Interview checklist\n\n- Replace clickable divs with buttons and links, and explain why.\n- Build a labelled form with correct input types.\n- Explain `defer` vs `async`.\n- Describe landmarks and heading order for accessibility and SEO.","uk":"HTML надає вмісту значення. Браузери, пошукові системи й допоміжні технології читають це значення, тож вибір правильного елемента є функцією, а не прикрасою.\n\n## Семантична структура\n\n```html\n<header>…логотип, навігація сайту…</header>\n<nav aria-label=\"Main\">…</nav>\n<main>\n  <article>\n    <h1>Заголовок сторінки</h1>\n    <section aria-labelledby=\"pricing\">\n      <h2 id=\"pricing\">Ціни</h2>\n    </section>\n  </article>\n  <aside>…пов''язані посилання…</aside>\n</main>\n<footer>…</footer>\n```\n\n- Використовуйте **один `<h1>`** на сторінку й не пропускайте рівні заголовків: користувачі зчитувачів екрана переміщуються саме заголовками.\n- Орієнтири (`header`, `nav`, `main`, `aside`, `footer`) дозволяють перестрибувати між частинами сторінки.\n- `<button>` для дій, `<a href>` для навігації. `<div onclick>` не отримує фокус, не має ролі й ігнорує Enter/Space.\n- `<ul>`/`<ol>` для списків, `<table>` з `<th scope>` для табличних даних (ніколи для верстки), `<time datetime>` для дат.\n\n## Форми\n\n```html\n<form>\n  <label for=\"email\">Email</label>\n  <input id=\"email\" name=\"email\" type=\"email\" autocomplete=\"email\" required\n         aria-describedby=\"email-hint\" />\n  <p id=\"email-hint\">Ми нікому його не передамо.</p>\n\n  <fieldset>\n    <legend>Тариф</legend>\n    <label><input type=\"radio\" name=\"plan\" value=\"free\" /> Free</label>\n    <label><input type=\"radio\" name=\"plan\" value=\"pro\" /> Pro</label>\n  </fieldset>\n\n  <button type=\"submit\">Зареєструватися</button>\n</form>\n```\n\n- Кожне поле потребує **мітки (label)**. Placeholder не є міткою: він зникає під час введення.\n- Правильний `type` (`email`, `tel`, `number`, `date`) дає потрібну мобільну клавіатуру й вбудовану валідацію. `autocomplete` пришвидшує заповнення.\n- `<button>` усередині форми за замовчуванням має `type=\"submit\"`, тож іншим кнопкам задавайте `type=\"button\"`.\n- Групуйте пов''язані радіокнопки й чекбокси через `<fieldset>` і `<legend>`.\n\n## Як браузер завантажує сторінку\n\n1. HTML розбирається згори донизу в DOM.\n2. Звичайний `<script>` **блокує розбір**, доки його не завантажено й не виконано.\n3. `<script defer>` завантажується паралельно й виконується після розбору, по порядку. `<script async>` виконується щойно завантажиться, у довільному порядку. Скрипти `type=\"module\"` за замовчуванням відкладені.\n4. CSS блокує **відмальовування** (не розбір), бо браузеру потрібні стилі перед малюванням.\n\nКритичний CSS розміщуйте в head, для скриптів застосунку використовуйте `defer`, а зображення нижче першого екрана завантажуйте ліниво через `loading=\"lazy\"`.\n\n## Метадані, що мають значення\n\n`<html lang>`, `<meta charset=\"utf-8\">`, `<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">`, унікальні `<title>` і meta description, а також текст `alt` для кожного змістовного зображення (`alt=\"\"` для декоративних).\n\n## Чек-лист для співбесіди\n\n- Замініть клікабельні div на кнопки й посилання та поясніть чому.\n- Побудуйте форму з мітками й правильними типами полів.\n- Поясніть різницю між `defer` і `async`.\n- Опишіть орієнтири й порядок заголовків для доступності та SEO."}'::jsonb, 7),
  ('http-rest', 'http-rest', '{"en":"HTTP and REST: methods, status codes, caching and CORS","uk":"HTTP і REST: методи, коди стану, кешування та CORS"}'::jsonb, '{"en":"The HTTP knowledge every web developer needs: idempotency, status codes, caching headers, CORS preflights and RESTful API design.","uk":"Знання HTTP, потрібні кожному веброзробнику: ідемпотентність, коди стану, заголовки кешування, CORS preflight і проєктування RESTful API."}'::jsonb, '{"en":"Every frontend talks to a backend over HTTP, and every backend interview touches REST. The questions are mostly about semantics: what each piece of the protocol promises.\n\n## Methods\n\n| Method | Use | Safe | Idempotent |\n| --- | --- | --- | --- |\n| GET | read a resource | ✓ | ✓ |\n| HEAD | headers only | ✓ | ✓ |\n| POST | create / run an action | ✗ | ✗ |\n| PUT | replace a resource completely | ✗ | ✓ |\n| PATCH | partial update | ✗ | ✗ (usually) |\n| DELETE | remove | ✗ | ✓ |\n\n**Safe** means \"doesn''t change state\". **Idempotent** means \"doing it twice has the same effect as once\", which is what makes retries safe. For retried POSTs (payments), use an **idempotency key** header.\n\n## Status codes\n\n- **2xx success**: `200 OK`, `201 Created` (with `Location`), `204 No Content`.\n- **3xx redirects**: `301`/`308` permanent, `302`/`307` temporary (307/308 keep the method), `304 Not Modified` (cache revalidation).\n- **4xx client errors**: `400` malformed, `401` not authenticated, `403` authenticated but not allowed, `404` not found, `409` conflict, `422` validation failed, `429` too many requests.\n- **5xx server errors**: `500`, `502` bad gateway, `503` unavailable (with `Retry-After`), `504` gateway timeout.\n\n## REST design\n\nResources are nouns, and methods are the verbs:\n\n```\nGET    /users?role=admin&page=2     list (filter, paginate)\nPOST   /users                       create → 201 + Location: /users/42\nGET    /users/42                    read\nPATCH  /users/42                    update fields\nDELETE /users/42                    delete → 204\nGET    /users/42/orders             sub-resource\n```\n\nKeep it stateless (each request carries its own auth), version the API (`/v1` or a header), and return consistent error bodies, for example RFC 9457 problem details.\n\n## Caching\n\n- `Cache-Control: max-age=3600` lets clients reuse a response for an hour. `no-cache` means revalidate before every use; `no-store` means never store it. Use `private` for user-specific data and `public, immutable` for fingerprinted assets.\n- Validators: `ETag` + `If-None-Match`, or `Last-Modified` + `If-Modified-Since`, let the server answer `304 Not Modified` without a body.\n\n## CORS\n\nBrowsers block JavaScript from reading responses from **another origin** (scheme + host + port) unless the server opts in with `Access-Control-Allow-Origin`.\n\n- **Simple requests** (GET/POST with simple headers) are sent directly, and the browser checks the response headers.\n- Others (PUT, JSON `Content-Type`, `Authorization`) trigger a **preflight** `OPTIONS` request first. The server must answer with the allowed methods and headers.\n- Credentials (cookies) require `Access-Control-Allow-Credentials: true` and an explicit origin, not `*`.\n\nCORS protects users'' data in their browser. It is not a server-side security boundary: curl ignores it.\n\n## HTTP/2 and HTTP/3\n\nThey multiplex many requests over one connection and compress headers. HTTP/3 runs on QUIC (UDP). Domain sharding and sprite sheets are no longer needed.\n\n## Interview checklist\n\n- Explain safe vs idempotent, and why PUT is idempotent but POST isn''t.\n- Pick the right status code (401 vs 403, 400 vs 422).\n- Design a REST endpoint with pagination and errors.\n- Explain a CORS preflight and how to fix a CORS error properly (on the server).","uk":"Кожен фронтенд спілкується з бекендом через HTTP, а кожна бекенд-співбесіда торкається REST. Питання здебільшого стосуються семантики: що обіцяє кожна частина протоколу.\n\n## Методи\n\n| Метод | Використання | Безпечний | Ідемпотентний |\n| --- | --- | --- | --- |\n| GET | читання ресурсу | ✓ | ✓ |\n| HEAD | лише заголовки | ✓ | ✓ |\n| POST | створення / виконання дії | ✗ | ✗ |\n| PUT | повна заміна ресурсу | ✗ | ✓ |\n| PATCH | часткове оновлення | ✗ | ✗ (зазвичай) |\n| DELETE | видалення | ✗ | ✓ |\n\n**Безпечний** означає «не змінює стан». **Ідемпотентний** означає «повторне виконання має той самий ефект, що й одне», і саме це робить повторні спроби безпечними. Для повторюваних POST-запитів (платежі) використовуйте заголовок **ключа ідемпотентності**.\n\n## Коди стану\n\n- **2xx успіх**: `200 OK`, `201 Created` (з `Location`), `204 No Content`.\n- **3xx переспрямування**: `301`/`308` постійні, `302`/`307` тимчасові (307/308 зберігають метод), `304 Not Modified` (перевірка кешу).\n- **4xx помилки клієнта**: `400` некоректний запит, `401` не автентифіковано, `403` автентифіковано, але заборонено, `404` не знайдено, `409` конфлікт, `422` валідація не пройшла, `429` забагато запитів.\n- **5xx помилки сервера**: `500`, `502` bad gateway, `503` недоступний (з `Retry-After`), `504` gateway timeout.\n\n## Проєктування REST\n\nРесурси є іменниками, а методи є дієсловами:\n\n```\nGET    /users?role=admin&page=2     список (фільтр, пагінація)\nPOST   /users                       створення → 201 + Location: /users/42\nGET    /users/42                    читання\nPATCH  /users/42                    оновлення полів\nDELETE /users/42                    видалення → 204\nGET    /users/42/orders             вкладений ресурс\n```\n\nТримайте API без стану (кожен запит несе власну автентифікацію), версіонуйте його (`/v1` або заголовок) і повертайте узгоджені тіла помилок, наприклад problem details за RFC 9457.\n\n## Кешування\n\n- `Cache-Control: max-age=3600` дозволяє клієнтам повторно використовувати відповідь годину. `no-cache` означає перевіряти перед кожним використанням; `no-store` означає ніколи не зберігати. Для даних конкретного користувача використовуйте `private`, для ресурсів з відбитком у назві `public, immutable`.\n- Валідатори: `ETag` + `If-None-Match` або `Last-Modified` + `If-Modified-Since` дозволяють серверу відповісти `304 Not Modified` без тіла.\n\n## CORS\n\nБраузери не дають JavaScript читати відповіді з **іншого джерела** (схема + хост + порт), якщо сервер не дозволив цього заголовком `Access-Control-Allow-Origin`.\n\n- **Прості запити** (GET/POST з простими заголовками) надсилаються одразу, а браузер перевіряє заголовки відповіді.\n- Інші (PUT, `Content-Type` JSON, `Authorization`) спершу викликають **preflight**-запит `OPTIONS`. Сервер має відповісти дозволеними методами й заголовками.\n- Облікові дані (cookies) вимагають `Access-Control-Allow-Credentials: true` і явного джерела, а не `*`.\n\nCORS захищає дані користувачів у їхньому браузері. Це не межа безпеки на сервері: curl його ігнорує.\n\n## HTTP/2 і HTTP/3\n\nВони мультиплексують багато запитів в одному з''єднанні й стискають заголовки. HTTP/3 працює поверх QUIC (UDP). Шардинг доменів і спрайти більше не потрібні.\n\n## Чек-лист для співбесіди\n\n- Поясніть різницю між безпечним та ідемпотентним методом і чому PUT ідемпотентний, а POST ні.\n- Обирайте правильний код стану (401 проти 403, 400 проти 422).\n- Спроєктуйте REST-ендпоінт з пагінацією та помилками.\n- Поясніть CORS preflight і як правильно виправити помилку CORS (на сервері)."}'::jsonb, 8),
  ('javascript', 'javascript', '{"en":"JavaScript essentials: types, equality, this and prototypes","uk":"Основи JavaScript: типи, рівність, this і прототипи"}'::jsonb, '{"en":"The language rules interviewers probe first: primitive vs reference values, coercion, == vs ===, how `this` is bound and how prototypes work.","uk":"Правила мови, які інтерв''юери перевіряють першими: примітиви й посилальні значення, приведення типів, == проти ===, прив''язка `this` і прототипи."}'::jsonb, '{"en":"JavaScript interviews usually start with the fundamentals, because every bug you will ever debug traces back to them.\n\n## Values and types\n\nThere are seven primitive types: `string`, `number`, `bigint`, `boolean`, `undefined`, `symbol` and `null`. Everything else is an **object**: arrays, functions, dates and maps included.\n\n- Primitives are immutable and compared **by value**.\n- Objects are compared **by reference**: `{} === {}` is `false`, because they are two different objects.\n\n```js\nconst a = { n: 1 };\nconst b = a;      // same reference\nb.n = 2;\nconsole.log(a.n); // 2\n```\n\n`typeof null === \"object\"` is a historical bug. Check `value === null` explicitly, and use `Array.isArray` for arrays.\n\n## Equality and coercion\n\n`===` compares type and value without conversion. `==` first coerces both sides with a complicated algorithm:\n\n```js\n0 == \"\";        // true\nnull == undefined; // true (and nothing else is == null)\n[] == false;    // true\nNaN === NaN;    // false: use Number.isNaN or Object.is\n```\n\nUse `===` everywhere. The one common exception is `value == null`, which checks for both `null` and `undefined`.\n\n**Truthiness**: only `false`, `0`, `-0`, `0n`, `\"\"`, `null`, `undefined` and `NaN` are falsy. `[]` and `{}` are truthy.\n\n## `let`, `const` and `var`\n\n- `var` is function-scoped and hoisted with the value `undefined`.\n- `let` and `const` are block-scoped. Reading them before their declaration throws (the *temporal dead zone*).\n- `const` prevents reassignment, not mutation: `const arr = []; arr.push(1)` is fine.\n\n## How `this` is bound\n\n`this` is decided by **how a function is called**, not where it is defined:\n\n| Call | `this` |\n| --- | --- |\n| `obj.method()` | `obj` |\n| `fn()` | `undefined` in strict mode (the global object otherwise) |\n| `fn.call(x)` / `fn.apply(x)` / `fn.bind(x)()` | `x` |\n| `new Fn()` | the new object |\n| arrow function | `this` of the enclosing scope (lexical) |\n\nA classic bug is passing a method as a callback: `setTimeout(obj.method)` loses `obj`. Fix it with `obj.method.bind(obj)` or an arrow function.\n\n## Prototypes\n\nEvery object has a hidden link (`[[Prototype]]`) to another object. Property lookups walk this chain:\n\n```js\nconst animal = { speak() { return `${this.name} makes a sound`; } };\nconst dog = Object.create(animal);\ndog.name = \"Rex\";\ndog.speak(); // \"Rex makes a sound\": found on the prototype, this === dog\n```\n\n`class` syntax is sugar over the same mechanism: methods live on `Class.prototype`, and `extends` links two prototype chains.\n\n## Interview checklist\n\n- Explain primitive vs reference semantics with an example of mutation.\n- Never rely on `==` coercion; know `== null` as the only idiom.\n- Predict `this` from the call site, and know how arrow functions differ.\n- Draw the prototype chain for a `class` that extends another.","uk":"Співбесіди з JavaScript зазвичай починаються з основ, адже кожен баг, який вам доведеться шукати, зрештою зводиться до них.\n\n## Значення та типи\n\nУ мові сім примітивних типів: `string`, `number`, `bigint`, `boolean`, `undefined`, `symbol` і `null`. Усе інше є **об''єктами**, зокрема масиви, функції, дати й Map.\n\n- Примітиви незмінні й порівнюються **за значенням**.\n- Об''єкти порівнюються **за посиланням**: `{} === {}` дає `false`, бо це два різні об''єкти.\n\n```js\nconst a = { n: 1 };\nconst b = a;      // те саме посилання\nb.n = 2;\nconsole.log(a.n); // 2\n```\n\n`typeof null === \"object\"` є історичною помилкою мови. Перевіряйте `value === null` явно, а для масивів використовуйте `Array.isArray`.\n\n## Рівність і приведення типів\n\n`===` порівнює тип і значення без перетворень. `==` спершу приводить обидва боки за складним алгоритмом:\n\n```js\n0 == \"\";        // true\nnull == undefined; // true (і більше ніщо не дорівнює null через ==)\n[] == false;    // true\nNaN === NaN;    // false: використовуйте Number.isNaN або Object.is\n```\n\nВикористовуйте `===` скрізь. Єдиний поширений виняток: `value == null`, що перевіряє і `null`, і `undefined`.\n\n**Хибні значення (falsy)**: лише `false`, `0`, `-0`, `0n`, `\"\"`, `null`, `undefined` і `NaN`. `[]` і `{}` є істинними.\n\n## `let`, `const` і `var`\n\n- `var` має область видимості функції й піднімається (hoisting) зі значенням `undefined`.\n- `let` і `const` мають блокову область видимості. Звернення до них до оголошення кидає помилку (*temporal dead zone*).\n- `const` забороняє перевизначення, але не зміну: `const arr = []; arr.push(1)` працює.\n\n## Як визначається `this`\n\n`this` залежить від того, **як функцію викликано**, а не де її оголошено:\n\n| Виклик | `this` |\n| --- | --- |\n| `obj.method()` | `obj` |\n| `fn()` | `undefined` у strict mode (інакше глобальний об''єкт) |\n| `fn.call(x)` / `fn.apply(x)` / `fn.bind(x)()` | `x` |\n| `new Fn()` | новий об''єкт |\n| стрілкова функція | `this` зовнішньої області (лексичний) |\n\nКласична помилка: передати метод як колбек. `setTimeout(obj.method)` втрачає `obj`. Виправлення: `obj.method.bind(obj)` або стрілкова функція.\n\n## Прототипи\n\nКожен об''єкт має приховане посилання (`[[Prototype]]`) на інший об''єкт. Пошук властивостей іде цим ланцюжком:\n\n```js\nconst animal = { speak() { return `${this.name} makes a sound`; } };\nconst dog = Object.create(animal);\ndog.name = \"Rex\";\ndog.speak(); // \"Rex makes a sound\": знайдено в прототипі, this === dog\n```\n\nСинтаксис `class` є «цукром» над тим самим механізмом: методи живуть у `Class.prototype`, а `extends` з''єднує два ланцюжки прототипів.\n\n## Чек-лист для співбесіди\n\n- Поясніть різницю між примітивами й посилальними значеннями на прикладі мутації.\n- Не покладайтеся на приведення в `==`; знайте `== null` як єдину ідіому.\n- Визначайте `this` за місцем виклику й пам''ятайте, чим відрізняються стрілкові функції.\n- Намалюйте ланцюжок прототипів для класу, що наслідує інший клас."}'::jsonb, 8),
  ('nodejs', 'nodejs', '{"en":"Node.js essentials: the event loop, streams and the runtime","uk":"Основи Node.js: цикл подій, потоки й середовище виконання"}'::jsonb, '{"en":"How Node.js runs JavaScript on the server, its event loop phases, non-blocking I/O, streams and backpressure, modules, error handling and scaling across cores.","uk":"Як Node.js виконує JavaScript на сервері, фази циклу подій, неблокувальний ввід-вивід, потоки й зворотний тиск, модулі, обробка помилок і масштабування на кілька ядер."}'::jsonb, '{"en":"Node.js runs JavaScript outside the browser on V8, with **libuv** providing an event loop, a thread pool and non-blocking I/O. Frontend developers meet it in tooling, SSR (Next.js) and BFF APIs.\n\n## Non-blocking I/O\n\nNode handles thousands of connections on one JavaScript thread because I/O doesn''t block: it starts the operation, registers a callback, and keeps serving other requests. The flip side: **CPU-heavy work blocks everyone**. A 2-second JSON transform freezes every request.\n\n```js\nconst data = fs.readFileSync(\"big.json\");        // ✗ blocks the event loop\nconst data = await fs.promises.readFile(\"big.json\"); // ✓ non-blocking\n```\n\nOffload CPU work to **worker threads**, a separate service or a queue.\n\n## Event loop phases\n\nlibuv cycles through phases: **timers** (`setTimeout`/`setInterval`) → pending callbacks → **poll** (I/O) → **check** (`setImmediate`) → close callbacks. Between callbacks, Node drains microtasks: `process.nextTick` first, then promise callbacks.\n\n```js\nsetTimeout(() => console.log(\"timeout\"), 0);\nsetImmediate(() => console.log(\"immediate\"));\nPromise.resolve().then(() => console.log(\"promise\"));\nprocess.nextTick(() => console.log(\"nextTick\"));\n// nextTick, promise, then timeout/immediate (their order varies in the main module)\n```\n\nRecursive `process.nextTick` can starve I/O, so prefer `setImmediate` to yield.\n\n## Modules\n\nNode supports **CommonJS** (`require`, `module.exports`) and **ES modules** (`import`, `\"type\": \"module\"` or `.mjs`). ESM can `import` CJS; CJS loads ESM via dynamic `import()` (newer versions also support `require` of synchronous ESM). Built-ins use the `node:` prefix: `import fs from \"node:fs/promises\"`.\n\n## Streams and backpressure\n\nStreams process data in chunks instead of loading everything into memory:\n\n```js\nimport { pipeline } from \"node:stream/promises\";\nawait pipeline(fs.createReadStream(\"in.log\"), zlib.createGzip(), fs.createWriteStream(\"in.log.gz\"));\n```\n\n`pipeline` handles **backpressure** (pausing a fast reader when the writer is slow) and propagates errors and cleanup. Manual `.pipe()` chains don''t forward errors.\n\n## Error handling\n\n- Async/await with `try/catch`; always handle promise rejections. An unhandled rejection crashes the process in modern Node.\n- Operational errors (network down, invalid input) should be handled. Programmer errors (bugs) should crash and restart via a process manager.\n- `EventEmitter` \"error\" events without a listener throw.\n\n## Using all CPU cores\n\nOne Node process uses one core for JavaScript. Scale with multiple processes (the `cluster` module, PM2, containers behind a load balancer) and keep processes stateless, with sessions in Redis or a database.\n\n## Configuration and security\n\nRead config from environment variables (`process.env`), validate it at startup, never log secrets, keep dependencies updated (`npm audit`), and set timeouts on outbound requests.\n\n## Interview checklist\n\n- Explain why Node is fast for I/O and slow for CPU-bound work.\n- Order `nextTick`, promises, timers and `setImmediate`.\n- Stream large files with `pipeline` and explain backpressure.\n- Describe how to scale across cores and handle errors safely.","uk":"Node.js виконує JavaScript поза браузером на V8, а **libuv** забезпечує цикл подій, пул потоків і неблокувальний ввід-вивід. Фронтенд-розробники стикаються з ним в інструментах, SSR (Next.js) і BFF API.\n\n## Неблокувальний ввід-вивід\n\nNode обслуговує тисячі з''єднань в одному потоці JavaScript, бо ввід-вивід не блокує: він запускає операцію, реєструє колбек і продовжує обслуговувати інші запити. Зворотний бік: **CPU-важка робота блокує всіх**. Перетворення JSON на 2 секунди заморожує кожен запит.\n\n```js\nconst data = fs.readFileSync(\"big.json\");        // ✗ блокує цикл подій\nconst data = await fs.promises.readFile(\"big.json\"); // ✓ неблокувально\n```\n\nВиносьте CPU-роботу у **worker threads**, окремий сервіс або чергу.\n\n## Фази циклу подій\n\nlibuv проходить фази по колу: **timers** (`setTimeout`/`setInterval`) → pending callbacks → **poll** (ввід-вивід) → **check** (`setImmediate`) → close callbacks. Між колбеками Node виконує мікрозадачі: спершу `process.nextTick`, потім колбеки промісів.\n\n```js\nsetTimeout(() => console.log(\"timeout\"), 0);\nsetImmediate(() => console.log(\"immediate\"));\nPromise.resolve().then(() => console.log(\"promise\"));\nprocess.nextTick(() => console.log(\"nextTick\"));\n// nextTick, promise, далі timeout/immediate (їхній порядок у головному модулі може відрізнятися)\n```\n\nРекурсивний `process.nextTick` може «заморити голодом» ввід-вивід, тож щоб поступитися потоком, обирайте `setImmediate`.\n\n## Модулі\n\nNode підтримує **CommonJS** (`require`, `module.exports`) і **ES-модулі** (`import`, `\"type\": \"module\"` або `.mjs`). ESM може імпортувати CJS; CJS завантажує ESM через динамічний `import()` (нові версії також підтримують `require` синхронних ESM). Вбудовані модулі мають префікс `node:`: `import fs from \"node:fs/promises\"`.\n\n## Потоки й зворотний тиск\n\nПотоки (streams) обробляють дані частинами, а не завантажують усе в пам''ять:\n\n```js\nimport { pipeline } from \"node:stream/promises\";\nawait pipeline(fs.createReadStream(\"in.log\"), zlib.createGzip(), fs.createWriteStream(\"in.log.gz\"));\n```\n\n`pipeline` обробляє **зворотний тиск (backpressure)**: призупиняє швидкого читача, коли повільний записувач не встигає, а також передає помилки й прибирає ресурси. Ручні ланцюжки `.pipe()` помилок не передають.\n\n## Обробка помилок\n\n- Async/await з `try/catch`; завжди обробляйте відхилення промісів. Необроблене відхилення в сучасному Node завершує процес.\n- Операційні помилки (мережа недоступна, некоректний вхід) треба обробляти. Помилки програміста (баги) мають завершувати процес із перезапуском через менеджер процесів.\n- Подія \"error\" в `EventEmitter` без слухача кидає виняток.\n\n## Використання всіх ядер\n\nОдин процес Node використовує одне ядро для JavaScript. Масштабуйтеся кількома процесами (модуль `cluster`, PM2, контейнери за балансувальником) і тримайте процеси без стану, а сесії в Redis чи базі даних.\n\n## Конфігурація й безпека\n\nЧитайте конфігурацію зі змінних середовища (`process.env`), валідуйте її під час запуску, ніколи не логуйте секрети, оновлюйте залежності (`npm audit`) і задавайте тайм-аути для вихідних запитів.\n\n## Чек-лист для співбесіди\n\n- Поясніть, чому Node швидкий для вводу-виводу й повільний для CPU-задач.\n- Розставте по порядку `nextTick`, проміси, таймери та `setImmediate`.\n- Обробляйте великі файли потоково через `pipeline` і поясніть зворотний тиск.\n- Опишіть, як масштабуватися на кілька ядер і безпечно обробляти помилки."}'::jsonb, 8),
  ('react', 'react', '{"en":"React fundamentals: rendering, state, effects and keys","uk":"Основи React: рендеринг, стан, ефекти та ключі"}'::jsonb, '{"en":"What actually happens when state changes, why keys matter, when effects run, and how to avoid the most common hooks mistakes.","uk":"Що насправді відбувається, коли змінюється стан, навіщо потрібні ключі, коли виконуються ефекти та як уникнути типових помилок із хуками."}'::jsonb, '{"en":"React turns state into UI. Most interview questions test whether you understand **when** components render and **what** survives between renders.\n\n## Rendering is calling your function\n\nA component is a function from props and state to elements. React calls it again when:\n\n- its state changes (`setState` with a different value according to `Object.is`),\n- its parent re-renders (unless it is wrapped in `memo` and its props are shallow-equal),\n- a context it reads changes.\n\nRendering must be **pure**: no subscriptions, timers or mutations of outside variables during render. Side effects go into event handlers or effects.\n\n## State is a snapshot\n\n```tsx\nconst [count, setCount] = useState(0);\n\nfunction handleClick() {\n  setCount(count + 1);\n  setCount(count + 1); // still uses the same snapshot → count + 1, not + 2\n  setCount((c) => c + 1); // updater function → sees the latest queued value\n}\n```\n\nUpdates are **batched** and applied on the next render. Never mutate state objects: `items.push(x); setItems(items)` keeps the same reference and React may skip the render. Create a new array instead: `setItems([...items, x])`.\n\n## Effects synchronise with the outside world\n\n```tsx\nuseEffect(() => {\n  const id = setInterval(tick, 1000);\n  return () => clearInterval(id); // cleanup before re-run and on unmount\n}, [tick]);\n```\n\n- With no dependency array, the effect runs after every render. With `[]`, it runs after mount. With `[a, b]`, it runs when `a` or `b` changes.\n- List every reactive value you read. Missing dependencies cause stale closures.\n- You often **don''t need an effect**. Derive values during render (`const total = items.reduce(...)`) instead of copying them into state.\n\n## Lists and keys\n\nKeys tell React which item is which between renders:\n\n```tsx\n{todos.map((t) => <TodoRow key={t.id} todo={t} />)}\n```\n\nUsing the array index as a key breaks when items are inserted or reordered: state and DOM input values stick to the wrong rows. Use a stable ID.\n\n## Controlled inputs\n\nA controlled input takes its value from state and reports changes:\n\n```tsx\n<input value={query} onChange={(e) => setQuery(e.target.value)} />\n```\n\nDerive the filtered list from `query` during render. Don''t store it in a second piece of state.\n\n## Performance tools\n\n- `memo(Component)`: skip a re-render when props are shallow-equal.\n- `useMemo(fn, deps)`: cache an expensive calculation.\n- `useCallback(fn, deps)`: keep a stable function identity, for example for a memoised child.\n\nMeasure first. Unnecessary memoisation adds complexity and buys nothing.\n\n## Interview checklist\n\n- Explain the render → commit → effect order.\n- Use updater functions when the next state depends on the previous one.\n- Pick stable keys and explain what goes wrong with indexes.\n- Remove effects that only transform data; keep the ones that talk to the outside world.","uk":"React перетворює стан на інтерфейс. Більшість питань на співбесіді перевіряють, чи розумієте ви, **коли** компоненти рендеряться і **що** зберігається між рендерами.\n\n## Рендеринг — це виклик вашої функції\n\nКомпонент є функцією від пропсів і стану до елементів. React викликає її знову, коли:\n\n- змінюється її стан (`setState` зі значенням, відмінним за `Object.is`),\n- ререндериться батьківський компонент (якщо компонент не обгорнуто в `memo` і пропси не однакові поверхнево),\n- змінюється контекст, який вона читає.\n\nРендер має бути **чистим**: жодних підписок, таймерів чи змін зовнішніх змінних під час рендеру. Побічні ефекти розміщуйте в обробниках подій або ефектах.\n\n## Стан — це знімок\n\n```tsx\nconst [count, setCount] = useState(0);\n\nfunction handleClick() {\n  setCount(count + 1);\n  setCount(count + 1); // той самий знімок → count + 1, а не + 2\n  setCount((c) => c + 1); // функція-оновлювач бачить останнє значення в черзі\n}\n```\n\nОновлення **групуються (batching)** і застосовуються в наступному рендері. Ніколи не змінюйте об''єкти стану напряму: `items.push(x); setItems(items)` залишає те саме посилання, і React може пропустити рендер. Створюйте новий масив: `setItems([...items, x])`.\n\n## Ефекти синхронізують із зовнішнім світом\n\n```tsx\nuseEffect(() => {\n  const id = setInterval(tick, 1000);\n  return () => clearInterval(id); // очищення перед повторним запуском і при демонтуванні\n}, [tick]);\n```\n\n- Без масиву залежностей ефект виконується після кожного рендеру. З `[]` виконується після монтування. З `[a, b]` виконується, коли змінюється `a` або `b`.\n- Вказуйте кожне реактивне значення, яке читаєте. Пропущені залежності дають застарілі замикання.\n- Часто ефект **не потрібен**. Обчислюйте похідні значення під час рендеру (`const total = items.reduce(...)`), а не копіюйте їх у стан.\n\n## Списки та ключі\n\nКлючі підказують React, який елемент є яким між рендерами:\n\n```tsx\n{todos.map((t) => <TodoRow key={t.id} todo={t} />)}\n```\n\nІндекс масиву як ключ ламається, коли елементи вставляють чи переставляють: стан і значення полів «прилипають» до хибних рядків. Використовуйте стабільний ID.\n\n## Керовані поля\n\nКероване поле бере значення зі стану й повідомляє про зміни:\n\n```tsx\n<input value={query} onChange={(e) => setQuery(e.target.value)} />\n```\n\nФільтрований список обчислюйте з `query` під час рендеру. Не зберігайте його в окремому стані.\n\n## Інструменти продуктивності\n\n- `memo(Component)`: пропустити ререндер, коли пропси поверхнево однакові.\n- `useMemo(fn, deps)`: кешувати дороге обчислення.\n- `useCallback(fn, deps)`: зберегти стабільну функцію, наприклад для мемоізованого дочірнього компонента.\n\nСпершу вимірюйте. Зайва мемоізація ускладнює код і нічого не дає.\n\n## Чек-лист для співбесіди\n\n- Поясніть порядок render → commit → effect.\n- Використовуйте функції-оновлювачі, коли новий стан залежить від попереднього.\n- Обирайте стабільні ключі й поясніть, що ламається з індексами.\n- Прибирайте ефекти, які лише перетворюють дані; залишайте ті, що спілкуються із зовнішнім світом."}'::jsonb, 9),
  ('recursion', 'recursion', '{"en":"Recursion: base cases, trees, memoisation and backtracking","uk":"Рекурсія: базові випадки, дерева, мемоізація та пошук із поверненням"}'::jsonb, '{"en":"How to design recursive functions that terminate, when recursion beats loops, how to avoid exponential blow-ups and stack overflows.","uk":"Як проєктувати рекурсивні функції, що завершуються, коли рекурсія краща за цикли, як уникнути експоненційного вибуху й переповнення стеку."}'::jsonb, '{"en":"A recursive function solves a problem by solving smaller versions of the **same** problem. It''s the natural tool for trees, nested data and \"try every option\" searches.\n\n## The recipe\n\n1. **Base case**: the smallest input you can answer directly.\n2. **Recursive case**: shrink the problem and call yourself.\n3. **Combine**: build the answer from the sub-results.\n\n```js\nfunction sum(list) {\n  if (list.length === 0) return 0;          // base case\n  return list[0] + sum(list.slice(1));      // smaller problem + combine\n}\n```\n\nIf any path never reaches a base case, you get infinite recursion and eventually `RangeError: Maximum call stack size exceeded`.\n\n## Recursion fits nested data\n\n```js\nfunction flatten(value, depth = Infinity) {\n  if (!Array.isArray(value)) return [value];\n  if (depth === 0) return [value];\n  return value.flatMap((item) => (Array.isArray(item) ? flatten(item, depth - 1) : [item]));\n}\n```\n\nTrees (DOM nodes, JSON, file systems, menus) are recursive by nature: process the node, then recurse into its children.\n\n## Exponential traps and memoisation\n\nThe naive Fibonacci recomputes the same values over and over:\n\n```js\nconst fib = (n) => (n < 2 ? n : fib(n - 1) + fib(n - 2)); // O(2^n)\n```\n\nCache the results (**memoisation**) to make it O(n). Or flip it into a bottom-up loop, which is dynamic programming:\n\n```js\nfunction fibMemo(n, memo = new Map()) {\n  if (n < 2) return n;\n  if (!memo.has(n)) memo.set(n, fibMemo(n - 1, memo) + fibMemo(n - 2, memo));\n  return memo.get(n);\n}\n```\n\n## Backtracking\n\nTry a choice, recurse, then **undo** it. This generates permutations, subsets and solves puzzles:\n\n```js\nfunction permutations(items) {\n  const out = [], current = [], used = new Array(items.length).fill(false);\n  (function go() {\n    if (current.length === items.length) return void out.push([...current]);\n    for (let i = 0; i < items.length; i++) {\n      if (used[i]) continue;\n      used[i] = true; current.push(items[i]);\n      go();\n      current.pop(); used[i] = false;            // undo\n    }\n  })();\n  return out;\n}\n```\n\n## Stack depth\n\nEach call uses a stack frame. JavaScript engines have no general tail-call optimisation, so recursion depth is limited (often around 10k frames). For very deep inputs, such as a 100k-long linked list, convert the recursion to a loop with an explicit stack.\n\n## Interview checklist\n\n- State the base case first and prove the input shrinks.\n- Spot overlapping sub-problems and add memoisation.\n- Explain the time complexity by counting the calls.\n- Know when to convert to iteration to avoid stack overflow.","uk":"Рекурсивна функція розв''язує задачу через розв''язання менших версій **тієї самої** задачі. Це природний інструмент для дерев, вкладених даних і пошуку «перебрати всі варіанти».\n\n## Рецепт\n\n1. **Базовий випадок**: найменший вхід, на який можна відповісти одразу.\n2. **Рекурсивний крок**: зменшити задачу й викликати себе.\n3. **Поєднання**: зібрати відповідь із підрезультатів.\n\n```js\nfunction sum(list) {\n  if (list.length === 0) return 0;          // базовий випадок\n  return list[0] + sum(list.slice(1));      // менша задача + поєднання\n}\n```\n\nЯкщо якийсь шлях ніколи не доходить до базового випадку, рекурсія стає нескінченною, і зрештою ви отримаєте `RangeError: Maximum call stack size exceeded`.\n\n## Рекурсія для вкладених даних\n\n```js\nfunction flatten(value, depth = Infinity) {\n  if (!Array.isArray(value)) return [value];\n  if (depth === 0) return [value];\n  return value.flatMap((item) => (Array.isArray(item) ? flatten(item, depth - 1) : [item]));\n}\n```\n\nДерева (вузли DOM, JSON, файлові системи, меню) рекурсивні за природою: обробіть вузол, потім рекурсивно його дочірні вузли.\n\n## Експоненційні пастки й мемоізація\n\nНаївне Фібоначчі обчислює ті самі значення знову й знову:\n\n```js\nconst fib = (n) => (n < 2 ? n : fib(n - 1) + fib(n - 2)); // O(2^n)\n```\n\nКешуйте результати (**мемоізація**), щоб отримати O(n). Або переверніть рекурсію в цикл «знизу вгору», тобто динамічне програмування:\n\n```js\nfunction fibMemo(n, memo = new Map()) {\n  if (n < 2) return n;\n  if (!memo.has(n)) memo.set(n, fibMemo(n - 1, memo) + fibMemo(n - 2, memo));\n  return memo.get(n);\n}\n```\n\n## Пошук із поверненням (backtracking)\n\nСпробуйте варіант, зробіть рекурсивний виклик, потім **скасуйте** вибір. Так генерують перестановки й підмножини та розв''язують головоломки:\n\n```js\nfunction permutations(items) {\n  const out = [], current = [], used = new Array(items.length).fill(false);\n  (function go() {\n    if (current.length === items.length) return void out.push([...current]);\n    for (let i = 0; i < items.length; i++) {\n      if (used[i]) continue;\n      used[i] = true; current.push(items[i]);\n      go();\n      current.pop(); used[i] = false;            // скасування\n    }\n  })();\n  return out;\n}\n```\n\n## Глибина стеку\n\nКожен виклик займає кадр стеку. У рушіях JavaScript немає загальної оптимізації хвостових викликів, тож глибина рекурсії обмежена (часто близько 10 тис. кадрів). Для дуже глибоких входів, як-от зв''язного списку довжиною 100 тис., перетворіть рекурсію на цикл з явним стеком.\n\n## Чек-лист для співбесіди\n\n- Спершу назвіть базовий випадок і доведіть, що вхід зменшується.\n- Помічайте підзадачі, що перекриваються, і додавайте мемоізацію.\n- Пояснюйте складність, рахуючи кількість викликів.\n- Знайте, коли перейти до ітерації, щоб уникнути переповнення стеку."}'::jsonb, 7),
  ('rxjs', 'rxjs', '{"en":"RxJS: observables, operators and higher-order mapping","uk":"RxJS: observable, оператори й відображення вищого порядку"}'::jsonb, '{"en":"Observables vs promises, cold vs hot streams, Subjects, the four flattening operators, and how to avoid leaks with proper unsubscription.","uk":"Observable проти промісів, холодні й гарячі потоки, Subject, чотири оператори «сплющення» і як уникнути витоків через правильну відписку."}'::jsonb, '{"en":"RxJS models values over time as **observables**. It''s central to Angular (HttpClient, forms, router) and handy anywhere events, timers and requests interact.\n\n## Observable vs promise\n\n| | Promise | Observable |\n| --- | --- | --- |\n| Values | one | zero to many |\n| Laziness | starts immediately | starts on `subscribe` |\n| Cancellation | no (AbortController aside) | `unsubscribe()` |\n| Operators | `then`/`catch` | dozens: `map`, `filter`, `debounceTime`… |\n\n```ts\nconst ticks$ = interval(1000).pipe(take(3), map((n) => n * 10));\nconst sub = ticks$.subscribe({ next: console.log, complete: () => console.log(\"done\") });\n// 0, 10, 20, done\n```\n\n## Cold vs hot\n\n- **Cold** observables (`of`, `interval`, `HttpClient.get`) start a new producer for **each** subscriber. Two `async` pipes on one HTTP observable mean two requests.\n- **Hot** observables (DOM events, Subjects) share one producer.\n- `share()` / `shareReplay({ bufferSize: 1, refCount: true })` turn cold into shared.\n\n## Subjects\n\nA Subject is both observable and observer: you `next()` values into it.\n\n- `Subject`: no initial value, and late subscribers miss past values.\n- `BehaviorSubject`: has a current value, and new subscribers get it immediately. A simple store.\n- `ReplaySubject(n)`: replays the last n values.\n\nExpose `subject.asObservable()` publicly, so outsiders can''t push values.\n\n## Higher-order mapping: the key interview topic\n\nWhen each value starts an inner observable (often a request), choose how to flatten:\n\n| Operator | Behaviour | Typical use |\n| --- | --- | --- |\n| `switchMap` | cancels the previous inner observable | typeahead search, route params |\n| `mergeMap` | runs all in parallel | independent saves, analytics |\n| `concatMap` | queues, one at a time in order | ordered writes |\n| `exhaustMap` | ignores new values while busy | \"Submit\" button, login |\n\nA classic typeahead:\n\n```ts\nconst results$ = query$.pipe(\n  map((q) => q.trim()),\n  debounceTime(300),\n  distinctUntilChanged(),\n  filter((q) => q.length >= 2),\n  switchMap((q) => search(q).pipe(catchError(() => of([])))),\n);\n```\n\nPut `catchError` **inside** `switchMap`. An error in the outer stream completes it, and the search stops working.\n\n## Unsubscribing\n\nInfinite streams (intervals, events, store selections) keep callbacks and components alive until you unsubscribe:\n\n- prefer the `async` pipe in Angular templates;\n- `takeUntilDestroyed()` (Angular 16+) or `takeUntil(destroy$)`;\n- finite streams (HTTP, `take(1)`, `first()`) complete on their own.\n\n## Combining streams\n\n`combineLatest` (latest of each, after all emitted), `withLatestFrom` (sample others when the main one emits), `forkJoin` (last values when all complete, like `Promise.all`), `merge` (interleave).\n\n## Interview checklist\n\n- Contrast observables with promises, and cold with hot streams.\n- Pick between switchMap, mergeMap, concatMap and exhaustMap.\n- Build a typeahead with debounce, distinct and cancellation.\n- Explain how you avoid subscription leaks.","uk":"RxJS моделює значення в часі як **observable**. Він займає центральне місце в Angular (HttpClient, форми, маршрутизатор) і зручний усюди, де взаємодіють події, таймери й запити.\n\n## Observable проти промісу\n\n| | Проміс | Observable |\n| --- | --- | --- |\n| Значення | одне | від нуля до багатьох |\n| Лінивість | стартує одразу | стартує при `subscribe` |\n| Скасування | ні (якщо не рахувати AbortController) | `unsubscribe()` |\n| Оператори | `then`/`catch` | десятки: `map`, `filter`, `debounceTime`… |\n\n```ts\nconst ticks$ = interval(1000).pipe(take(3), map((n) => n * 10));\nconst sub = ticks$.subscribe({ next: console.log, complete: () => console.log(\"done\") });\n// 0, 10, 20, done\n```\n\n## Холодні й гарячі\n\n- **Холодні** observable (`of`, `interval`, `HttpClient.get`) запускають нового виробника для **кожного** підписника. Два `async` pipe на один HTTP-observable означають два запити.\n- **Гарячі** observable (події DOM, Subject) ділять одного виробника.\n- `share()` / `shareReplay({ bufferSize: 1, refCount: true })` перетворюють холодний потік на спільний.\n\n## Subject\n\nSubject є і observable, і observer: ви передаєте в нього значення через `next()`.\n\n- `Subject`: без початкового значення, пізні підписники пропускають минулі значення.\n- `BehaviorSubject`: має поточне значення, і нові підписники одразу його отримують. Простий стор.\n- `ReplaySubject(n)`: повторює останні n значень.\n\nНазовні віддавайте `subject.asObservable()`, щоб сторонній код не міг надсилати значення.\n\n## Відображення вищого порядку: ключова тема співбесід\n\nКоли кожне значення запускає внутрішній observable (часто запит), оберіть спосіб «сплющення»:\n\n| Оператор | Поведінка | Типове використання |\n| --- | --- | --- |\n| `switchMap` | скасовує попередній внутрішній observable | пошук під час введення, параметри маршруту |\n| `mergeMap` | виконує всі паралельно | незалежні збереження, аналітика |\n| `concatMap` | ставить у чергу, по одному, по порядку | упорядковані записи |\n| `exhaustMap` | ігнорує нові значення, поки зайнятий | кнопка «Надіслати», вхід |\n\nКласичний пошук під час введення:\n\n```ts\nconst results$ = query$.pipe(\n  map((q) => q.trim()),\n  debounceTime(300),\n  distinctUntilChanged(),\n  filter((q) => q.length >= 2),\n  switchMap((q) => search(q).pipe(catchError(() => of([])))),\n);\n```\n\nРозміщуйте `catchError` **всередині** `switchMap`. Помилка в зовнішньому потоці завершує його, і пошук перестає працювати.\n\n## Відписка\n\nНескінченні потоки (інтервали, події, вибірки зі стору) тримають колбеки й компоненти живими, доки ви не відпишетеся:\n\n- у шаблонах Angular обирайте `async` pipe;\n- `takeUntilDestroyed()` (Angular 16+) або `takeUntil(destroy$)`;\n- скінченні потоки (HTTP, `take(1)`, `first()`) завершуються самі.\n\n## Поєднання потоків\n\n`combineLatest` (останні значення кожного, після того як усі видали значення), `withLatestFrom` (взяти останні значення інших, коли видає головний), `forkJoin` (останні значення, коли всі завершилися, як `Promise.all`), `merge` (переплетення).\n\n## Чек-лист для співбесіди\n\n- Порівняйте observable з промісами та холодні потоки з гарячими.\n- Обирайте між switchMap, mergeMap, concatMap і exhaustMap.\n- Побудуйте пошук під час введення з debounce, distinct і скасуванням.\n- Поясніть, як ви уникаєте витоків підписок."}'::jsonb, 8),
  ('searching-algorithms', 'searching-algorithms', '{"en":"Searching algorithms: linear, binary and two pointers","uk":"Алгоритми пошуку: лінійний, бінарний і два вказівники"}'::jsonb, '{"en":"How to find things fast, why binary search needs sorted input, and the off-by-one traps interviewers love.","uk":"Як швидко знаходити елементи, чому бінарному пошуку потрібні відсортовані дані та які помилки «на одиницю» люблять інтерв''юери."}'::jsonb, '{"en":"Searching is the most common building block in interview problems. Before you write a loop, ask two questions: **is the data sorted?** and **how many times will I search?** The answers decide between a linear scan, binary search, a hash map or two pointers.\n\n## Linear search: O(n)\n\nWalk the collection from start to end and stop at the first match.\n\n```ts\nfunction indexOf<T>(items: T[], target: T): number {\n  for (let i = 0; i < items.length; i++) {\n    if (items[i] === target) return i;\n  }\n  return -1;\n}\n```\n\nIt works on **any** data, sorted or not. For a single lookup on unsorted data it is optimal: you cannot know an element is missing without looking at every element. `Array.prototype.indexOf`, `includes` and `find` are all linear.\n\nIf you need **many** lookups, build a `Set` or `Map` once (O(n)) and then each lookup is O(1) on average.\n\n## Binary search: O(log n)\n\nOn **sorted** data you can discard half of the remaining range at every step.\n\n```ts\nfunction binarySearch(items: number[], target: number): number {\n  let lo = 0;\n  let hi = items.length - 1;          // inclusive bounds\n  while (lo <= hi) {\n    const mid = lo + ((hi - lo) >> 1); // avoids overflow in other languages\n    if (items[mid] === target) return mid;\n    if (items[mid] < target) lo = mid + 1;\n    else hi = mid - 1;\n  }\n  return -1;\n}\n```\n\nThe invariant: *if the target exists, it is inside `[lo, hi]`*. Every branch must keep that true and shrink the range, otherwise you loop forever.\n\n### Common bugs\n\n- Using `while (lo < hi)` with inclusive bounds: you skip checking the last element.\n- Writing `lo = mid` instead of `lo = mid + 1`: the range stops shrinking when `hi - lo === 1`.\n- Running binary search on unsorted data: it returns garbage without throwing.\n- Sorting first just to search once: sorting is O(n log n), worse than a single linear scan.\n\n### Lower bound: first position ≥ target\n\nMany interview tasks (\"insert position\", \"first bad version\", \"count occurrences\") are variations of *lower bound*:\n\n```ts\nfunction lowerBound(items: number[], target: number): number {\n  let lo = 0;\n  let hi = items.length;              // half-open [lo, hi)\n  while (lo < hi) {\n    const mid = (lo + hi) >> 1;\n    if (items[mid] < target) lo = mid + 1;\n    else hi = mid;\n  }\n  return lo;                          // 0..length\n}\n```\n\nCount of `x` in a sorted array = `lowerBound(x + 1) - lowerBound(x)`, which is O(log n).\n\n### Binary search on the answer\n\nIf you can check \"is X good enough?\" and the answer flips from *no* to *yes* exactly once as X grows, binary search over X. Examples: the minimum ship capacity to deliver packages in D days, or the smallest divisor with a sum below a threshold.\n\n## Two pointers: O(n) on sorted data\n\nTo find a pair with a given sum in a sorted array, start one pointer at each end:\n\n```ts\nfunction pairWithSum(sorted: number[], sum: number): [number, number] | null {\n  let i = 0;\n  let j = sorted.length - 1;\n  while (i < j) {\n    const s = sorted[i] + sorted[j];\n    if (s === sum) return [i, j];\n    if (s < sum) i++;\n    else j--;\n  }\n  return null;\n}\n```\n\nEach step removes one candidate, so the whole scan is linear. On unsorted data, use a `Map` of seen values instead (also O(n)).\n\n## Choosing the approach\n\n| Situation | Best tool | Cost |\n| --- | --- | --- |\n| One lookup, unsorted | Linear scan | O(n) |\n| Many lookups, unsorted | Build a `Set`/`Map` | O(n) once, then O(1) |\n| Sorted array | Binary search | O(log n) |\n| Pair/range problems on sorted data | Two pointers | O(n) |\n| Monotonic yes/no question | Binary search on the answer | O(log range · check) |\n\n## Interview checklist\n\n1. State whether the input is sorted, and whether duplicates are possible.\n2. Choose inclusive `[lo, hi]` or half-open `[lo, hi)` bounds and stick to them.\n3. Test the empty array, one element, the target at both ends, and a missing target.\n4. Say the complexity out loud.","uk":"Пошук — найпоширеніший будівельний блок у задачах на співбесідах. Перш ніж писати цикл, поставте собі два питання: **чи відсортовані дані?** і **скільки разів я шукатиму?** Від відповідей залежить вибір: лінійний перегляд, бінарний пошук, хеш-таблиця чи два вказівники.\n\n## Лінійний пошук: O(n)\n\nПроходимо колекцію від початку до кінця й зупиняємося на першому збігу.\n\n```ts\nfunction indexOf<T>(items: T[], target: T): number {\n  for (let i = 0; i < items.length; i++) {\n    if (items[i] === target) return i;\n  }\n  return -1;\n}\n```\n\nПрацює на **будь-яких** даних, відсортованих чи ні. Для одного пошуку в невідсортованих даних це оптимально: не можна знати, що елемента немає, не подивившись на кожен. `Array.prototype.indexOf`, `includes` і `find` — лінійні.\n\nЯкщо потрібно **багато** пошуків, один раз побудуйте `Set` або `Map` (O(n)), і тоді кожен пошук коштуватиме в середньому O(1).\n\n## Бінарний пошук: O(log n)\n\nНа **відсортованих** даних на кожному кроці можна відкинути половину діапазону, що залишився.\n\n```ts\nfunction binarySearch(items: number[], target: number): number {\n  let lo = 0;\n  let hi = items.length - 1;          // межі включно\n  while (lo <= hi) {\n    const mid = lo + ((hi - lo) >> 1); // уникає переповнення в інших мовах\n    if (items[mid] === target) return mid;\n    if (items[mid] < target) lo = mid + 1;\n    else hi = mid - 1;\n  }\n  return -1;\n}\n```\n\nІнваріант: *якщо елемент існує, він усередині `[lo, hi]`*. Кожна гілка має зберігати це твердження й звужувати діапазон, інакше цикл стане нескінченним.\n\n### Типові помилки\n\n- `while (lo < hi)` з межами включно: останній елемент не перевіряється.\n- `lo = mid` замість `lo = mid + 1`: діапазон перестає звужуватися, коли `hi - lo === 1`.\n- Бінарний пошук по невідсортованих даних: результат хибний, а помилки немає.\n- Сортування лише заради одного пошуку: сортування — O(n log n), гірше за один лінійний прохід.\n\n### Нижня межа: перша позиція ≥ target\n\nБагато задач («позиція вставки», «перша погана версія», «кількість входжень») — варіації *нижньої межі* (lower bound):\n\n```ts\nfunction lowerBound(items: number[], target: number): number {\n  let lo = 0;\n  let hi = items.length;              // напіввідкритий [lo, hi)\n  while (lo < hi) {\n    const mid = (lo + hi) >> 1;\n    if (items[mid] < target) lo = mid + 1;\n    else hi = mid;\n  }\n  return lo;                          // 0..length\n}\n```\n\nКількість `x` у відсортованому масиві = `lowerBound(x + 1) - lowerBound(x)`, тобто O(log n).\n\n### Бінарний пошук за відповіддю\n\nЯкщо можна перевірити «чи достатньо X?» і відповідь змінюється з *ні* на *так* рівно один раз зі зростанням X, шукайте бінарно по X. Приклади: мінімальна місткість корабля, щоб доставити вантаж за D днів, або найменший дільник, за якого сума менша за поріг.\n\n## Два вказівники: O(n) на відсортованих даних\n\nЩоб знайти пару з заданою сумою у відсортованому масиві, поставте по вказівнику на кожен кінець:\n\n```ts\nfunction pairWithSum(sorted: number[], sum: number): [number, number] | null {\n  let i = 0;\n  let j = sorted.length - 1;\n  while (i < j) {\n    const s = sorted[i] + sorted[j];\n    if (s === sum) return [i, j];\n    if (s < sum) i++;\n    else j--;\n  }\n  return null;\n}\n```\n\nКожен крок відкидає одного кандидата, тож увесь прохід лінійний. На невідсортованих даних використайте `Map` уже побачених значень (теж O(n)).\n\n## Як обрати підхід\n\n| Ситуація | Найкращий інструмент | Вартість |\n| --- | --- | --- |\n| Один пошук, дані не відсортовані | Лінійний прохід | O(n) |\n| Багато пошуків, дані не відсортовані | Побудувати `Set`/`Map` | O(n) один раз, далі O(1) |\n| Відсортований масив | Бінарний пошук | O(log n) |\n| Задачі на пари/діапазони у відсортованих даних | Два вказівники | O(n) |\n| Монотонне питання «так/ні» | Бінарний пошук за відповіддю | O(log діапазону · перевірка) |\n\n## Чек-лист для співбесіди\n\n1. Уточніть, чи відсортовані вхідні дані та чи можливі дублікати.\n2. Оберіть межі `[lo, hi]` включно або напіввідкриті `[lo, hi)` і дотримуйтеся їх.\n3. Перевірте порожній масив, один елемент, шуканий елемент на обох кінцях і відсутній елемент.\n4. Назвіть складність уголос."}'::jsonb, 7),
  ('sorting-algorithms', 'sorting-algorithms', '{"en":"Sorting algorithms: merge, quick, counting and stability","uk":"Алгоритми сортування: злиттям, швидке, підрахунком і стабільність"}'::jsonb, '{"en":"How the classic sorts work, their complexity and stability, and how JavaScript''s Array.prototype.sort behaves.","uk":"Як працюють класичні сортування, їхня складність і стабільність та як поводиться Array.prototype.sort у JavaScript."}'::jsonb, '{"en":"You rarely write a sort in production, but interviews use sorting to check your grasp of divide-and-conquer, complexity and stability.\n\n## The landscape\n\n| Algorithm | Average | Worst | Extra memory | Stable |\n| --- | --- | --- | --- | --- |\n| Insertion sort | O(n²) | O(n²) | O(1) | yes (fast on nearly sorted data) |\n| Merge sort | O(n log n) | O(n log n) | O(n) | **yes** |\n| Quicksort | O(n log n) | O(n²) | O(log n) stack | no |\n| Heapsort | O(n log n) | O(n log n) | O(1) | no |\n| Counting / radix | O(n + k) | O(n + k) | O(n + k) | yes |\n\nComparison sorts can''t beat **O(n log n)** in the worst case. Counting and radix sorts avoid comparisons, so they can be linear for small integer ranges.\n\n## Merge sort\n\nSplit in half, sort both halves recursively, then merge the two sorted halves:\n\n```ts\nfunction mergeSort<T>(a: T[], cmp: (x: T, y: T) => number): T[] {\n  if (a.length <= 1) return a.slice();\n  const mid = a.length >> 1;\n  const left = mergeSort(a.slice(0, mid), cmp);\n  const right = mergeSort(a.slice(mid), cmp);\n  const out: T[] = [];\n  let i = 0, j = 0;\n  while (i < left.length && j < right.length) {\n    out.push(cmp(right[j], left[i]) < 0 ? right[j++] : left[i++]); // ties take left → stable\n  }\n  return out.concat(left.slice(i), right.slice(j));\n}\n```\n\nIt''s predictable at O(n log n), stable and great for linked lists and external sorting. The cost is O(n) extra memory.\n\n## Quicksort\n\nPick a pivot, partition elements into \"less than\" and \"greater than\", then recurse on both sides. It''s fast in practice and sorts in place. A bad pivot on already-sorted input degrades to O(n²), which random or median-of-three pivots avoid.\n\n## Stability\n\nA **stable** sort keeps equal elements in their original order. That matters when you sort by several keys: sort by the secondary key first, then by the primary key with a stable sort.\n\n## JavaScript''s `sort`\n\n- Without a comparator it compares **strings**: `[10, 9, 1].sort()` gives `[1, 10, 9]`.\n- The comparator returns a negative number, zero or a positive number. `(a, b) => a - b` sorts ascending.\n- Since ES2019 it is guaranteed **stable**. V8 uses TimSort, a hybrid of merge and insertion sort.\n- It sorts **in place**. Use `toSorted` or copy first when the array is shared state.\n\n```js\nusers.toSorted((a, b) => a.age - b.age || a.name.localeCompare(b.name));\n```\n\n## Interview checklist\n\n- Explain why merge sort is stable and quicksort isn''t.\n- Know the O(n log n) lower bound for comparison sorts and when counting sort beats it.\n- Always supply a numeric comparator in JavaScript.\n- Describe how to sort by several keys.","uk":"У продакшн-коді сортування рідко пишуть вручну, але на співбесідах воно перевіряє розуміння підходу «розділяй і володарюй», складності та стабільності.\n\n## Загальна картина\n\n| Алгоритм | Середній | Найгірший | Додаткова пам''ять | Стабільний |\n| --- | --- | --- | --- | --- |\n| Вставками | O(n²) | O(n²) | O(1) | так (швидкий на майже відсортованих даних) |\n| Злиттям | O(n log n) | O(n log n) | O(n) | **так** |\n| Швидке (quicksort) | O(n log n) | O(n²) | O(log n) стеку | ні |\n| Пірамідальне (heapsort) | O(n log n) | O(n log n) | O(1) | ні |\n| Підрахунком / розрядне | O(n + k) | O(n + k) | O(n + k) | так |\n\nСортування порівнянням не може бути кращим за **O(n log n)** у найгіршому випадку. Сортування підрахунком і розрядне не використовують порівнянь, тож для малого діапазону цілих чисел можуть бути лінійними.\n\n## Сортування злиттям\n\nРозділити масив навпіл, рекурсивно відсортувати обидві половини, потім злити дві відсортовані частини:\n\n```ts\nfunction mergeSort<T>(a: T[], cmp: (x: T, y: T) => number): T[] {\n  if (a.length <= 1) return a.slice();\n  const mid = a.length >> 1;\n  const left = mergeSort(a.slice(0, mid), cmp);\n  const right = mergeSort(a.slice(mid), cmp);\n  const out: T[] = [];\n  let i = 0, j = 0;\n  while (i < left.length && j < right.length) {\n    out.push(cmp(right[j], left[i]) < 0 ? right[j++] : left[i++]); // при рівності беремо лівий → стабільно\n  }\n  return out.concat(left.slice(i), right.slice(j));\n}\n```\n\nВоно передбачуване (O(n log n)), стабільне й чудово підходить для зв''язних списків і зовнішнього сортування. Ціна: O(n) додаткової пам''яті.\n\n## Швидке сортування\n\nОбрати опорний елемент, розбити елементи на «менші» й «більші», потім рекурсивно обробити обидві частини. Швидке на практиці й сортує на місці. Невдалий опорний елемент на вже відсортованих даних дає O(n²); випадковий опорний елемент або медіана трьох цього уникають.\n\n## Стабільність\n\n**Стабільне** сортування зберігає рівні елементи в початковому порядку. Це важливо, коли сортують за кількома ключами: спершу за другорядним ключем, потім стабільно за основним.\n\n## `sort` у JavaScript\n\n- Без компаратора порівнює **рядки**: `[10, 9, 1].sort()` дає `[1, 10, 9]`.\n- Компаратор повертає від''ємне число, нуль або додатне число. `(a, b) => a - b` сортує за зростанням.\n- Починаючи з ES2019 сортування гарантовано **стабільне**. V8 використовує TimSort, гібрид злиття та вставок.\n- Сортує **на місці**. Використовуйте `toSorted` або спершу копіюйте масив, якщо це спільний стан.\n\n```js\nusers.toSorted((a, b) => a.age - b.age || a.name.localeCompare(b.name));\n```\n\n## Чек-лист для співбесіди\n\n- Поясніть, чому сортування злиттям стабільне, а швидке ні.\n- Знайте нижню межу O(n log n) для сортувань порівнянням і коли сортування підрахунком її обходить.\n- У JavaScript завжди передавайте числовий компаратор.\n- Опишіть, як сортувати за кількома ключами."}'::jsonb, 8),
  ('state-management', 'state-management', '{"en":"State management: where state lives and how it changes","uk":"Керування станом: де живе стан і як він змінюється"}'::jsonb, '{"en":"Local vs shared vs server state, single source of truth, reducers and immutability, selectors and derived data, and when a store library is worth it.","uk":"Локальний, спільний і серверний стан, єдине джерело правди, редʼюсери й незмінність, селектори й похідні дані, і коли бібліотека стору справді потрібна."}'::jsonb, '{"en":"Most UI bugs are state bugs: two copies that disagree, a mutation nobody noticed, or a value that should have been derived. Good state management is mostly about **where** state lives and **how** it changes.\n\n## Kinds of state\n\n| Kind | Examples | Usually lives in |\n| --- | --- | --- |\n| Local UI state | input text, open/closed | component state |\n| Shared client state | cart, theme, current user | context, store (Redux, NgRx, Zustand, signals) |\n| Server state | lists from the API | a cache (TanStack Query, RTK Query, SWR), not a hand-written store |\n| URL state | filters, page, selected tab | the URL (shareable, survives reloads) |\n| Form state | values, validation, touched | a form library or local state |\n\nKeep state as **local as possible** and lift it only when siblings need it. Treat server data as a cache with loading/error/stale states instead of copying it into a global store.\n\n## Single source of truth and derived data\n\nStore the minimum, and derive the rest during render or in selectors:\n\n```ts\n// ✗ items, total and count stored separately (they drift apart)\n// ✓ store items, derive the rest\nconst total = items.reduce((s, i) => s + i.price * i.qty, 0);\n```\n\nNormalise relational data (`byId` maps plus id arrays) so each entity exists once.\n\n## Reducers and immutability\n\nA reducer is a pure function `(state, action) => newState`:\n\n```ts\nfunction cartReducer(state: Cart, action: Action): Cart {\n  switch (action.type) {\n    case \"add\": {\n      const existing = state.items.find((i) => i.id === action.item.id);\n      return {\n        ...state,\n        items: existing\n          ? state.items.map((i) => (i.id === action.item.id ? { ...i, qty: i.qty + 1 } : i))\n          : [...state.items, { ...action.item, qty: 1 }],\n      };\n    }\n    default:\n      return state;\n  }\n}\n```\n\n- **Never mutate**: return new objects or arrays for anything that changed, and reuse references for what didn''t. That''s how React, Redux selectors and Angular OnPush detect changes cheaply (`prev !== next`).\n- Unknown actions return the same state object.\n- Libraries like Immer (built into Redux Toolkit) let you write \"mutating\" code that produces immutable updates.\n\n## Selectors\n\nSelectors read and derive state (`selectCartTotal`). Memoised selectors (`createSelector`) recompute only when inputs change and keep returned references stable, which avoids needless re-renders.\n\n## Side effects\n\nKeep reducers pure. Put requests, timers and storage in thunks, sagas, NgRx effects or query libraries, and dispatch actions with the results (`loading` → `success`/`failure`).\n\n## Choosing tools\n\n- React: `useState`/`useReducer` + context for small shared state; Zustand/Redux Toolkit for larger client state; TanStack Query for server state.\n- Angular: services with signals or BehaviorSubject; NgRx for large apps that need strict patterns and devtools.\n\nDon''t add a global store \"just in case\". Add structure when state is shared widely, changes in complex ways, or needs time-travel debugging.\n\n## Interview checklist\n\n- Classify state and decide where it should live.\n- Write a pure, immutable reducer and explain why immutability matters.\n- Derive data instead of duplicating it.\n- Separate server state (cache) from client state.","uk":"Більшість помилок UI є помилками стану: дві копії, що не збігаються, непомічена мутація або значення, яке слід було обчислити. Добре керування станом зводиться переважно до того, **де** стан живе і **як** змінюється.\n\n## Види стану\n\n| Вид | Приклади | Зазвичай живе в |\n| --- | --- | --- |\n| Локальний стан UI | текст поля, відкрито/закрито | стані компонента |\n| Спільний клієнтський стан | кошик, тема, поточний користувач | контексті, сторі (Redux, NgRx, Zustand, сигнали) |\n| Серверний стан | списки з API | кеші (TanStack Query, RTK Query, SWR), а не в написаному вручну сторі |\n| Стан в URL | фільтри, сторінка, вибрана вкладка | URL (можна поділитися, переживає перезавантаження) |\n| Стан форми | значення, валідація, торкнуті поля | бібліотеці форм або локальному стані |\n\nТримайте стан **якомога локальніше** й піднімайте його лише тоді, коли він потрібен сусіднім компонентам. Ставтеся до серверних даних як до кешу зі станами завантаження/помилки/застарілості, а не копіюйте їх у глобальний стор.\n\n## Єдине джерело правди й похідні дані\n\nЗберігайте мінімум, а решту обчислюйте під час рендеру чи в селекторах:\n\n```ts\n// ✗ items, total і count зберігаються окремо (вони розходяться)\n// ✓ зберігайте items, решту обчислюйте\nconst total = items.reduce((s, i) => s + i.price * i.qty, 0);\n```\n\nНормалізуйте реляційні дані (мапи `byId` плюс масиви id), щоб кожна сутність існувала один раз.\n\n## Редʼюсери й незмінність\n\nРедʼюсер є чистою функцією `(state, action) => newState`:\n\n```ts\nfunction cartReducer(state: Cart, action: Action): Cart {\n  switch (action.type) {\n    case \"add\": {\n      const existing = state.items.find((i) => i.id === action.item.id);\n      return {\n        ...state,\n        items: existing\n          ? state.items.map((i) => (i.id === action.item.id ? { ...i, qty: i.qty + 1 } : i))\n          : [...state.items, { ...action.item, qty: 1 }],\n      };\n    }\n    default:\n      return state;\n  }\n}\n```\n\n- **Ніколи не змінюйте стан напряму**: повертайте нові об''єкти чи масиви для всього, що змінилося, і перевикористовуйте посилання на те, що не змінилося. Саме так React, селектори Redux і Angular OnPush дешево виявляють зміни (`prev !== next`).\n- Для невідомих дій повертайте той самий об''єкт стану.\n- Бібліотеки на кшталт Immer (вбудованої в Redux Toolkit) дозволяють писати «мутуючий» код, що створює незмінні оновлення.\n\n## Селектори\n\nСелектори читають і обчислюють похідний стан (`selectCartTotal`). Мемоізовані селектори (`createSelector`) перераховуються лише при зміні вхідних даних і зберігають стабільні посилання, що позбавляє зайвих ререндерів.\n\n## Побічні ефекти\n\nТримайте редʼюсери чистими. Запити, таймери й сховища розміщуйте в thunk, sagas, ефектах NgRx чи бібліотеках запитів і надсилайте дії з результатами (`loading` → `success`/`failure`).\n\n## Вибір інструментів\n\n- React: `useState`/`useReducer` + context для невеликого спільного стану; Zustand/Redux Toolkit для більшого клієнтського стану; TanStack Query для серверного стану.\n- Angular: сервіси із сигналами чи BehaviorSubject; NgRx для великих застосунків, яким потрібні суворі патерни й devtools.\n\nНе додавайте глобальний стор «про всяк випадок». Додавайте структуру, коли стан широко використовується, складно змінюється або потребує налагодження з «подорожжю в часі».\n\n## Чек-лист для співбесіди\n\n- Класифікуйте стан і вирішіть, де він має жити.\n- Напишіть чистий незмінний редʼюсер і поясніть, чому важлива незмінність.\n- Обчислюйте дані замість дублювання.\n- Відокремлюйте серверний стан (кеш) від клієнтського."}'::jsonb, 8),
  ('typescript', 'typescript', '{"en":"TypeScript for interviews: narrowing, generics and utility types","uk":"TypeScript для співбесід: звуження типів, дженерики та утилітні типи"}'::jsonb, '{"en":"How the type checker thinks: structural typing, unions and narrowing, generics with constraints, and the utility types you are expected to know.","uk":"Як мислить перевірка типів: структурна типізація, об''єднання та звуження, дженерики з обмеженнями й утилітні типи, які від вас очікують знати."}'::jsonb, '{"en":"TypeScript checks your JavaScript before it runs. Interviewers want to see that you can model data precisely, without `any`.\n\n## Structural typing\n\nTypes are compatible when their **shapes** match, whatever the types are named:\n\n```ts\ntype Point = { x: number; y: number };\nconst p = { x: 1, y: 2, label: \"A\" };\nconst q: Point = p; // OK: p has at least x and y\n```\n\nObject literals assigned directly get *excess property checks*: `const r: Point = { x: 1, y: 2, z: 3 }` is an error.\n\n## `unknown` vs `any`\n\n- `any` switches the checker off and spreads silently.\n- `unknown` accepts anything but forces you to **narrow** before use. Prefer `unknown` for external data such as JSON and errors in `catch`.\n\n## Unions and narrowing\n\n```ts\ntype Shape =\n  | { kind: \"circle\"; r: number }\n  | { kind: \"rect\"; w: number; h: number };\n\nfunction area(s: Shape): number {\n  switch (s.kind) {             // discriminant\n    case \"circle\": return Math.PI * s.r ** 2;\n    case \"rect\":   return s.w * s.h;\n    default: {\n      const never: never = s;   // compile error if a case is missing\n      return never;\n    }\n  }\n}\n```\n\nNarrowing works with `typeof`, `instanceof`, `in`, equality checks, truthiness and **type guards**:\n\n```ts\nfunction isString(v: unknown): v is string {\n  return typeof v === \"string\";\n}\n```\n\n## Generics\n\nGenerics let one function work for many types while keeping the relationship between input and output:\n\n```ts\nfunction first<T>(items: T[]): T | undefined {\n  return items[0];\n}\n\nfunction pick<T, K extends keyof T>(obj: T, keys: K[]): Pick<T, K> {\n  const out = {} as Pick<T, K>;\n  for (const k of keys) out[k] = obj[k];\n  return out;\n}\n```\n\n`K extends keyof T` is a **constraint**: `K` must be a property name of `T`.\n\n## Utility types worth knowing\n\n| Type | Meaning |\n| --- | --- |\n| `Partial<T>` / `Required<T>` | all properties optional / required |\n| `Readonly<T>` | properties can''t be reassigned |\n| `Pick<T, K>` / `Omit<T, K>` | keep / drop properties |\n| `Record<K, V>` | object with keys `K` and values `V` |\n| `ReturnType<F>` / `Parameters<F>` | extract from function types |\n| `Awaited<T>` | unwrap a Promise type |\n| `NonNullable<T>` | remove `null` and `undefined` |\n\n## `type` vs `interface`\n\nBoth describe object shapes. `interface` can be **merged** and `extends` other interfaces. `type` can express unions, tuples, mapped and conditional types. Pick one convention per codebase.\n\n## Interview checklist\n\n- Model states as discriminated unions instead of optional flags.\n- Use `unknown` plus narrowing for untrusted data.\n- Explain what a generic constraint guarantees.\n- Know that types are erased at runtime: validate external input with code (e.g. zod).","uk":"TypeScript перевіряє ваш JavaScript до запуску. Інтерв''юери хочуть побачити, що ви вмієте точно моделювати дані без `any`.\n\n## Структурна типізація\n\nТипи сумісні, коли збігається їхня **форма**, незалежно від назв типів:\n\n```ts\ntype Point = { x: number; y: number };\nconst p = { x: 1, y: 2, label: \"A\" };\nconst q: Point = p; // OK: у p є щонайменше x та y\n```\n\nДля об''єктних літералів, присвоєних напряму, діє *перевірка зайвих властивостей*: `const r: Point = { x: 1, y: 2, z: 3 }` дає помилку.\n\n## `unknown` проти `any`\n\n- `any` вимикає перевірку й непомітно поширюється кодом.\n- `unknown` приймає будь-що, але змушує **звузити** тип перед використанням. Обирайте `unknown` для зовнішніх даних, як-от JSON і помилки в `catch`.\n\n## Об''єднання та звуження\n\n```ts\ntype Shape =\n  | { kind: \"circle\"; r: number }\n  | { kind: \"rect\"; w: number; h: number };\n\nfunction area(s: Shape): number {\n  switch (s.kind) {             // дискримінант\n    case \"circle\": return Math.PI * s.r ** 2;\n    case \"rect\":   return s.w * s.h;\n    default: {\n      const never: never = s;   // помилка компіляції, якщо випадок пропущено\n      return never;\n    }\n  }\n}\n```\n\nЗвуження працює з `typeof`, `instanceof`, `in`, перевірками рівності, істинності та **type guards**:\n\n```ts\nfunction isString(v: unknown): v is string {\n  return typeof v === \"string\";\n}\n```\n\n## Дженерики\n\nДженерики дозволяють одній функції працювати з різними типами, зберігаючи зв''язок між входом і виходом:\n\n```ts\nfunction first<T>(items: T[]): T | undefined {\n  return items[0];\n}\n\nfunction pick<T, K extends keyof T>(obj: T, keys: K[]): Pick<T, K> {\n  const out = {} as Pick<T, K>;\n  for (const k of keys) out[k] = obj[k];\n  return out;\n}\n```\n\n`K extends keyof T` є **обмеженням**: `K` має бути назвою властивості `T`.\n\n## Утилітні типи, які варто знати\n\n| Тип | Значення |\n| --- | --- |\n| `Partial<T>` / `Required<T>` | усі властивості необов''язкові / обов''язкові |\n| `Readonly<T>` | властивості не можна перевизначати |\n| `Pick<T, K>` / `Omit<T, K>` | залишити / прибрати властивості |\n| `Record<K, V>` | об''єкт із ключами `K` і значеннями `V` |\n| `ReturnType<F>` / `Parameters<F>` | витягнути з типу функції |\n| `Awaited<T>` | розгорнути тип Promise |\n| `NonNullable<T>` | прибрати `null` і `undefined` |\n\n## `type` проти `interface`\n\nОбидва описують форму об''єкта. `interface` можна **зливати** й розширювати через `extends`. `type` вміє об''єднання, кортежі, відображені (mapped) та умовні типи. Оберіть одну домовленість для кодової бази.\n\n## Чек-лист для співбесіди\n\n- Моделюйте стани дискримінованими об''єднаннями, а не необов''язковими прапорцями.\n- Для неперевірених даних використовуйте `unknown` і звуження.\n- Поясніть, що гарантує обмеження дженерика.\n- Пам''ятайте, що типи стираються під час виконання: валідуйте зовнішній вхід кодом (наприклад, zod)."}'::jsonb, 8),
  ('unit-testing', 'unit-testing', '{"en":"Unit testing: structure, test doubles and testing UI behaviour","uk":"Модульне тестування: структура, тестові дублери й тестування поведінки UI"}'::jsonb, '{"en":"Arrange-act-assert, what makes a good test, mocks vs stubs vs fakes, testing async code and timers, and testing components through the user''s eyes.","uk":"Arrange-act-assert, що робить тест хорошим, моки, стаби й фейки, тестування асинхронного коду й таймерів і тестування компонентів очима користувача."}'::jsonb, '{"en":"Good tests let you change code without fear. Interviewers look for tests that check **behaviour**, are fast and deterministic, and fail for one clear reason.\n\n## Anatomy of a test\n\n```ts\ndescribe(\"formatPrice\", () => {\n  it(\"formats cents as a currency string\", () => {\n    // Arrange\n    const cents = 123456;\n    // Act\n    const text = formatPrice(cents, \"USD\");\n    // Assert\n    expect(text).toBe(\"$1,234.56\");\n  });\n});\n```\n\n- One behaviour per test, with a name that reads like a specification.\n- Test edge cases: empty input, zero, negative numbers, boundaries, invalid data.\n- Avoid logic (loops, ifs) in tests. Prefer `it.each` tables.\n\n## The testing pyramid (or trophy)\n\nMany fast **unit** tests for pure logic, a solid layer of **integration/component** tests, and a few **end-to-end** tests for critical journeys (Playwright, Cypress). Static types and linting catch a whole class of bugs for free.\n\n## Test doubles\n\n| Double | Purpose |\n| --- | --- |\n| **Stub** | returns canned answers (`getUser → { id: 1 }`) |\n| **Mock / spy** | records calls so you can assert on them (`expect(send).toHaveBeenCalledWith(...)`) |\n| **Fake** | a working lightweight implementation (in-memory repository) |\n\nDesign for testability by **injecting dependencies** (clock, HTTP client, storage) instead of importing them deep inside your code:\n\n```ts\nexport function isExpired(token: Token, now = Date.now) {\n  return token.expiresAt < now();\n}\n// test: isExpired(token, () => 1_000)\n```\n\nOver-mocking is a smell: if a test mocks everything, it tests the mocks. Mock at boundaries (network, time, randomness), not your own internal functions.\n\n## Async code and time\n\n```ts\nit(\"retries once\", async () => {\n  const fetcher = vi.fn().mockRejectedValueOnce(new Error(\"down\")).mockResolvedValue(\"ok\");\n  await expect(loadWithRetry(fetcher)).resolves.toBe(\"ok\");\n  expect(fetcher).toHaveBeenCalledTimes(2);\n});\n```\n\nAlways `await` (or return) the promise, or the test passes before the assertion runs. Use fake timers (`vi.useFakeTimers()`, `jest.useFakeTimers()`) for debounce, retries and timeouts, so tests stay fast and deterministic.\n\n## Testing UI\n\nTest what the user sees and does, not implementation details:\n\n```tsx\nrender(<Login />);\nawait user.type(screen.getByLabelText(\"Email\"), \"a@b.co\");\nawait user.click(screen.getByRole(\"button\", { name: \"Sign in\" }));\nexpect(await screen.findByText(\"Welcome back\")).toBeInTheDocument();\n```\n\nQuery by **role and accessible name** first, then label, then text. `data-testid` is a last resort. This also nudges you towards accessible markup. Don''t assert on internal state or CSS class names.\n\n## Coverage\n\nCoverage shows what was **executed**, not what was **verified**. Aim for meaningful coverage of business logic rather than 100% of everything.\n\n## Interview checklist\n\n- Write a clear arrange-act-assert test with edge cases.\n- Explain stubs vs mocks vs fakes, and inject dependencies to make code testable.\n- Test async code and timers without flakiness.\n- Query components by role and label, like a user would.","uk":"Хороші тести дозволяють змінювати код без страху. Інтерв''юери шукають тести, що перевіряють **поведінку**, швидкі й детерміновані та падають з однієї зрозумілої причини.\n\n## Анатомія тесту\n\n```ts\ndescribe(\"formatPrice\", () => {\n  it(\"formats cents as a currency string\", () => {\n    // Arrange (підготовка)\n    const cents = 123456;\n    // Act (дія)\n    const text = formatPrice(cents, \"USD\");\n    // Assert (перевірка)\n    expect(text).toBe(\"$1,234.56\");\n  });\n});\n```\n\n- Одна поведінка на тест, а назва читається як специфікація.\n- Перевіряйте граничні випадки: порожній вхід, нуль, від''ємні числа, межі, некоректні дані.\n- Уникайте логіки (циклів, умов) у тестах. Обирайте таблиці `it.each`.\n\n## Піраміда (або «кубок») тестування\n\nБагато швидких **модульних** тестів для чистої логіки, міцний шар **інтеграційних/компонентних** тестів і кілька **наскрізних (e2e)** тестів для критичних сценаріїв (Playwright, Cypress). Статичні типи й лінтинг безкоштовно ловлять цілий клас помилок.\n\n## Тестові дублери\n\n| Дублер | Призначення |\n| --- | --- |\n| **Stub (заглушка)** | повертає заготовлені відповіді (`getUser → { id: 1 }`) |\n| **Mock / spy (шпигун)** | записує виклики, щоб їх перевірити (`expect(send).toHaveBeenCalledWith(...)`) |\n| **Fake (фейк)** | робоча спрощена реалізація (репозиторій у пам''яті) |\n\nПроєктуйте код тестованим через **впровадження залежностей** (годинник, HTTP-клієнт, сховище) замість імпорту їх глибоко всередині коду:\n\n```ts\nexport function isExpired(token: Token, now = Date.now) {\n  return token.expiresAt < now();\n}\n// у тесті: isExpired(token, () => 1_000)\n```\n\nНадмірне мокання є поганою ознакою: якщо тест мокає все, він тестує моки. Мокайте на межах (мережа, час, випадковість), а не власні внутрішні функції.\n\n## Асинхронний код і час\n\n```ts\nit(\"retries once\", async () => {\n  const fetcher = vi.fn().mockRejectedValueOnce(new Error(\"down\")).mockResolvedValue(\"ok\");\n  await expect(loadWithRetry(fetcher)).resolves.toBe(\"ok\");\n  expect(fetcher).toHaveBeenCalledTimes(2);\n});\n```\n\nЗавжди використовуйте `await` (або повертайте проміс), інакше тест пройде раніше, ніж виконається перевірка. Для debounce, повторних спроб і тайм-аутів беріть фейкові таймери (`vi.useFakeTimers()`, `jest.useFakeTimers()`), щоб тести лишалися швидкими й детермінованими.\n\n## Тестування UI\n\nПеревіряйте те, що користувач бачить і робить, а не деталі реалізації:\n\n```tsx\nrender(<Login />);\nawait user.type(screen.getByLabelText(\"Email\"), \"a@b.co\");\nawait user.click(screen.getByRole(\"button\", { name: \"Sign in\" }));\nexpect(await screen.findByText(\"Welcome back\")).toBeInTheDocument();\n```\n\nШукайте елементи спершу за **роллю й доступним ім''ям**, потім за міткою, потім за текстом. `data-testid` є крайнім засобом. Це ще й підштовхує до доступної розмітки. Не перевіряйте внутрішній стан чи назви CSS-класів.\n\n## Покриття\n\nПокриття показує, що було **виконано**, а не що було **перевірено**. Прагніть змістовного покриття бізнес-логіки, а не 100% усього.\n\n## Чек-лист для співбесіди\n\n- Напишіть зрозумілий тест arrange-act-assert з граничними випадками.\n- Поясніть різницю між стабами, моками й фейками та впроваджуйте залежності, щоб код був тестованим.\n- Тестуйте асинхронний код і таймери без нестабільності.\n- Шукайте компоненти за роллю й міткою, як це робив би користувач."}'::jsonb, 8),
  ('web-accessibility', 'web-accessibility', '{"en":"Web accessibility: WCAG, semantics, keyboard and ARIA","uk":"Вебдоступність: WCAG, семантика, клавіатура та ARIA"}'::jsonb, '{"en":"The principles behind WCAG, why native HTML beats ARIA, keyboard and focus management, accessible names, contrast and how to test.","uk":"Принципи WCAG, чому нативний HTML кращий за ARIA, керування клавіатурою й фокусом, доступні імена, контраст і тестування."}'::jsonb, '{"en":"Accessibility (a11y) means people can use your product with screen readers, keyboards, switch devices, zoom or in bright sunlight. It''s a legal requirement in many markets (the European Accessibility Act, ADA) and a quality signal in interviews.\n\n## WCAG in one minute\n\nWCAG 2.2 organises requirements under **POUR**: Perceivable, Operable, Understandable, Robust. Level **AA** is the usual target. Typical AA checks:\n\n- Text contrast at least **4.5:1** (3:1 for large text and UI component boundaries).\n- Everything works with the **keyboard**, with a visible focus indicator.\n- Every image has a text alternative; every form control has a label.\n- No information conveyed by colour alone.\n- Content reflows at 320 px width and 200% zoom without horizontal scrolling.\n- Target size at least 24×24 px (2.2).\n\n## The first rule of ARIA\n\n**Don''t use ARIA if a native element does the job.** A `<button>` is focusable, has the right role and handles Enter and Space. A `<div role=\"button\">` needs `tabindex=\"0\"` and key handlers to catch up. ARIA only changes what assistive technology *announces*; it adds no behaviour.\n\nWhen you do build custom widgets (tabs, combobox, disclosure), follow the ARIA Authoring Practices patterns:\n\n```html\n<button aria-expanded=\"false\" aria-controls=\"faq-1\">Shipping</button>\n<div id=\"faq-1\" hidden>…</div>\n```\n\nToggle buttons use `aria-pressed`, disclosures `aria-expanded`, current navigation items `aria-current=\"page\"`.\n\n## Accessible names\n\nEvery interactive element needs a name:\n\n- Visible text content (`<button>Save</button>`),\n- `<label for>` for inputs,\n- `aria-label` / `aria-labelledby` for icon-only controls,\n- `alt` for images (`alt=\"\"` for decorative ones).\n\nThe visible label should be part of the accessible name (WCAG 2.5.3, \"label in name\"), so voice-control users can say what they see.\n\n## Keyboard and focus\n\n- Tab order follows the DOM order, so keep visual and DOM order aligned. Avoid positive `tabindex`.\n- Never remove focus outlines without a replacement: style `:focus-visible` instead.\n- Modals: move focus in, trap it, close on Escape, and return focus to the trigger. The native `<dialog>` with `showModal()` does most of this.\n- Provide a \"skip to content\" link and landmarks.\n\n## Dynamic content\n\nAnnounce changes with live regions: `aria-live=\"polite\"` for status messages, `role=\"alert\"` for errors. Move focus deliberately after route changes in SPAs.\n\n## Motion and preferences\n\nRespect `prefers-reduced-motion`, don''t auto-play animations longer than 5 seconds without a pause control, and never flash more than three times per second.\n\n## Testing\n\nAutomated tools (axe, Lighthouse) catch about a third of issues. Then test manually: navigate with the keyboard only, use a screen reader (VoiceOver, NVDA), zoom to 200%, and check contrast.\n\n## Interview checklist\n\n- State the first rule of ARIA and give an example.\n- Make an icon-only button and a custom toggle accessible.\n- Explain focus management for a modal.\n- Describe how you''d test a page for accessibility.","uk":"Доступність (a11y) означає, що вашим продуктом можуть користуватися люди зі зчитувачами екрана, клавіатурою, перемикачами, збільшенням або під яскравим сонцем. У багатьох країнах це юридична вимога (Європейський акт про доступність, ADA) і показник якості на співбесідах.\n\n## WCAG за хвилину\n\nWCAG 2.2 групує вимоги за принципами **POUR**: Perceivable (сприйманість), Operable (керованість), Understandable (зрозумілість), Robust (надійність). Звична мета: рівень **AA**. Типові перевірки AA:\n\n- Контраст тексту щонайменше **4,5:1** (3:1 для великого тексту й меж елементів інтерфейсу).\n- Усе працює з **клавіатури**, з видимим індикатором фокусу.\n- Кожне зображення має текстову альтернативу; кожне поле форми має мітку.\n- Інформація не передається лише кольором.\n- Вміст перебудовується за ширини 320 px і збільшення 200% без горизонтальної прокрутки.\n- Розмір цілі щонайменше 24×24 px (2.2).\n\n## Перше правило ARIA\n\n**Не використовуйте ARIA, якщо з завданням впорається нативний елемент.** `<button>` отримує фокус, має правильну роль і обробляє Enter та Space. `<div role=\"button\">` потребує `tabindex=\"0\"` і обробників клавіш, щоб наздогнати його. ARIA змінює лише те, що *оголошують* допоміжні технології, і не додає поведінки.\n\nКоли ви все ж будуєте власні віджети (вкладки, комбобокс, розкривні блоки), дотримуйтеся патернів ARIA Authoring Practices:\n\n```html\n<button aria-expanded=\"false\" aria-controls=\"faq-1\">Доставка</button>\n<div id=\"faq-1\" hidden>…</div>\n```\n\nКнопки-перемикачі використовують `aria-pressed`, розкривні блоки `aria-expanded`, поточні пункти навігації `aria-current=\"page\"`.\n\n## Доступні імена\n\nКожен інтерактивний елемент потребує імені:\n\n- видимий текст (`<button>Зберегти</button>`),\n- `<label for>` для полів,\n- `aria-label` / `aria-labelledby` для елементів лише з іконкою,\n- `alt` для зображень (`alt=\"\"` для декоративних).\n\nВидима мітка має входити в доступне ім''я (WCAG 2.5.3, «мітка в імені»), щоб користувачі голосового керування могли назвати те, що бачать.\n\n## Клавіатура й фокус\n\n- Порядок табуляції відповідає порядку в DOM, тож тримайте візуальний і DOM-порядок узгодженими. Уникайте додатних `tabindex`.\n- Ніколи не прибирайте обведення фокусу без заміни: стилізуйте `:focus-visible`.\n- Модальні вікна: перенесіть фокус усередину, утримуйте його там, закривайте на Escape й повертайте фокус на кнопку-тригер. Нативний `<dialog>` із `showModal()` робить більшість цього.\n- Додайте посилання «перейти до вмісту» й орієнтири.\n\n## Динамічний вміст\n\nОголошуйте зміни через живі регіони: `aria-live=\"polite\"` для статусних повідомлень, `role=\"alert\"` для помилок. У SPA свідомо переносьте фокус після зміни маршруту.\n\n## Рух і налаштування\n\nПоважайте `prefers-reduced-motion`, не запускайте автоматично анімації довші за 5 секунд без кнопки паузи й ніколи не блимайте частіше трьох разів на секунду.\n\n## Тестування\n\nАвтоматичні інструменти (axe, Lighthouse) знаходять приблизно третину проблем. Далі тестуйте вручну: навігація лише клавіатурою, зчитувач екрана (VoiceOver, NVDA), збільшення до 200% і перевірка контрасту.\n\n## Чек-лист для співбесіди\n\n- Сформулюйте перше правило ARIA й наведіть приклад.\n- Зробіть доступними кнопку лише з іконкою та власний перемикач.\n- Поясніть керування фокусом для модального вікна.\n- Опишіть, як би ви перевіряли сторінку на доступність."}'::jsonb, 8),
  ('web-performance', 'web-performance', '{"en":"Web performance: Core Web Vitals, rendering and loading","uk":"Продуктивність вебу: Core Web Vitals, рендеринг і завантаження"}'::jsonb, '{"en":"What LCP, INP and CLS measure, how the rendering pipeline works, and the techniques that actually move the numbers: less JavaScript, smarter loading, debouncing.","uk":"Що вимірюють LCP, INP і CLS, як працює конвеєр рендерингу й які прийоми справді покращують показники: менше JavaScript, розумне завантаження, debounce."}'::jsonb, '{"en":"Performance is user experience. Interviewers expect you to know what to measure, why pages get slow, and which fixes matter.\n\n## Core Web Vitals\n\n| Metric | Measures | Good |\n| --- | --- | --- |\n| **LCP**, Largest Contentful Paint | when the main content appears | ≤ 2.5 s |\n| **INP**, Interaction to Next Paint | how quickly the page responds to input | ≤ 200 ms |\n| **CLS**, Cumulative Layout Shift | how much content jumps around | ≤ 0.1 |\n\nMeasure with real-user data (CrUX, `web-vitals` library) and diagnose with Lighthouse and the DevTools Performance panel.\n\n## The rendering pipeline\n\nJavaScript → **Style** → **Layout** → **Paint** → **Composite**.\n\n- Changing `width`, `top` or fonts triggers layout, the most expensive step.\n- Changing colours triggers paint.\n- `transform` and `opacity` can be handled by the compositor alone, so animate those.\n- Long tasks (>50 ms) on the main thread block input, which hurts INP. Split work, yield (`await scheduler.yield()` or `setTimeout`), or move it to a Web Worker.\n\n## Loading faster (LCP)\n\n- Ship less JavaScript: code-split routes and heavy widgets (`import()`), tree-shake, and drop unused dependencies.\n- Prioritise the hero: `<link rel=\"preload\">` its image, `fetchpriority=\"high\"`, modern formats (AVIF/WebP), responsive `srcset`.\n- Render HTML on the server or statically (SSR/SSG) so content doesn''t wait for JS.\n- Cache aggressively with fingerprinted assets and a CDN. Use `font-display: swap` and preconnect to critical origins.\n- Lazy-load below-the-fold images and iframes (`loading=\"lazy\"`).\n\n## Avoiding layout shift (CLS)\n\nReserve space: set `width`/`height` (or `aspect-ratio`) on images and embeds, keep skeletons the same size as the content, and never insert banners above existing content.\n\n## Doing less work\n\n**Debounce** waits until events stop (search input, resize). **Throttle** runs at most once per interval (scroll position, mouse move):\n\n```js\nfunction debounce(fn, wait) {\n  let timer;\n  return function (...args) {\n    clearTimeout(timer);\n    timer = setTimeout(() => fn.apply(this, args), wait);\n  };\n}\n```\n\nIn frameworks, avoid unnecessary re-renders (memoise expensive subtrees, keep state local), and virtualise long lists so only the visible rows render.\n\n## Memory\n\nLeaks come from forgotten listeners, timers, detached DOM nodes held in closures, and ever-growing caches. Use the Memory panel''s heap snapshots to find them.\n\n## Interview checklist\n\n- Name and explain LCP, INP and CLS.\n- Explain why `transform` animations are cheaper than `top`/`left`.\n- List concrete loading optimisations for the largest element.\n- Implement debounce and throttle, and say when to use each.","uk":"Продуктивність є частиною досвіду користувача. Інтерв''юери очікують, що ви знаєте, що вимірювати, чому сторінки сповільнюються і які виправлення мають значення.\n\n## Core Web Vitals\n\n| Метрика | Що вимірює | Добре |\n| --- | --- | --- |\n| **LCP**, Largest Contentful Paint | коли з''являється основний вміст | ≤ 2,5 с |\n| **INP**, Interaction to Next Paint | наскільки швидко сторінка реагує на дії | ≤ 200 мс |\n| **CLS**, Cumulative Layout Shift | наскільки «стрибає» вміст | ≤ 0,1 |\n\nВимірюйте на даних реальних користувачів (CrUX, бібліотека `web-vitals`), а діагностуйте в Lighthouse і на панелі Performance у DevTools.\n\n## Конвеєр рендерингу\n\nJavaScript → **Style** → **Layout** → **Paint** → **Composite**.\n\n- Зміна `width`, `top` чи шрифтів запускає layout, найдорожчий крок.\n- Зміна кольорів запускає paint.\n- `transform` і `opacity` може обробити сам композитор, тож анімуйте саме їх.\n- Довгі задачі (>50 мс) у головному потоці блокують введення, що погіршує INP. Розбивайте роботу, поступайтеся потоком (`await scheduler.yield()` або `setTimeout`) або винесіть її у Web Worker.\n\n## Швидше завантаження (LCP)\n\n- Відправляйте менше JavaScript: розділяйте код маршрутів і важких віджетів (`import()`), прибирайте невикористаний код і зайві залежності.\n- Пріоритезуйте головний елемент: `<link rel=\"preload\">` для його зображення, `fetchpriority=\"high\"`, сучасні формати (AVIF/WebP), адаптивний `srcset`.\n- Рендерте HTML на сервері чи статично (SSR/SSG), щоб вміст не чекав на JS.\n- Агресивно кешуйте ресурси з відбитками в назвах і використовуйте CDN. Задавайте `font-display: swap` і preconnect до критичних джерел.\n- Ліниво завантажуйте зображення й iframe нижче першого екрана (`loading=\"lazy\"`).\n\n## Уникнення зсувів (CLS)\n\nРезервуйте місце: задавайте `width`/`height` (або `aspect-ratio`) зображенням і вбудовуванням, робіть скелетони того самого розміру, що й вміст, і ніколи не вставляйте банери над наявним вмістом.\n\n## Менше роботи\n\n**Debounce** чекає, доки події припиняться (пошукове поле, resize). **Throttle** виконує не частіше за раз на інтервал (позиція прокрутки, рух миші):\n\n```js\nfunction debounce(fn, wait) {\n  let timer;\n  return function (...args) {\n    clearTimeout(timer);\n    timer = setTimeout(() => fn.apply(this, args), wait);\n  };\n}\n```\n\nУ фреймворках уникайте зайвих ререндерів (мемоізуйте дорогі піддерева, тримайте стан локально) і віртуалізуйте довгі списки, щоб рендерилися лише видимі рядки.\n\n## Пам''ять\n\nВитоки виникають через забуті обробники, таймери, від''єднані вузли DOM, які тримають замикання, і кеші, що постійно ростуть. Шукайте їх за знімками купи на панелі Memory.\n\n## Чек-лист для співбесіди\n\n- Назвіть і поясніть LCP, INP і CLS.\n- Поясніть, чому анімації через `transform` дешевші за `top`/`left`.\n- Перелічіть конкретні оптимізації завантаження для найбільшого елемента.\n- Реалізуйте debounce і throttle та скажіть, коли що використовувати."}'::jsonb, 8)
) as v(slug, skill_slug, title, summary, body, reading_minutes)
join public.skills s on s.slug = v.skill_slug
on conflict (slug) do update set skill_id = excluded.skill_id, title = excluded.title, summary = excluded.summary,
  body = excluded.body, reading_minutes = excluded.reading_minutes, updated_at = now();

insert into public.tasks (slug, kind, complexity, est_seconds, title, prompt, lecture_id, quiz, practice, published, updated_at)
select v.slug, v.kind::public.task_kind, v.complexity, v.est_seconds, v.title, v.prompt, l.id, v.quiz, v.practice, true, now() from (values
  ('ng-binding-syntax', 'quiz', 1, 60, '{"en":"Binding syntax","uk":"Синтаксис прив''язок"}'::jsonb, '{"en":"Which binding passes data **from the template to the component class** when the user clicks?","uk":"Яка прив''язка передає дані **з шаблону в клас компонента**, коли користувач клікає?"}'::jsonb, 'angular', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"`[click]=\"save()\"`","uk":"`[click]=\"save()\"`"}},{"id":"b","text":{"en":"`(click)=\"save()\"`","uk":"`(click)=\"save()\"`"}},{"id":"c","text":{"en":"`{{ save() }}`","uk":"`{{ save() }}`"}},{"id":"d","text":{"en":"`*click=\"save()\"`","uk":"`*click=\"save()\"`"}}]}'::jsonb, null::jsonb),
  ('ng-oninit-vs-constructor', 'quiz', 2, 90, '{"en":"Constructor vs ngOnInit","uk":"Конструктор чи ngOnInit"}'::jsonb, '{"en":"Why load data in `ngOnInit` rather than in the constructor?","uk":"Чому дані краще завантажувати в `ngOnInit`, а не в конструкторі?"}'::jsonb, 'angular', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"`@Input` values are not set yet when the constructor runs","uk":"Під час виконання конструктора значення `@Input` ще не встановлені"}},{"id":"b","text":{"en":"Services can''t be injected into constructors","uk":"Сервіси не можна впроваджувати в конструктори"}},{"id":"c","text":{"en":"The constructor runs on every change detection cycle","uk":"Конструктор виконується в кожному циклі виявлення змін"}},{"id":"d","text":{"en":"`ngOnInit` runs before the constructor","uk":"`ngOnInit` виконується раніше за конструктор"}}]}'::jsonb, null::jsonb),
  ('ng-onpush-mutation', 'quiz', 3, 120, '{"en":"OnPush and mutation","uk":"OnPush і мутація"}'::jsonb, '{"en":"The child list uses `ChangeDetectionStrategy.OnPush`. After `add()` runs, the child doesn''t show the new item. Why?","uk":"Дочірній список використовує `ChangeDetectionStrategy.OnPush`. Після виклику `add()` новий елемент у ньому не з''являється. Чому?"}'::jsonb, 'angular', '{"mode":"single","code":"// parent\nitems = [''a'', ''b''];\nadd() {\n  this.items.push(''c'');\n}\n\n// template\n<app-list [items]=\"items\"></app-list>","codeLanguage":"ts","options":[{"id":"a","text":{"en":"`push` mutates the same array, so the `@Input` reference didn''t change","uk":"`push` змінює той самий масив, тож посилання `@Input` не змінилося"}},{"id":"b","text":{"en":"OnPush components never update after the first render","uk":"OnPush-компоненти ніколи не оновлюються після першого рендеру"}},{"id":"c","text":{"en":"`*ngFor` doesn''t support arrays of strings","uk":"`*ngFor` не підтримує масиви рядків"}},{"id":"d","text":{"en":"Zone.js doesn''t patch click events","uk":"Zone.js не перехоплює події кліку"}}]}'::jsonb, null::jsonb),
  ('ng-provider-scope', 'quiz', 3, 120, '{"en":"Provider scope","uk":"Область дії провайдера"}'::jsonb, '{"en":"`TimerService` is listed in a component''s `providers` array. Two instances of that component are on the page. How many `TimerService` instances exist?","uk":"`TimerService` вказано в масиві `providers` компонента. На сторінці два екземпляри цього компонента. Скільки існує екземплярів `TimerService`?"}'::jsonb, 'angular', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"One, services are always singletons","uk":"Один, сервіси завжди синглтони"}},{"id":"b","text":{"en":"Two, one per component instance","uk":"Два, по одному на екземпляр компонента"}},{"id":"c","text":{"en":"Zero until `providedIn: \"root\"` is added","uk":"Нуль, доки не додано `providedIn: \"root\"`"}},{"id":"d","text":{"en":"It depends on change detection strategy","uk":"Залежить від стратегії виявлення змін"}}]}'::jsonb, null::jsonb),
  ('ng-async-pipe', 'quiz', 4, 150, '{"en":"async pipe","uk":"async pipe"}'::jsonb, '{"en":"What are the advantages of `user$ | async` over subscribing in the component? Select all that apply.","uk":"Які переваги `user$ | async` над підпискою в компоненті? Оберіть усі правильні."}'::jsonb, 'angular', '{"mode":"multi","codeLanguage":"ts","options":[{"id":"a","text":{"en":"It unsubscribes automatically when the component is destroyed","uk":"Автоматично відписується, коли компонент знищено"}},{"id":"b","text":{"en":"It marks OnPush components for check when a value arrives","uk":"Позначає OnPush-компоненти для перевірки, коли надходить значення"}},{"id":"c","text":{"en":"It makes the HTTP request run only once for any number of `async` pipes","uk":"Гарантує один HTTP-запит для будь-якої кількості `async` pipe"}},{"id":"d","text":{"en":"It removes the need to handle errors","uk":"Позбавляє потреби обробляти помилки"}}]}'::jsonb, null::jsonb),
  ('ng-quantity-stepper', 'practice', 3, 900, '{"en":"Quantity stepper component","uk":"Компонент-лічильник кількості"}'::jsonb, '{"en":"Implement `StepperComponent` (`app-stepper`):\n\n- Inputs: `value`, `min`, `max`. Output: `valueChange`.\n- Render a `−` button labelled `Decrease`, the value in an element with `data-testid=\"value\"`, and a `+` button labelled `Increase` (use `aria-label`).\n- Clicking emits the new value through `valueChange`. Don''t mutate `value` yourself: the parent owns it.\n- Disable `Decrease` at `min` and `Increase` at `max`.\n\nThe parent `AppComponent` already wires it up and shows the total.","uk":"Реалізуйте `StepperComponent` (`app-stepper`):\n\n- Вхідні дані: `value`, `min`, `max`. Вихід: `valueChange`.\n- Відрендерте кнопку `−` з міткою `Decrease`, значення в елементі з `data-testid=\"value\"` і кнопку `+` з міткою `Increase` (використайте `aria-label`).\n- Клік надсилає нове значення через `valueChange`. Не змінюйте `value` самостійно: ним володіє батько.\n- Вимикайте `Decrease` на `min` і `Increase` на `max`.\n\nБатьківський `AppComponent` уже під''єднує компонент і показує суму."}'::jsonb, 'angular', null::jsonb, '{"framework":"angular","files":{"/src/app/stepper.component.ts":"import { Component, EventEmitter, Input, Output } from \"@angular/core\";\n\n@Component({\n  selector: \"app-stepper\",\n  template: `\n    <!-- TODO: decrease button, value, increase button -->\n    <span data-testid=\"value\">{{ value }}</span>\n  `,\n})\nexport class StepperComponent {\n  @Input() value = 0;\n  @Input() min = 0;\n  @Input() max = 10;\n  @Output() valueChange = new EventEmitter<number>();\n}\n","/src/app/app.component.ts":"import { Component } from \"@angular/core\";\n\n@Component({\n  selector: \"app-root\",\n  template: `\n    <h1>Cart</h1>\n    <p>Coffee beans</p>\n    <app-stepper [value]=\"quantity\" [min]=\"1\" [max]=\"5\" (valueChange)=\"quantity = $event\"></app-stepper>\n    <p data-testid=\"total\">Total: {{ quantity * 12 }} USD</p>\n  `,\n})\nexport class AppComponent {\n  quantity = 1;\n}\n","/src/app/app.module.ts":"import { NgModule } from \"@angular/core\";\nimport { BrowserModule } from \"@angular/platform-browser\";\nimport { AppComponent } from \"./app.component\";\nimport { StepperComponent } from \"./stepper.component\";\n\n@NgModule({\n  declarations: [AppComponent, StepperComponent],\n  imports: [BrowserModule],\n  bootstrap: [AppComponent],\n})\nexport class AppModule {}\n"},"visibleFiles":["/src/app/stepper.component.ts","/src/app/app.component.ts"],"activeFile":"/src/app/stepper.component.ts","tests":"import { describe, it, expect, screen, user } from \"./test-kit\";\n\ndescribe(\"app-stepper\", () => {\n  it(\"starts at the parent value and disables Decrease at min\", async () => {\n    expect(await screen.findByTestId(\"value\")).toHaveTextContent(\"1\");\n    expect(screen.getByRole(\"button\", { name: \"Decrease\" })).toBeDisabled();\n  });\n  it(\"increases through the parent (two-way data flow)\", async () => {\n    await user.click(await screen.findByRole(\"button\", { name: \"Increase\" }));\n    await user.click(screen.getByRole(\"button\", { name: \"Increase\" }));\n    expect(screen.getByTestId(\"value\")).toHaveTextContent(\"3\");\n    expect(screen.getByTestId(\"total\")).toHaveTextContent(\"Total: 36 USD\");\n  });\n  it(\"stops at max\", async () => {\n    const inc = await screen.findByRole(\"button\", { name: \"Increase\" });\n    await user.click(inc);\n    await user.click(inc);\n    await user.click(inc);\n    expect(screen.getByTestId(\"value\")).toHaveTextContent(\"5\");\n    expect(inc).toBeDisabled();\n  });\n  it(\"decreases\", async () => {\n    await user.click(await screen.findByRole(\"button\", { name: \"Decrease\" }));\n    expect(screen.getByTestId(\"value\")).toHaveTextContent(\"4\");\n  });\n});\n","testCount":4}'::jsonb),
  ('arr-default-sort', 'quiz', 1, 60, '{"en":"Default sort","uk":"Сортування за замовчуванням"}'::jsonb, '{"en":"What does `[10, 1, 5, 100].sort()` return?","uk":"Що повертає `[10, 1, 5, 100].sort()`?"}'::jsonb, 'arrays-strings', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"`[1, 5, 10, 100]`","uk":"`[1, 5, 10, 100]`"}},{"id":"b","text":{"en":"`[1, 10, 100, 5]`","uk":"`[1, 10, 100, 5]`"}},{"id":"c","text":{"en":"`[100, 10, 5, 1]`","uk":"`[100, 10, 5, 1]`"}},{"id":"d","text":{"en":"It throws without a comparator","uk":"Без компаратора кидає помилку"}}]}'::jsonb, null::jsonb),
  ('arr-mutating-methods', 'quiz', 2, 90, '{"en":"Which methods mutate?","uk":"Які методи змінюють масив?"}'::jsonb, '{"en":"Which of these **mutate** the original array? Select all that apply.","uk":"Які з цих методів **змінюють** вихідний масив? Оберіть усі правильні."}'::jsonb, 'arrays-strings', '{"mode":"multi","codeLanguage":"ts","options":[{"id":"a","text":{"en":"`sort`","uk":"`sort`"}},{"id":"b","text":{"en":"`toSorted`","uk":"`toSorted`"}},{"id":"c","text":{"en":"`splice`","uk":"`splice`"}},{"id":"d","text":{"en":"`slice`","uk":"`slice`"}},{"id":"e","text":{"en":"`reverse`","uk":"`reverse`"}}]}'::jsonb, null::jsonb),
  ('arr-reduce-initial', 'quiz', 2, 90, '{"en":"reduce without an initial value","uk":"reduce без початкового значення"}'::jsonb, '{"en":"What happens when `items` is an empty array?","uk":"Що станеться, якщо `items` є порожнім масивом?"}'::jsonb, 'arrays-strings', '{"mode":"single","code":"const total = items.reduce((sum, item) => sum + item.price);","codeLanguage":"js","options":[{"id":"a","text":{"en":"Returns `0`","uk":"Повертає `0`"}},{"id":"b","text":{"en":"Returns `undefined`","uk":"Повертає `undefined`"}},{"id":"c","text":{"en":"Throws `TypeError: Reduce of empty array with no initial value`","uk":"Кидає `TypeError: Reduce of empty array with no initial value`"}},{"id":"d","text":{"en":"Returns `NaN`","uk":"Повертає `NaN`"}}]}'::jsonb, null::jsonb),
  ('arr-dedupe-complexity', 'quiz', 3, 120, '{"en":"Faster de-duplication","uk":"Швидше видалення дублікатів"}'::jsonb, '{"en":"This de-duplication is slow for 100k items. Which rewrite keeps the first-seen order and runs in O(n)?","uk":"Це видалення дублікатів повільне для 100 тис. елементів. Який варіант зберігає порядок першої появи й працює за O(n)?"}'::jsonb, 'arrays-strings', '{"mode":"single","code":"const unique = items.filter((x, i) => items.indexOf(x) === i);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`[...new Set(items)]`","uk":"`[...new Set(items)]`"}},{"id":"b","text":{"en":"`items.sort().filter((x, i, a) => x !== a[i - 1])`","uk":"`items.sort().filter((x, i, a) => x !== a[i - 1])`"}},{"id":"c","text":{"en":"`items.reduce((acc, x) => acc.concat(x), [])`","uk":"`items.reduce((acc, x) => acc.concat(x), [])`"}},{"id":"d","text":{"en":"`Array.from(items).reverse()`","uk":"`Array.from(items).reverse()`"}}]}'::jsonb, null::jsonb),
  ('str-emoji-reverse', 'quiz', 4, 120, '{"en":"Reversing Unicode strings","uk":"Розворот рядків Unicode"}'::jsonb, '{"en":"Why can `s.split(\"\").reverse().join(\"\")` corrupt emoji like 😀?","uk":"Чому `s.split(\"\").reverse().join(\"\")` може зіпсувати емодзі на кшталт 😀?"}'::jsonb, 'arrays-strings', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"`split(\"\")` splits into UTF-16 code units, separating surrogate pairs","uk":"`split(\"\")` ділить на кодові одиниці UTF-16 і розриває сурогатні пари"}},{"id":"b","text":{"en":"`reverse` doesn''t work on strings","uk":"`reverse` не працює з рядками"}},{"id":"c","text":{"en":"`join` removes non-ASCII characters","uk":"`join` видаляє не-ASCII символи"}},{"id":"d","text":{"en":"Emoji are stored as two separate strings","uk":"Емодзі зберігаються як два окремі рядки"}}]}'::jsonb, null::jsonb),
  ('str-group-anagrams', 'practice', 3, 900, '{"en":"Group anagrams","uk":"Групування анаграм"}'::jsonb, '{"en":"Implement `groupAnagrams(words)`. Words are anagrams if they use the same letters, **ignoring case and non-letter characters**.\n\n- Return groups in the order their first word appears, and words inside a group in input order.\n- Keep the original spelling of each word.\n\n```ts\ngroupAnagrams([\"Listen\", \"enlist\", \"google\", \"Silent\"])\n// [[\"Listen\", \"enlist\", \"Silent\"], [\"google\"]]\n```","uk":"Реалізуйте `groupAnagrams(words)`. Слова є анаграмами, якщо складаються з тих самих літер, **без урахування регістру й небуквених символів**.\n\n- Повертайте групи в порядку появи їхнього першого слова, а слова всередині групи в порядку вхідних даних.\n- Зберігайте оригінальне написання кожного слова.\n\n```ts\ngroupAnagrams([\"Listen\", \"enlist\", \"google\", \"Silent\"])\n// [[\"Listen\", \"enlist\", \"Silent\"], [\"google\"]]\n```"}'::jsonb, 'arrays-strings', null::jsonb, '{"framework":"vanilla-ts","files":{"/src/anagrams.ts":"export function groupAnagrams(words: string[]): string[][] {\n  // TODO\n  return words.map((w) => [w]);\n}\n","/index.ts":"import \"./styles.css\";\nimport { groupAnagrams } from \"./src/anagrams\";\n\nconst groups = groupAnagrams([\"Listen\", \"enlist\", \"google\", \"Silent\", \"inlets\", \"banana\"]);\ndocument.getElementById(\"app\")!.innerHTML =\n  \"<h1>Anagram groups</h1><ul>\" + groups.map((g) => `<li>${g.join(\", \")}</li>`).join(\"\") + \"</ul>\";\n"},"visibleFiles":["/src/anagrams.ts","/index.ts"],"activeFile":"/src/anagrams.ts","tests":"import { describe, it, expect, screen } from \"./test-kit\";\nimport { groupAnagrams } from \"../src/anagrams\";\n\ndescribe(\"groupAnagrams\", () => {\n  it(\"groups words with the same letters\", () => {\n    expect(groupAnagrams([\"eat\", \"tea\", \"tan\", \"ate\", \"nat\", \"bat\"])).toEqual([[\"eat\", \"tea\", \"ate\"], [\"tan\", \"nat\"], [\"bat\"]]);\n  });\n  it(\"ignores case and keeps the original spelling\", () => {\n    expect(groupAnagrams([\"Listen\", \"enlist\", \"google\", \"Silent\"])).toEqual([[\"Listen\", \"enlist\", \"Silent\"], [\"google\"]]);\n  });\n  it(\"ignores non-letter characters\", () => {\n    expect(groupAnagrams([\"Dormitory\", \"dirty room!\", \"x\"])).toEqual([[\"Dormitory\", \"dirty room!\"], [\"x\"]]);\n  });\n  it(\"does not merge words with different letter counts\", () => {\n    expect(groupAnagrams([\"aab\", \"abb\"])).toEqual([[\"aab\"], [\"abb\"]]);\n  });\n  it(\"handles an empty list\", () => expect(groupAnagrams([])).toEqual([]));\n  it(\"renders the demo\", async () => {\n    expect(await screen.findAllByRole(\"listitem\")).toHaveLength(3);\n  });\n});\n","testCount":6}'::jsonb),
  ('async-event-loop-order', 'quiz', 2, 90, '{"en":"Event loop order","uk":"Порядок у циклі подій"}'::jsonb, '{"en":"What does this code print?","uk":"Що виведе цей код?"}'::jsonb, 'async-javascript', '{"mode":"single","code":"console.log(1);\nsetTimeout(() => console.log(2), 0);\nPromise.resolve().then(() => console.log(3));\nconsole.log(4);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`1 2 3 4`","uk":"`1 2 3 4`"}},{"id":"b","text":{"en":"`1 4 3 2`","uk":"`1 4 3 2`"}},{"id":"c","text":{"en":"`1 4 2 3`","uk":"`1 4 2 3`"}},{"id":"d","text":{"en":"`1 3 4 2`","uk":"`1 3 4 2`"}}]}'::jsonb, null::jsonb),
  ('async-all-settled', 'quiz', 2, 90, '{"en":"Choosing a combinator","uk":"Вибір комбінатора"}'::jsonb, '{"en":"You load 5 independent widgets and want to render every one that succeeds, showing an error only for the failed ones. Which combinator fits?","uk":"Ви завантажуєте 5 незалежних віджетів і хочете показати всі успішні, а помилку лише для невдалих. Який комбінатор підходить?"}'::jsonb, 'async-javascript', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"`Promise.all`","uk":"`Promise.all`"}},{"id":"b","text":{"en":"`Promise.allSettled`","uk":"`Promise.allSettled`"}},{"id":"c","text":{"en":"`Promise.race`","uk":"`Promise.race`"}},{"id":"d","text":{"en":"`Promise.any`","uk":"`Promise.any`"}}]}'::jsonb, null::jsonb),
  ('async-foreach-await', 'quiz', 3, 120, '{"en":"await in forEach","uk":"await у forEach"}'::jsonb, '{"en":"What''s wrong with this function?","uk":"Що не так із цією функцією?"}'::jsonb, 'async-javascript', '{"mode":"single","code":"async function save(files) {\n  files.forEach(async (file) => {\n    await upload(file);\n  });\n  console.log(\"done\");\n}","codeLanguage":"js","options":[{"id":"a","text":{"en":"`forEach` ignores the returned promises, so `save` returns before the uploads finish and their errors are unhandled","uk":"`forEach` ігнорує повернені проміси, тож `save` завершується раніше за завантаження, а їхні помилки не обробляються"}},{"id":"b","text":{"en":"`await` is a syntax error inside arrow functions","uk":"`await` дає синтаксичну помилку всередині стрілкових функцій"}},{"id":"c","text":{"en":"The uploads run one after another, which is slow","uk":"Завантаження виконуються одне за одним, що повільно"}},{"id":"d","text":{"en":"Nothing, it waits for every upload","uk":"Нічого, функція чекає на кожне завантаження"}}]}'::jsonb, null::jsonb),
  ('async-sequential-vs-parallel', 'quiz', 3, 120, '{"en":"Sequential awaits","uk":"Послідовні await"}'::jsonb, '{"en":"`getUser` and `getOrders` each take ~300 ms and don''t depend on each other. How long does `load` take, and how do you make it ~300 ms?","uk":"`getUser` і `getOrders` займають ~300 мс кожна й не залежать одна від одної. Скільки триває `load` і як зробити ~300 мс?"}'::jsonb, 'async-javascript', '{"mode":"single","code":"async function load() {\n  const user = await getUser();\n  const orders = await getOrders();\n  return { user, orders };\n}","codeLanguage":"js","options":[{"id":"a","text":{"en":"~300 ms already; `await` runs them in parallel","uk":"Уже ~300 мс; `await` запускає їх паралельно"}},{"id":"b","text":{"en":"~600 ms; start both first, then `await Promise.all([...])`","uk":"~600 мс; спершу запустити обидві, потім `await Promise.all([...])`"}},{"id":"c","text":{"en":"~600 ms; it can''t be faster in a single thread","uk":"~600 мс; в одному потоці швидше неможливо"}},{"id":"d","text":{"en":"~0 ms; async functions return immediately","uk":"~0 мс; async-функції повертаються одразу"}}]}'::jsonb, null::jsonb),
  ('async-promise-any', 'quiz', 4, 150, '{"en":"Fastest mirror","uk":"Найшвидше дзеркало"}'::jsonb, '{"en":"You query three mirrors and want the first **successful** response, ignoring mirrors that fail fast. What do you use, and what happens if all three fail?","uk":"Ви звертаєтеся до трьох дзеркал і хочете першу **успішну** відповідь, ігноруючи дзеркала, що швидко падають. Що використати й що станеться, якщо впадуть усі три?"}'::jsonb, 'async-javascript', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"`Promise.race`; it rejects with the last error","uk":"`Promise.race`; відхиляється з останньою помилкою"}},{"id":"b","text":{"en":"`Promise.any`; it rejects with an `AggregateError` holding all errors","uk":"`Promise.any`; відхиляється з `AggregateError`, що містить усі помилки"}},{"id":"c","text":{"en":"`Promise.all`; it resolves with the successful ones","uk":"`Promise.all`; вирішується з успішними"}},{"id":"d","text":{"en":"`Promise.allSettled`; it rejects if all fail","uk":"`Promise.allSettled`; відхиляється, якщо всі впали"}}]}'::jsonb, null::jsonb),
  ('async-map-with-concurrency', 'practice', 4, 1200, '{"en":"Map with a concurrency limit","uk":"Map з обмеженням паралельності"}'::jsonb, '{"en":"Implement `mapWithConcurrency(items, limit, fn)`:\n\n- Calls `fn(item, index)` for every item, with **at most `limit` calls in flight** at any time.\n- Starts a new call as soon as one finishes; don''t wait for whole batches.\n- Resolves with the results **in input order**.\n- Rejects as soon as any call rejects.","uk":"Реалізуйте `mapWithConcurrency(items, limit, fn)`:\n\n- Викликає `fn(item, index)` для кожного елемента, причому **одночасно виконується не більше `limit` викликів**.\n- Новий виклик стартує, щойно завершився будь-який попередній; не чекайте цілих пачок.\n- Вирішується результатами **в порядку вхідних даних**.\n- Відхиляється, щойно будь-який виклик відхилено."}'::jsonb, 'async-javascript', null::jsonb, '{"framework":"vanilla-ts","files":{"/src/mapWithConcurrency.ts":"export async function mapWithConcurrency<T, R>(\n  items: T[],\n  limit: number,\n  fn: (item: T, index: number) => Promise<R>,\n): Promise<R[]> {\n  // TODO: at most `limit` calls at a time, results in input order\n  const results: R[] = [];\n  for (let i = 0; i < items.length; i++) results.push(await fn(items[i], i));\n  return results;\n}\n","/index.ts":"import \"./styles.css\";\nimport { mapWithConcurrency } from \"./src/mapWithConcurrency\";\n\nconst sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));\nconst app = document.getElementById(\"app\")!;\napp.innerHTML = \"<h1>Downloads</h1><ol id=\\\"log\\\"></ol>\";\nconst log = document.getElementById(\"log\")!;\n\nmapWithConcurrency([300, 100, 200, 50, 150], 2, async (ms, i) => {\n  log.insertAdjacentHTML(\"beforeend\", `<li>start #${i}</li>`);\n  await sleep(ms);\n  log.insertAdjacentHTML(\"beforeend\", `<li>done #${i}</li>`);\n  return ms;\n});\n"},"visibleFiles":["/src/mapWithConcurrency.ts","/index.ts"],"activeFile":"/src/mapWithConcurrency.ts","tests":"import { describe, it, expect, sleep } from \"./test-kit\";\nimport { mapWithConcurrency } from \"../src/mapWithConcurrency\";\n\nfunction tracker() {\n  let active = 0;\n  let peak = 0;\n  return {\n    get peak() { return peak; },\n    async run<T>(ms: number, value: T) {\n      active++;\n      peak = Math.max(peak, active);\n      await sleep(ms);\n      active--;\n      return value;\n    },\n  };\n}\n\ndescribe(\"mapWithConcurrency\", () => {\n  it(\"keeps results in input order\", async () => {\n    const out = await mapWithConcurrency([30, 10, 20], 3, (ms, i) => sleep(ms).then(() => i * 10));\n    expect(out).toEqual([0, 10, 20]);\n  });\n  it(\"never exceeds the limit\", async () => {\n    const t = tracker();\n    await mapWithConcurrency([20, 20, 20, 20, 20, 20], 2, (ms, i) => t.run(ms, i));\n    expect(t.peak).toBe(2);\n  });\n  it(\"runs in parallel up to the limit (not one by one)\", async () => {\n    const t = tracker();\n    const started = Date.now();\n    await mapWithConcurrency([60, 60, 60, 60], 4, (ms, i) => t.run(ms, i));\n    expect(t.peak).toBe(4);\n    expect(Date.now() - started).toBeLessThan(200);\n  });\n  it(\"starts the next task as soon as a slot frees up\", async () => {\n    const order: string[] = [];\n    await mapWithConcurrency([80, 10, 10, 10], 2, async (ms, i) => {\n      order.push(\"start\" + i);\n      await sleep(ms);\n      return i;\n    });\n    expect(order).toEqual([\"start0\", \"start1\", \"start2\", \"start3\"]);\n  });\n  it(\"handles an empty list and a limit larger than the list\", async () => {\n    expect(await mapWithConcurrency([], 3, async (x) => x)).toEqual([]);\n    expect(await mapWithConcurrency([1, 2], 10, async (x) => x * 2)).toEqual([2, 4]);\n  });\n  it(\"rejects when a task fails\", async () => {\n    await expect(mapWithConcurrency([1, 2, 3], 2, async (x) => { if (x === 2) throw new Error(\"boom\"); return x; })).rejects.toThrow(\"boom\");\n  });\n});\n","testCount":6}'::jsonb),
  ('bigo-nested-loops', 'quiz', 1, 60, '{"en":"Nested loops","uk":"Вкладені цикли"}'::jsonb, '{"en":"What is the time complexity of this function for an array of length n?","uk":"Яка часова складність цієї функції для масиву довжини n?"}'::jsonb, 'big-o', '{"mode":"single","code":"function hasDuplicate(a) {\n  for (let i = 0; i < a.length; i++)\n    for (let j = i + 1; j < a.length; j++)\n      if (a[i] === a[j]) return true;\n  return false;\n}","codeLanguage":"js","options":[{"id":"a","text":{"en":"O(n)","uk":"O(n)"}},{"id":"b","text":{"en":"O(n log n)","uk":"O(n log n)"}},{"id":"c","text":{"en":"O(n²)","uk":"O(n²)"}},{"id":"d","text":{"en":"O(2n)","uk":"O(2n)"}}]}'::jsonb, null::jsonb),
  ('bigo-includes-in-loop', 'quiz', 2, 90, '{"en":"Hidden linear cost","uk":"Прихована лінійна вартість"}'::jsonb, '{"en":"`users` has n items and `bannedIds` has m items. What''s the complexity, and how do you improve it?","uk":"`users` має n елементів, а `bannedIds` має m. Яка складність і як її покращити?"}'::jsonb, 'big-o', '{"mode":"single","code":"const allowed = users.filter((u) => !bannedIds.includes(u.id));","codeLanguage":"js","options":[{"id":"a","text":{"en":"O(n + m); it''s already optimal","uk":"O(n + m); уже оптимально"}},{"id":"b","text":{"en":"O(n·m); build `new Set(bannedIds)` once and use `has` → O(n + m)","uk":"O(n·m); один раз побудувати `new Set(bannedIds)` і використати `has` → O(n + m)"}},{"id":"c","text":{"en":"O(n log m); sort `bannedIds` first","uk":"O(n log m); спершу відсортувати `bannedIds`"}},{"id":"d","text":{"en":"O(1); `filter` is native code","uk":"O(1); `filter` написано нативним кодом"}}]}'::jsonb, null::jsonb),
  ('bigo-halving', 'quiz', 2, 90, '{"en":"Halving loop","uk":"Цикл з діленням навпіл"}'::jsonb, '{"en":"What is the time complexity of this loop?","uk":"Яка часова складність цього циклу?"}'::jsonb, 'big-o', '{"mode":"single","code":"let steps = 0;\nwhile (n > 0) {\n  n = Math.floor(n / 2);\n  steps++;\n}","codeLanguage":"js","options":[{"id":"a","text":{"en":"O(1)","uk":"O(1)"}},{"id":"b","text":{"en":"O(log n)","uk":"O(log n)"}},{"id":"c","text":{"en":"O(n)","uk":"O(n)"}},{"id":"d","text":{"en":"O(√n)","uk":"O(√n)"}}]}'::jsonb, null::jsonb),
  ('bigo-amortized-push', 'quiz', 3, 120, '{"en":"Amortised O(1)","uk":"Амортизоване O(1)"}'::jsonb, '{"en":"Why is `array.push` described as O(1) **amortised** rather than plain O(1)?","uk":"Чому `array.push` описують як **амортизоване** O(1), а не просто O(1)?"}'::jsonb, 'big-o', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"Occasionally the backing storage is reallocated and copied (O(n)), but the average cost per push stays constant","uk":"Інколи сховище перевиділяється й копіюється (O(n)), але середня вартість одного push залишається сталою"}},{"id":"b","text":{"en":"Because `push` is implemented in C++","uk":"Бо `push` реалізовано на C++"}},{"id":"c","text":{"en":"Because it''s O(log n) for large arrays","uk":"Бо для великих масивів він має O(log n)"}},{"id":"d","text":{"en":"Because JavaScript arrays are linked lists","uk":"Бо масиви JavaScript є зв''язними списками"}}]}'::jsonb, null::jsonb),
  ('bigo-space-recursion', 'quiz', 4, 150, '{"en":"Space of recursion","uk":"Пам''ять рекурсії"}'::jsonb, '{"en":"What is the **space** complexity of this recursive sum over an array of length n (ignoring the input)?","uk":"Яка складність **за пам''яттю** цієї рекурсивної суми масиву довжини n (не враховуючи вхідних даних)?"}'::jsonb, 'big-o', '{"mode":"single","code":"function sum(a) {\n  if (a.length === 0) return 0;\n  return a[0] + sum(a.slice(1));\n}","codeLanguage":"js","options":[{"id":"a","text":{"en":"O(1)","uk":"O(1)"}},{"id":"b","text":{"en":"O(log n)","uk":"O(log n)"}},{"id":"c","text":{"en":"O(n) for the call stack only","uk":"O(n) лише для стеку викликів"}},{"id":"d","text":{"en":"O(n²): n stack frames and an O(n) `slice` copy per call","uk":"O(n²): n кадрів стеку і копія `slice` за O(n) на кожен виклик"}}]}'::jsonb, null::jsonb),
  ('api-fetch-404', 'quiz', 1, 60, '{"en":"fetch and HTTP errors","uk":"fetch та HTTP-помилки"}'::jsonb, '{"en":"The server answers `404`. What does `await fetch(url)` do?","uk":"Сервер відповідає `404`. Що робить `await fetch(url)`?"}'::jsonb, 'browser-apis', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"Rejects with a TypeError","uk":"Відхиляється з TypeError"}},{"id":"b","text":{"en":"Resolves with a Response whose `ok` is `false` and `status` is 404","uk":"Вирішується з Response, у якого `ok` дорівнює `false`, а `status` 404"}},{"id":"c","text":{"en":"Resolves with `null`","uk":"Вирішується з `null`"}},{"id":"d","text":{"en":"Throws synchronously","uk":"Кидає помилку синхронно"}}]}'::jsonb, null::jsonb),
  ('api-localstorage-types', 'quiz', 1, 60, '{"en":"localStorage values","uk":"Значення в localStorage"}'::jsonb, '{"en":"What does this code log?","uk":"Що виведе цей код?"}'::jsonb, 'browser-apis', '{"mode":"single","code":"localStorage.setItem(\"count\", 1);\nconsole.log(localStorage.getItem(\"count\") + 2);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`3`","uk":"`3`"}},{"id":"b","text":{"en":"`\"12\"`","uk":"`\"12\"`"}},{"id":"c","text":{"en":"`NaN`","uk":"`NaN`"}},{"id":"d","text":{"en":"`undefined`","uk":"`undefined`"}}]}'::jsonb, null::jsonb),
  ('api-abort-stale', 'quiz', 3, 120, '{"en":"Stale search results","uk":"Застарілі результати пошуку"}'::jsonb, '{"en":"A search box fires a request on every keystroke. Sometimes old results overwrite newer ones. What''s the best fix?","uk":"Поле пошуку надсилає запит на кожне натискання. Іноді старі результати перезаписують новіші. Яке виправлення найкраще?"}'::jsonb, 'browser-apis', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"Abort the previous request with an `AbortController` before starting a new one (and debounce input)","uk":"Скасовувати попередній запит через `AbortController` перед новим (і додати debounce до введення)"}},{"id":"b","text":{"en":"Use `sync: true` in fetch options","uk":"Використати `sync: true` в опціях fetch"}},{"id":"c","text":{"en":"Sort the responses by length","uk":"Сортувати відповіді за довжиною"}},{"id":"d","text":{"en":"Store results in localStorage","uk":"Зберігати результати в localStorage"}}]}'::jsonb, null::jsonb),
  ('api-intersection-observer', 'quiz', 2, 90, '{"en":"Lazy loading","uk":"Ліниве завантаження"}'::jsonb, '{"en":"Which API is designed to tell you efficiently when an element enters the viewport?","uk":"Який API призначений для ефективного визначення, коли елемент з''являється в області перегляду?"}'::jsonb, 'browser-apis', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"`IntersectionObserver`","uk":"`IntersectionObserver`"}},{"id":"b","text":{"en":"`MutationObserver`","uk":"`MutationObserver`"}},{"id":"c","text":{"en":"A `scroll` listener calling `getBoundingClientRect()`","uk":"Обробник `scroll`, що викликає `getBoundingClientRect()`"}},{"id":"d","text":{"en":"`ResizeObserver`","uk":"`ResizeObserver`"}}]}'::jsonb, null::jsonb),
  ('api-token-storage', 'quiz', 4, 150, '{"en":"Where to keep a session","uk":"Де зберігати сесію"}'::jsonb, '{"en":"Where is a session credential least exposed to XSS?","uk":"Де облікові дані сесії найменше вразливі до XSS?"}'::jsonb, 'browser-apis', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"`localStorage`","uk":"`localStorage`"}},{"id":"b","text":{"en":"A JavaScript variable in a global object","uk":"Змінна JavaScript у глобальному об''єкті"}},{"id":"c","text":{"en":"An `HttpOnly; Secure; SameSite` cookie","uk":"Cookie з `HttpOnly; Secure; SameSite`"}},{"id":"d","text":{"en":"`sessionStorage`","uk":"`sessionStorage`"}}]}'::jsonb, null::jsonb),
  ('api-storage-with-ttl', 'practice', 3, 900, '{"en":"Storage wrapper with expiry","uk":"Обгортка сховища з терміном дії"}'::jsonb, '{"en":"Implement `createStore({ prefix, storage, now })` returning `{ set, get, remove }`:\n\n- Keys are namespaced: `set(\"user\", v)` writes `prefix + \"user\"`.\n- Values of any JSON type round-trip, including `0`, `false` and `\"\"`.\n- `set(key, value, ttlMs?)`: with a TTL, `get` returns `undefined` once `now()` passes the expiry, and removes the entry.\n- `get` never throws: corrupt JSON returns `undefined`.\n- `set` returns `false` instead of throwing when the storage is full.\n\n`storage` defaults to `localStorage` and `now` to `Date.now`; the tests inject fakes.","uk":"Реалізуйте `createStore({ prefix, storage, now })`, що повертає `{ set, get, remove }`:\n\n- Ключі мають простір імен: `set(\"user\", v)` записує `prefix + \"user\"`.\n- Значення будь-якого JSON-типу зберігаються й читаються без втрат, включно з `0`, `false` і `\"\"`.\n- `set(key, value, ttlMs?)`: з TTL метод `get` повертає `undefined`, щойно `now()` перевищить термін дії, і видаляє запис.\n- `get` ніколи не кидає помилку: зіпсований JSON повертає `undefined`.\n- `set` повертає `false` замість помилки, коли сховище переповнене.\n\n`storage` за замовчуванням дорівнює `localStorage`, а `now` дорівнює `Date.now`; тести підставляють фейки."}'::jsonb, 'browser-apis', null::jsonb, '{"framework":"vanilla-ts","files":{"/src/store.ts":"type Options = { prefix: string; storage?: Storage; now?: () => number };\n\nexport function createStore({ prefix, storage = localStorage, now = Date.now }: Options) {\n  return {\n    set(key: string, value: unknown, ttlMs?: number): boolean {\n      // TODO\n      storage.setItem(key, String(value));\n      return true;\n    },\n    get<T>(key: string): T | undefined {\n      // TODO\n      return (storage.getItem(key) ?? undefined) as T | undefined;\n    },\n    remove(key: string): void {\n      // TODO\n    },\n  };\n}\n","/index.ts":"import \"./styles.css\";\nimport { createStore } from \"./src/store\";\n\nconst store = createStore({ prefix: \"demo:\" });\nstore.set(\"visits\", (store.get<number>(\"visits\") ?? 0) + 1);\nstore.set(\"flash\", \"Saved!\", 2000);\n\ndocument.getElementById(\"app\")!.innerHTML = `<h1>Storage</h1>\n<p>Visits in this browser: <output id=\"visits\">${store.get<number>(\"visits\")}</output></p>\n<p>Flash message: <output id=\"flash\">${store.get<string>(\"flash\") ?? \"(expired)\"}</output></p>`;\n"},"visibleFiles":["/src/store.ts","/index.ts"],"activeFile":"/src/store.ts","tests":"import { describe, it, expect } from \"./test-kit\";\nimport { createStore } from \"../src/store\";\n\nclass MemoryStorage {\n  data = new Map<string, string>();\n  full = false;\n  get length() { return this.data.size; }\n  key(i: number) { return [...this.data.keys()][i] ?? null; }\n  getItem(k: string) { return this.data.has(k) ? this.data.get(k)! : null; }\n  setItem(k: string, v: string) {\n    if (this.full) throw new DOMException(\"full\", \"QuotaExceededError\");\n    this.data.set(k, String(v));\n  }\n  removeItem(k: string) { this.data.delete(k); }\n  clear() { this.data.clear(); }\n}\n\nfunction setup() {\n  const storage = new MemoryStorage();\n  let time = 1000;\n  const store = createStore({ prefix: \"app:\", storage: storage as unknown as Storage, now: () => time });\n  return { storage, store, tick: (ms: number) => (time += ms) };\n}\n\ndescribe(\"createStore\", () => {\n  it(\"round-trips JSON values under a prefix\", () => {\n    const { store, storage } = setup();\n    store.set(\"user\", { name: \"Ada\", tags: [\"x\"] });\n    expect(store.get(\"user\")).toEqual({ name: \"Ada\", tags: [\"x\"] });\n    expect([...storage.data.keys()]).toEqual([\"app:user\"]);\n  });\n  it(\"keeps falsy values\", () => {\n    const { store } = setup();\n    store.set(\"zero\", 0);\n    store.set(\"no\", false);\n    store.set(\"empty\", \"\");\n    expect(store.get(\"zero\")).toBe(0);\n    expect(store.get(\"no\")).toBe(false);\n    expect(store.get(\"empty\")).toBe(\"\");\n  });\n  it(\"returns undefined for missing keys\", () => {\n    expect(setup().store.get(\"missing\")).toBeUndefined();\n  });\n  it(\"expires entries after their TTL and removes them\", () => {\n    const { store, storage, tick } = setup();\n    store.set(\"flash\", \"hi\", 500);\n    tick(499);\n    expect(store.get(\"flash\")).toBe(\"hi\");\n    tick(2);\n    expect(store.get(\"flash\")).toBeUndefined();\n    expect(storage.data.size).toBe(0);\n  });\n  it(\"does not throw on corrupt data\", () => {\n    const { store, storage } = setup();\n    storage.data.set(\"app:bad\", \"{not json\");\n    expect(store.get(\"bad\")).toBeUndefined();\n  });\n  it(\"returns false when the storage is full\", () => {\n    const { store, storage } = setup();\n    storage.full = true;\n    expect(store.set(\"k\", 1)).toBe(false);\n  });\n  it(\"removes keys\", () => {\n    const { store } = setup();\n    store.set(\"k\", 1);\n    store.remove(\"k\");\n    expect(store.get(\"k\")).toBeUndefined();\n  });\n});\n","testCount":7}'::jsonb),
  ('closure-var-loop', 'quiz', 1, 60, '{"en":"var in a loop","uk":"var у циклі"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'closures-scope', '{"mode":"single","code":"for (var i = 0; i < 3; i++) {\n  setTimeout(() => console.log(i));\n}","codeLanguage":"js","options":[{"id":"a","text":{"en":"`0 1 2`","uk":"`0 1 2`"}},{"id":"b","text":{"en":"`3 3 3`","uk":"`3 3 3`"}},{"id":"c","text":{"en":"`undefined undefined undefined`","uk":"`undefined undefined undefined`"}},{"id":"d","text":{"en":"`2 2 2`","uk":"`2 2 2`"}}]}'::jsonb, null::jsonb),
  ('closure-tdz', 'quiz', 2, 90, '{"en":"Temporal dead zone","uk":"Temporal dead zone"}'::jsonb, '{"en":"What happens when `show()` runs?","uk":"Що станеться під час виконання `show()`?"}'::jsonb, 'closures-scope', '{"mode":"single","code":"const name = \"outer\";\nfunction show() {\n  console.log(name);\n  let name = \"inner\";\n}\nshow();","codeLanguage":"js","options":[{"id":"a","text":{"en":"Logs `undefined`","uk":"Виведе `undefined`"}},{"id":"b","text":{"en":"Logs `\"outer\"`","uk":"Виведе `\"outer\"`"}},{"id":"c","text":{"en":"Throws a `ReferenceError`","uk":"Кине `ReferenceError`"}},{"id":"d","text":{"en":"Logs `\"inner\"`","uk":"Виведе `\"inner\"`"}}]}'::jsonb, null::jsonb),
  ('closure-independent-counters', 'quiz', 2, 90, '{"en":"Independent closures","uk":"Незалежні замикання"}'::jsonb, '{"en":"What does the last line print?","uk":"Що виведе останній рядок?"}'::jsonb, 'closures-scope', '{"mode":"single","code":"function makeCounter() {\n  let count = 0;\n  return () => ++count;\n}\nconst a = makeCounter();\nconst b = makeCounter();\na(); b();\nconsole.log(a(), b() - 1);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`1 1`","uk":"`1 1`"}},{"id":"b","text":{"en":"`2 1`","uk":"`2 1`"}},{"id":"c","text":{"en":"`2 3`","uk":"`2 3`"}},{"id":"d","text":{"en":"`3 3`","uk":"`3 3`"}}]}'::jsonb, null::jsonb),
  ('closure-stale-interval', 'quiz', 4, 150, '{"en":"Stale closure in React","uk":"Застаріле замикання в React"}'::jsonb, '{"en":"This counter shows 1 and never goes higher. Why?","uk":"Цей лічильник показує 1 і далі не зростає. Чому?"}'::jsonb, 'closures-scope', '{"mode":"single","code":"const [count, setCount] = useState(0);\nuseEffect(() => {\n  const id = setInterval(() => setCount(count + 1), 1000);\n  return () => clearInterval(id);\n}, []);","codeLanguage":"tsx","options":[{"id":"a","text":{"en":"The interval callback closed over `count` from the first render (always 0); use `setCount(c => c + 1)`","uk":"Колбек інтервалу замкнув `count` з першого рендеру (завжди 0); використайте `setCount(c => c + 1)`"}},{"id":"b","text":{"en":"`setInterval` only fires once inside React effects","uk":"`setInterval` усередині ефектів React спрацьовує лише раз"}},{"id":"c","text":{"en":"React batches the updates and drops all but the first","uk":"React групує оновлення й відкидає всі, крім першого"}},{"id":"d","text":{"en":"The cleanup function clears the interval after the first tick","uk":"Функція очищення прибирає інтервал після першого спрацювання"}}]}'::jsonb, null::jsonb),
  ('closure-memoize-falsy', 'quiz', 3, 120, '{"en":"Memoize bug","uk":"Помилка в memoize"}'::jsonb, '{"en":"`slowSquare(0)` is recomputed on every call, even after the first. Why?","uk":"`slowSquare(0)` перераховується щоразу, навіть після першого виклику. Чому?"}'::jsonb, 'closures-scope', '{"mode":"single","code":"function memoize(fn) {\n  const cache = new Map();\n  return (arg) => {\n    if (cache.get(arg)) return cache.get(arg);\n    const value = fn(arg);\n    cache.set(arg, value);\n    return value;\n  };\n}","codeLanguage":"js","options":[{"id":"a","text":{"en":"Map keys can''t be numbers","uk":"Ключі Map не можуть бути числами"}},{"id":"b","text":{"en":"`cache.get(0)` is `0`, which is falsy, so the cache looks empty; check `cache.has(arg)`","uk":"`cache.get(0)` дорівнює `0`, а це хибне значення, тож кеш здається порожнім; перевіряйте `cache.has(arg)`"}},{"id":"c","text":{"en":"The closure creates a new Map on every call","uk":"Замикання створює новий Map при кожному виклику"}},{"id":"d","text":{"en":"Arrow functions can''t capture variables","uk":"Стрілкові функції не можуть захоплювати змінні"}}]}'::jsonb, null::jsonb),
  ('closure-once-and-memoize', 'practice', 2, 720, '{"en":"once() and memoize()","uk":"once() та memoize()"}'::jsonb, '{"en":"Implement two closure helpers in `src/fn.js`:\n\n- `once(fn)`: the returned function calls `fn` the first time only (with its arguments and `this`) and always returns that first result.\n- `memoize(fn)`: caches results by the **first argument**. Cached falsy values (`0`, `\"\"`, `undefined`) must count as cache hits.","uk":"Реалізуйте два допоміжні замикання в `src/fn.js`:\n\n- `once(fn)`: повернена функція викликає `fn` лише першого разу (з аргументами й `this`) і завжди повертає той перший результат.\n- `memoize(fn)`: кешує результати за **першим аргументом**. Закешовані хибні значення (`0`, `\"\"`, `undefined`) мають вважатися влученнями в кеш."}'::jsonb, 'closures-scope', null::jsonb, '{"framework":"vanilla-js","files":{"/src/fn.js":"export function once(fn) {\n  // TODO\n  return fn;\n}\n\nexport function memoize(fn) {\n  // TODO\n  return fn;\n}\n","/index.js":"import \"./styles.css\";\nimport { once, memoize } from \"./src/fn\";\n\nlet calls = 0;\nconst slowSquare = memoize((n) => {\n  calls++;\n  return n * n;\n});\n[4, 4, 0, 0, 4].forEach(slowSquare);\nconst init = once(() => \"initialised\");\n\ndocument.getElementById(\"app\").innerHTML =\n  \"<h1>Closures</h1>\" +\n  \"<p>slowSquare ran <output id=\\\"calls\\\">\" + calls + \"</output> times for 5 calls.</p>\" +\n  \"<p>\" + init() + \" / \" + init() + \"</p>\";\n"},"visibleFiles":["/src/fn.js","/index.js"],"activeFile":"/src/fn.js","tests":"import { describe, it, expect, fn, screen } from \"./test-kit\";\nimport { once, memoize } from \"../src/fn\";\n\ndescribe(\"once\", () => {\n  it(\"calls the function only once and returns the first result\", () => {\n    const spy = fn((x) => x * 2);\n    const f = once(spy);\n    expect(f(2)).toBe(4);\n    expect(f(10)).toBe(4);\n    expect(spy).toHaveBeenCalledTimes(1);\n  });\n  it(\"preserves this\", () => {\n    const obj = { n: 7, get: once(function () { return this.n; }) };\n    expect(obj.get()).toBe(7);\n  });\n});\n\ndescribe(\"memoize\", () => {\n  it(\"caches by the first argument\", () => {\n    const spy = fn((n) => n * n);\n    const sq = memoize(spy);\n    expect(sq(3)).toBe(9);\n    expect(sq(3)).toBe(9);\n    expect(spy).toHaveBeenCalledTimes(1);\n  });\n  it(\"treats falsy results as cache hits\", () => {\n    const spy = fn(() => 0);\n    const zero = memoize(spy);\n    zero(\"a\");\n    zero(\"a\");\n    expect(spy).toHaveBeenCalledTimes(1);\n  });\n  it(\"keeps separate entries per argument\", () => {\n    const spy = fn((s) => s.toUpperCase());\n    const up = memoize(spy);\n    expect(up(\"a\")).toBe(\"A\");\n    expect(up(\"b\")).toBe(\"B\");\n    expect(spy).toHaveBeenCalledTimes(2);\n  });\n  it(\"renders the demo\", async () => {\n    expect(await screen.findByText(\"2\")).toBeInTheDocument();\n  });\n});\n","testCount":6}'::jsonb),
  ('css-specificity', 'quiz', 2, 90, '{"en":"Which rule wins?","uk":"Яке правило перемагає?"}'::jsonb, '{"en":"What colour is the link?","uk":"Якого кольору буде посилання?"}'::jsonb, 'css', '{"mode":"single","code":"<nav id=\"nav\" class=\"menu\"><a class=\"link\" href=\"/\">Home</a></nav>\n\n#nav a       { color: green; }\n.menu .link  { color: red; }\na.link       { color: blue; }\nnav a        { color: orange; }","codeLanguage":"css","options":[{"id":"a","text":{"en":"red","uk":"червоного (red)"}},{"id":"b","text":{"en":"green","uk":"зеленого (green)"}},{"id":"c","text":{"en":"blue","uk":"синього (blue)"}},{"id":"d","text":{"en":"orange","uk":"помаранчевого (orange)"}}]}'::jsonb, null::jsonb),
