  ('css-flex-vs-grid', 'quiz', 2, 90, '{"en":"Flexbox or Grid","uk":"Flexbox чи Grid"}'::jsonb, '{"en":"You need a card gallery whose columns line up across rows and reflow by width. What fits best?","uk":"Потрібна галерея карток, колонки якої вирівнюються між рядками й перебудовуються залежно від ширини. Що підходить найкраще?"}'::jsonb, 'css', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"`display: grid` with `repeat(auto-fill, minmax(16rem, 1fr))`","uk":"`display: grid` з `repeat(auto-fill, minmax(16rem, 1fr))`"}},{"id":"b","text":{"en":"`display: flex` with `flex-wrap: wrap` and no widths","uk":"`display: flex` з `flex-wrap: wrap` без ширин"}},{"id":"c","text":{"en":"`float: left` on every card","uk":"`float: left` для кожної картки"}},{"id":"d","text":{"en":"A `<table>` with one cell per card","uk":"`<table>` з однією клітинкою на картку"}}]}'::jsonb, null::jsonb),
  ('css-stacking-context', 'quiz', 4, 150, '{"en":"z-index doesn''t work","uk":"z-index не працює"}'::jsonb, '{"en":"The modal has `z-index: 9999` but still appears **under** the header. What''s the most likely cause?","uk":"Модальне вікно має `z-index: 9999`, але все одно з''являється **під** шапкою. Яка найімовірніша причина?"}'::jsonb, 'css', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"The modal''s parent creates a stacking context (e.g. `transform`) with a lower z-index than the header","uk":"Батько модального вікна створює контекст накладання (наприклад, `transform`) з меншим z-index, ніж у шапки"}},{"id":"b","text":{"en":"z-index can''t exceed 999","uk":"z-index не може бути більшим за 999"}},{"id":"c","text":{"en":"z-index only works with `display: flex`","uk":"z-index працює лише з `display: flex`"}},{"id":"d","text":{"en":"The header is rendered later in the DOM, which always wins","uk":"Шапка рендериться пізніше в DOM, а це завжди перемагає"}}]}'::jsonb, null::jsonb),
  ('css-visually-hidden', 'quiz', 3, 120, '{"en":"Hidden but accessible","uk":"Приховано, але доступно"}'::jsonb, '{"en":"You want a label that screen readers announce but sighted users don''t see. Which approach works?","uk":"Потрібна мітка, яку оголошують зчитувачі екрана, але не бачать зрячі користувачі. Який підхід працює?"}'::jsonb, 'css', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"`display: none`","uk":"`display: none`"}},{"id":"b","text":{"en":"`visibility: hidden`","uk":"`visibility: hidden`"}},{"id":"c","text":{"en":"Clip it to a 1×1px absolutely positioned box with `overflow: hidden`","uk":"Обрізати до абсолютно позиціонованого блоку 1×1px з `overflow: hidden`"}},{"id":"d","text":{"en":"`opacity: 0; height: 0`","uk":"`opacity: 0; height: 0`"}}]}'::jsonb, null::jsonb),
  ('css-dashboard-layout', 'practice', 2, 900, '{"en":"Toolbar, grid and badge","uk":"Панель, сітка й бейдж"}'::jsonb, '{"en":"Edit `styles.css` (the HTML is fixed):\n\n1. `.toolbar`: a **flex** row with the brand on the left and the search on the right (`space-between`), vertically centred.\n2. `.cards`: a **grid** with a `16px` gap that fits as many ≥160px columns as possible.\n3. `.badge`: pinned to the **top-right** corner of its card, 8px from each edge.\n4. `.visually-hidden`: hidden visually but still read by screen readers (no `display: none`).\n\nThe preview updates as you type.","uk":"Відредагуйте `styles.css` (HTML фіксований):\n\n1. `.toolbar`: **flex**-рядок, де бренд ліворуч, а пошук праворуч (`space-between`), вирівняні по вертикалі по центру.\n2. `.cards`: **grid** з проміжком `16px`, що вміщує якомога більше колонок завширшки від 160px.\n3. `.badge`: закріплений у **правому верхньому** куті своєї картки, по 8px від кожного краю.\n4. `.visually-hidden`: прихований візуально, але доступний для зчитувачів екрана (без `display: none`).\n\nПопередній перегляд оновлюється під час введення."}'::jsonb, 'css', null::jsonb, '{"framework":"vanilla-js","files":{"/styles.css":"* {\n  box-sizing: border-box;\n}\n\nbody {\n  margin: 0;\n  font-family: system-ui, sans-serif;\n  background: #f7f5ef;\n}\n\n/* 1. Toolbar: brand left, search right, vertically centred */\n.toolbar {\n  padding: 12px 16px;\n  background: #0b5a43;\n  color: white;\n}\n\n/* 2. Cards: a grid with a 16px gap */\n.cards {\n  list-style: none;\n  margin: 0;\n  padding: 16px;\n}\n\n/* 3. Pin the badge to the card''s top-right corner (8px) */\n.card {\n  background: white;\n  border-radius: 12px;\n  padding: 16px;\n}\n\n.badge {\n  background: #c9a227;\n  border-radius: 999px;\n  padding: 2px 8px;\n  font-size: 12px;\n}\n\n/* 4. Hide visually, keep it for screen readers */\n.visually-hidden {\n}\n","/index.html":"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <title>Dashboard</title>\n</head>\n<body>\n  <header class=\"toolbar\">\n    <strong class=\"brand\">Dashboard</strong>\n    <form class=\"search\">\n      <label class=\"visually-hidden\" for=\"q\">Search projects</label>\n      <input id=\"q\" placeholder=\"Search…\" />\n    </form>\n  </header>\n  <main>\n    <ul class=\"cards\">\n      <li class=\"card\"><span class=\"badge\">New</span><h2>Alpha</h2><p>Design system</p></li>\n      <li class=\"card\"><h2>Beta</h2><p>Billing</p></li>\n      <li class=\"card\"><h2>Gamma</h2><p>Search</p></li>\n      <li class=\"card\"><h2>Delta</h2><p>Mobile app</p></li>\n    </ul>\n  </main>\n  <script src=\"index.js\"></script>\n</body>\n</html>\n","/index.js":"import \"./styles.css\";\n"},"visibleFiles":["/styles.css","/index.html"],"activeFile":"/styles.css","tests":"import { describe, it, expect, waitFor } from \"./test-kit\";\n\nconst css = (sel, prop) => getComputedStyle(document.querySelector(sel)).getPropertyValue(prop);\n\ndescribe(\"dashboard CSS\", () => {\n  it(\"lays out the toolbar with flexbox\", async () => {\n    await waitFor(() => expect(css(\".toolbar\", \"display\")).toBe(\"flex\"));\n    expect(css(\".toolbar\", \"justify-content\")).toBe(\"space-between\");\n    expect(css(\".toolbar\", \"align-items\")).toBe(\"center\");\n  });\n  it(\"uses a grid with a 16px gap for the cards\", () => {\n    expect(css(\".cards\", \"display\")).toBe(\"grid\");\n    expect(css(\".cards\", \"column-gap\")).toBe(\"16px\");\n    expect(css(\".cards\", \"row-gap\")).toBe(\"16px\");\n  });\n  it(\"pins the badge to the top-right corner of its card\", () => {\n    expect(css(\".card\", \"position\")).toBe(\"relative\");\n    expect(css(\".badge\", \"position\")).toBe(\"absolute\");\n    expect(css(\".badge\", \"top\")).toBe(\"8px\");\n    expect(css(\".badge\", \"right\")).toBe(\"8px\");\n  });\n  it(\"hides the search label visually but not from screen readers\", () => {\n    const label = document.querySelector(\".visually-hidden\");\n    const style = getComputedStyle(label);\n    expect(style.display).not.toBe(\"none\");\n    expect(style.visibility).not.toBe(\"hidden\");\n    expect(style.position).toBe(\"absolute\");\n    expect(label.getBoundingClientRect().width).toBeLessThanOrEqual(1);\n    expect(style.overflow).toBe(\"hidden\");\n  });\n});\n","testCount":4}'::jsonb),
  ('ds-stack-brackets', 'quiz', 1, 60, '{"en":"Matching brackets","uk":"Перевірка дужок"}'::jsonb, '{"en":"Which data structure is the natural fit for checking that brackets like `({[]})` are balanced?","uk":"Яка структура даних природно підходить для перевірки збалансованості дужок на кшталт `({[]})`?"}'::jsonb, 'data-structures', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"Queue","uk":"Черга"}},{"id":"b","text":{"en":"Stack","uk":"Стек"}},{"id":"c","text":{"en":"Heap","uk":"Купа"}},{"id":"d","text":{"en":"Set","uk":"Множина"}}]}'::jsonb, null::jsonb),
  ('ds-queue-shift', 'quiz', 2, 90, '{"en":"Queues in JavaScript","uk":"Черги в JavaScript"}'::jsonb, '{"en":"A BFS uses `queue.shift()` on an array with a million items. What''s the problem?","uk":"BFS використовує `queue.shift()` для масиву з мільйона елементів. У чому проблема?"}'::jsonb, 'data-structures', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"`shift` is O(n) because it re-indexes the array, so BFS can degrade to O(n²)","uk":"`shift` має складність O(n), бо переіндексовує масив, тож BFS може деградувати до O(n²)"}},{"id":"b","text":{"en":"`shift` returns the last element, not the first","uk":"`shift` повертає останній елемент, а не перший"}},{"id":"c","text":{"en":"Arrays can''t hold a million items","uk":"Масиви не можуть вміщувати мільйон елементів"}},{"id":"d","text":{"en":"There''s no problem; `shift` is O(1)","uk":"Проблеми немає; `shift` працює за O(1)"}}]}'::jsonb, null::jsonb),
  ('ds-two-sum-map', 'quiz', 2, 90, '{"en":"Two-sum in O(n)","uk":"Two-sum за O(n)"}'::jsonb, '{"en":"To find two numbers in an **unsorted** array that add up to a target in one pass, what do you store while scanning?","uk":"Щоб за один прохід знайти в **невідсортованому** масиві два числа із заданою сумою, що зберігати під час проходу?"}'::jsonb, 'data-structures', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"A Map from value to index of the numbers seen so far","uk":"Map від значення до індексу вже переглянутих чисел"}},{"id":"b","text":{"en":"A sorted copy of the array","uk":"Відсортовану копію масиву"}},{"id":"c","text":{"en":"A stack of differences","uk":"Стек різниць"}},{"id":"d","text":{"en":"A heap of the largest values","uk":"Купу найбільших значень"}}]}'::jsonb, null::jsonb),
  ('ds-heap-topk', 'quiz', 4, 150, '{"en":"Top-k streaming","uk":"Top-k у потоці"}'::jsonb, '{"en":"You receive a stream of 10 million scores and must keep the 100 highest at all times, with little memory. What''s the best approach?","uk":"Ви отримуєте потік із 10 мільйонів оцінок і маєте постійно тримати 100 найвищих, використовуючи мало пам''яті. Який підхід найкращий?"}'::jsonb, 'data-structures', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"Store everything and sort at the end: O(n log n) time, O(n) memory","uk":"Зберегти все й відсортувати в кінці: O(n log n) часу, O(n) пам''яті"}},{"id":"b","text":{"en":"A min-heap of size 100: replace the root when a bigger score arrives (O(n log k))","uk":"Min-купа розміру 100: замінювати корінь, коли надходить більша оцінка (O(n log k))"}},{"id":"c","text":{"en":"A max-heap of all scores","uk":"Max-купа з усіх оцінок"}},{"id":"d","text":{"en":"A stack that keeps the latest 100 scores","uk":"Стек, що тримає останні 100 оцінок"}}]}'::jsonb, null::jsonb),
  ('ds-bst-degenerate', 'quiz', 3, 120, '{"en":"Unbalanced BST","uk":"Незбалансоване BST"}'::jsonb, '{"en":"You insert 1, 2, 3, …, n in order into a plain (non-balancing) binary search tree. What is the cost of searching it?","uk":"Ви вставляєте 1, 2, 3, …, n по порядку в звичайне (незбалансоване) бінарне дерево пошуку. Яка вартість пошуку в ньому?"}'::jsonb, 'data-structures', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"O(1)","uk":"O(1)"}},{"id":"b","text":{"en":"O(log n)","uk":"O(log n)"}},{"id":"c","text":{"en":"O(n)","uk":"O(n)"}},{"id":"d","text":{"en":"O(n log n)","uk":"O(n log n)"}}]}'::jsonb, null::jsonb),
  ('ds-lru-cache', 'practice', 4, 1200, '{"en":"LRU cache","uk":"LRU-кеш"}'::jsonb, '{"en":"Implement `LRUCache` with a fixed `capacity`:\n\n- `get(key)` returns the value or `undefined`, and marks the key as **most recently used**.\n- `set(key, value)` inserts or updates the key and marks it most recent. If that exceeds the capacity, evict the **least recently used** key.\n- `size` returns the number of entries.\n- Both operations must be **O(1)**.\n\nHint: a JavaScript `Map` remembers insertion order.","uk":"Реалізуйте `LRUCache` із фіксованою місткістю `capacity`:\n\n- `get(key)` повертає значення або `undefined` і позначає ключ як **останній використаний**.\n- `set(key, value)` вставляє чи оновлює ключ і позначає його найсвіжішим. Якщо місткість перевищено, витісніть **найдавніше використаний** ключ.\n- `size` повертає кількість записів.\n- Обидві операції мають працювати за **O(1)**.\n\nПідказка: `Map` у JavaScript пам''ятає порядок вставки."}'::jsonb, 'data-structures', null::jsonb, '{"framework":"vanilla-ts","files":{"/src/lru.ts":"export class LRUCache<K, V> {\n  constructor(private capacity: number) {}\n\n  get(key: K): V | undefined {\n    // TODO\n    return undefined;\n  }\n\n  set(key: K, value: V): void {\n    // TODO\n  }\n\n  get size(): number {\n    return 0;\n  }\n}\n","/index.ts":"import \"./styles.css\";\nimport { LRUCache } from \"./src/lru\";\n\nconst cache = new LRUCache<string, number>(2);\ncache.set(\"a\", 1);\ncache.set(\"b\", 2);\ncache.get(\"a\");\ncache.set(\"c\", 3); // evicts \"b\"\n\ndocument.getElementById(\"app\")!.innerHTML = `<h1>LRU cache</h1>\n<p>a = <output id=\"a\">${cache.get(\"a\")}</output>, b = <output id=\"b\">${cache.get(\"b\")}</output>, c = <output id=\"c\">${cache.get(\"c\")}</output></p>`;\n"},"visibleFiles":["/src/lru.ts","/index.ts"],"activeFile":"/src/lru.ts","tests":"import { describe, it, expect, screen } from \"./test-kit\";\nimport { LRUCache } from \"../src/lru\";\n\ndescribe(\"LRUCache\", () => {\n  it(\"stores and returns values\", () => {\n    const c = new LRUCache<string, number>(2);\n    c.set(\"x\", 1);\n    expect(c.get(\"x\")).toBe(1);\n    expect(c.get(\"missing\")).toBeUndefined();\n    expect(c.size).toBe(1);\n  });\n  it(\"evicts the least recently used key\", () => {\n    const c = new LRUCache<string, number>(2);\n    c.set(\"a\", 1);\n    c.set(\"b\", 2);\n    c.set(\"c\", 3);\n    expect(c.get(\"a\")).toBeUndefined();\n    expect(c.size).toBe(2);\n  });\n  it(\"get() refreshes recency\", () => {\n    const c = new LRUCache<string, number>(2);\n    c.set(\"a\", 1);\n    c.set(\"b\", 2);\n    c.get(\"a\");\n    c.set(\"c\", 3);\n    expect(c.get(\"a\")).toBe(1);\n    expect(c.get(\"b\")).toBeUndefined();\n  });\n  it(\"set() on an existing key updates it without growing\", () => {\n    const c = new LRUCache<string, number>(2);\n    c.set(\"a\", 1);\n    c.set(\"b\", 2);\n    c.set(\"a\", 10);\n    c.set(\"c\", 3);\n    expect(c.get(\"a\")).toBe(10);\n    expect(c.get(\"b\")).toBeUndefined();\n    expect(c.size).toBe(2);\n  });\n  it(\"caches falsy values\", () => {\n    const c = new LRUCache<string, number>(1);\n    c.set(\"zero\", 0);\n    expect(c.get(\"zero\")).toBe(0);\n  });\n  it(\"renders the demo\", async () => {\n    expect((await screen.findByText(\"undefined\")).id).toBe(\"b\");\n  });\n});\n","testCount":6}'::jsonb),
  ('dom-target-vs-current', 'quiz', 1, 60, '{"en":"target vs currentTarget","uk":"target проти currentTarget"}'::jsonb, '{"en":"The user clicks the `<span>` inside the button. Inside the listener on `<ul>`, what is `event.currentTarget`?","uk":"Користувач клікає `<span>` усередині кнопки. Чим є `event.currentTarget` в обробнику на `<ul>`?"}'::jsonb, 'dom-events', '{"mode":"single","code":"<ul id=\"list\">\n  <li><button><span>Delete</span></button></li>\n</ul>","codeLanguage":"html","options":[{"id":"a","text":{"en":"The `<span>`","uk":"`<span>`"}},{"id":"b","text":{"en":"The `<button>`","uk":"`<button>`"}},{"id":"c","text":{"en":"The `<ul>`","uk":"`<ul>`"}},{"id":"d","text":{"en":"`window`","uk":"`window`"}}]}'::jsonb, null::jsonb),
  ('dom-prevent-vs-stop', 'quiz', 2, 90, '{"en":"preventDefault vs stopPropagation","uk":"preventDefault проти stopPropagation"}'::jsonb, '{"en":"A form''s submit handler calls `event.stopPropagation()` but the page still reloads. Why?","uk":"Обробник submit форми викликає `event.stopPropagation()`, але сторінка все одно перезавантажується. Чому?"}'::jsonb, 'dom-events', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"`stopPropagation` stops bubbling; it doesn''t cancel the default submit. Call `preventDefault()`","uk":"`stopPropagation` зупиняє спливання, але не скасовує типове надсилання. Викличте `preventDefault()`"}},{"id":"b","text":{"en":"Submit events can''t be stopped","uk":"Події submit неможливо зупинити"}},{"id":"c","text":{"en":"`stopPropagation` only works in the capture phase","uk":"`stopPropagation` працює лише у фазі занурення"}},{"id":"d","text":{"en":"The form needs `novalidate`","uk":"Формі потрібен `novalidate`"}}]}'::jsonb, null::jsonb),
  ('dom-delegation-benefits', 'quiz', 2, 90, '{"en":"Why delegate?","uk":"Навіщо делегувати?"}'::jsonb, '{"en":"What are the benefits of one delegated listener on a list instead of one listener per item? Select all that apply.","uk":"Які переваги одного делегованого обробника на списку замість обробника на кожен елемент? Оберіть усі правильні."}'::jsonb, 'dom-events', '{"mode":"multi","codeLanguage":"ts","options":[{"id":"a","text":{"en":"Items added later are handled automatically","uk":"Елементи, додані пізніше, обробляються автоматично"}},{"id":"b","text":{"en":"Fewer listeners and less memory for long lists","uk":"Менше обробників і менше пам''яті для довгих списків"}},{"id":"c","text":{"en":"It works for events that don''t bubble, like `focus`","uk":"Працює для подій, що не спливають, як-от `focus`"}},{"id":"d","text":{"en":"It prevents XSS","uk":"Запобігає XSS"}}]}'::jsonb, null::jsonb),
  ('dom-textcontent-xss', 'quiz', 3, 120, '{"en":"Rendering user input","uk":"Відображення введення користувача"}'::jsonb, '{"en":"A comment is rendered with `el.innerHTML = comment`. A user posts `<img src=x onerror=\"stealCookies()\">`. What happens, and what''s the fix?","uk":"Коментар рендериться через `el.innerHTML = comment`. Користувач публікує `<img src=x onerror=\"stealCookies()\">`. Що станеться і як це виправити?"}'::jsonb, 'dom-events', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"The script runs for everyone viewing it (XSS); use `textContent` or sanitise HTML","uk":"Скрипт виконається в усіх, хто це переглядає (XSS); використайте `textContent` або санітизуйте HTML"}},{"id":"b","text":{"en":"Nothing, browsers block inline handlers in `innerHTML`","uk":"Нічого, браузери блокують вбудовані обробники в `innerHTML`"}},{"id":"c","text":{"en":"The image just fails to load","uk":"Зображення просто не завантажиться"}},{"id":"d","text":{"en":"It throws a SyntaxError","uk":"Кидається SyntaxError"}}]}'::jsonb, null::jsonb),
  ('dom-layout-thrashing', 'quiz', 4, 150, '{"en":"Layout thrashing","uk":"Layout thrashing"}'::jsonb, '{"en":"Why is this loop slow for 1,000 items, and how do you fix it?","uk":"Чому цей цикл повільний для 1000 елементів і як це виправити?"}'::jsonb, 'dom-events', '{"mode":"single","code":"for (const el of document.querySelectorAll(\".bar\")) {\n  el.style.width = `${el.parentElement.offsetWidth / 2}px`;\n}","codeLanguage":"js","options":[{"id":"a","text":{"en":"Each read of `offsetWidth` after a write forces a synchronous reflow; read all widths first, then write","uk":"Кожне читання `offsetWidth` після запису змушує синхронно перераховувати розкладку; спершу прочитайте всі ширини, потім записуйте"}},{"id":"b","text":{"en":"`style.width` is a slow setter; use `setAttribute` instead","uk":"`style.width` є повільним сеттером; використайте `setAttribute`"}},{"id":"c","text":{"en":"`querySelectorAll` returns a live list that re-queries each time","uk":"`querySelectorAll` повертає живий список, що щоразу шукає заново"}},{"id":"d","text":{"en":"Template literals are slow; use string concatenation","uk":"Шаблонні рядки повільні; використайте конкатенацію"}}]}'::jsonb, null::jsonb),
  ('dom-event-delegation', 'practice', 3, 900, '{"en":"Event delegation helper","uk":"Допоміжна функція делегування"}'::jsonb, '{"en":"Implement `delegate(root, selector, type, handler)`:\n\n- Adds **one** listener of `type` to `root`.\n- When the event starts inside an element matching `selector` that is **inside `root`**, call `handler(event, matchedElement)`. Clicks on children of the match (icons, spans) count.\n- Ignore events outside a match.\n- Return a function that removes the listener.\n\nThe demo to-do list uses it for its delete buttons, including items added later.","uk":"Реалізуйте `delegate(root, selector, type, handler)`:\n\n- Додає **один** обробник типу `type` на `root`.\n- Коли подія починається всередині елемента, що відповідає `selector` і знаходиться **всередині `root`**, викликайте `handler(event, matchedElement)`. Кліки по дочірніх елементах збігу (іконках, span) теж рахуються.\n- Ігноруйте події поза збігом.\n- Поверніть функцію, що знімає обробник.\n\nДемо-список справ використовує її для кнопок видалення, включно з елементами, доданими пізніше."}'::jsonb, 'dom-events', null::jsonb, '{"framework":"vanilla-js","files":{"/src/delegate.js":"/**\n * @param {Element} root\n * @param {string} selector\n * @param {string} type\n * @param {(event: Event, match: Element) => void} handler\n * @returns {() => void} unsubscribe\n */\nexport function delegate(root, selector, type, handler) {\n  // TODO\n  return () => {};\n}\n","/index.js":"import \"./styles.css\";\nimport { delegate } from \"./src/delegate\";\n\nconst app = document.getElementById(\"app\");\napp.innerHTML = `\n  <h1>To-do</h1>\n  <ul id=\"todos\"></ul>\n  <button id=\"add\" type=\"button\">Add task</button>`;\nconst list = document.getElementById(\"todos\");\nlet n = 0;\nfunction add() {\n  n++;\n  const li = document.createElement(\"li\");\n  li.innerHTML = `<span>Task ${n}</span> <button class=\"delete\" type=\"button\" aria-label=\"Delete task ${n}\"><b>×</b></button>`;\n  list.append(li);\n}\nadd();\nadd();\ndocument.getElementById(\"add\").addEventListener(\"click\", add);\ndelegate(list, \"button.delete\", \"click\", (_event, button) => button.closest(\"li\").remove());\n"},"visibleFiles":["/src/delegate.js","/index.js"],"activeFile":"/src/delegate.js","tests":"import { describe, it, expect, fn, screen, user } from \"./test-kit\";\nimport { delegate } from \"../src/delegate\";\n\nfunction fixture() {\n  const root = document.createElement(\"div\");\n  root.innerHTML = `<button class=\"act\"><span class=\"icon\">i</span> Act</button><p class=\"other\">x</p>`;\n  document.body.append(root);\n  return root;\n}\n\ndescribe(\"delegate\", () => {\n  it(\"calls the handler with the matched element\", () => {\n    const root = fixture();\n    const handler = fn();\n    delegate(root, \".act\", \"click\", handler);\n    root.querySelector(\".act\").click();\n    expect(handler).toHaveBeenCalledTimes(1);\n    expect(handler.mock.calls[0][1]).toBe(root.querySelector(\".act\"));\n    root.remove();\n  });\n  it(\"matches clicks on children of the matched element\", () => {\n    const root = fixture();\n    const handler = fn();\n    delegate(root, \".act\", \"click\", handler);\n    root.querySelector(\".icon\").click();\n    expect(handler).toHaveBeenCalledTimes(1);\n    expect(handler.mock.calls[0][1]).toBe(root.querySelector(\".act\"));\n    root.remove();\n  });\n  it(\"ignores events outside a match\", () => {\n    const root = fixture();\n    const handler = fn();\n    delegate(root, \".act\", \"click\", handler);\n    root.querySelector(\".other\").click();\n    expect(handler).toHaveBeenCalledTimes(0);\n    root.remove();\n  });\n  it(\"ignores matches outside the root\", () => {\n    const outer = document.createElement(\"div\");\n    outer.className = \"act\";\n    const root = document.createElement(\"div\");\n    root.innerHTML = \"<span>inside</span>\";\n    outer.append(root);\n    document.body.append(outer);\n    const handler = fn();\n    delegate(root, \".act\", \"click\", handler);\n    root.querySelector(\"span\").click();\n    expect(handler).toHaveBeenCalledTimes(0);\n    outer.remove();\n  });\n  it(\"returns an unsubscribe function\", () => {\n    const root = fixture();\n    const handler = fn();\n    const off = delegate(root, \".act\", \"click\", handler);\n    off();\n    root.querySelector(\".act\").click();\n    expect(handler).toHaveBeenCalledTimes(0);\n    root.remove();\n  });\n  it(\"works for items added later in the demo\", async () => {\n    await user.click(screen.getByRole(\"button\", { name: \"Add task\" }));\n    expect(screen.getAllByRole(\"listitem\")).toHaveLength(3);\n    await user.click(screen.getByRole(\"button\", { name: \"Delete task 3\" }).querySelector(\"b\"));\n    expect(screen.getAllByRole(\"listitem\")).toHaveLength(2);\n  });\n});\n","testCount":6}'::jsonb),
  ('esm-live-binding', 'quiz', 2, 90, '{"en":"Live bindings","uk":"Живі прив''язки"}'::jsonb, '{"en":"What does `main.js` log?","uk":"Що виведе `main.js`?"}'::jsonb, 'es-modules', '{"mode":"single","code":"// counter.js\nexport let count = 0;\nexport function inc() { count++; }\n\n// main.js\nimport { count, inc } from \"./counter.js\";\ninc();\nconsole.log(count);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`0`","uk":"`0`"}},{"id":"b","text":{"en":"`1`","uk":"`1`"}},{"id":"c","text":{"en":"`undefined`","uk":"`undefined`"}},{"id":"d","text":{"en":"It throws","uk":"Кидає помилку"}}]}'::jsonb, null::jsonb),
  ('esm-tree-shaking', 'quiz', 2, 90, '{"en":"Why tree-shaking needs ESM","uk":"Чому tree-shaking потребує ESM"}'::jsonb, '{"en":"Why can bundlers tree-shake ES modules more reliably than CommonJS?","uk":"Чому збирачі надійніше прибирають невикористаний код з ES-модулів, ніж із CommonJS?"}'::jsonb, 'es-modules', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"Imports and exports are static, so usage is known without running code","uk":"Імпорти й експорти статичні, тож використання відоме без запуску коду"}},{"id":"b","text":{"en":"ES modules are always smaller","uk":"ES-модулі завжди менші"}},{"id":"c","text":{"en":"CommonJS can''t export functions","uk":"CommonJS не може експортувати функції"}},{"id":"d","text":{"en":"Browsers remove unused exports at runtime","uk":"Браузери прибирають невикористані експорти під час виконання"}}]}'::jsonb, null::jsonb),
  ('esm-evaluate-once', 'quiz', 3, 90, '{"en":"Module evaluation","uk":"Виконання модуля"}'::jsonb, '{"en":"`config.js` logs \"loading config\" at the top level. Three different modules import it. How many times is it logged?","uk":"`config.js` на верхньому рівні виводить \"loading config\". Три різні модулі його імпортують. Скільки разів це буде виведено?"}'::jsonb, 'es-modules', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"Once","uk":"Один раз"}},{"id":"b","text":{"en":"Three times","uk":"Тричі"}},{"id":"c","text":{"en":"Zero times until a function is called","uk":"Жодного разу, доки не викликано функцію"}},{"id":"d","text":{"en":"It depends on import order","uk":"Залежить від порядку імпортів"}}]}'::jsonb, null::jsonb),
  ('esm-dynamic-import', 'quiz', 3, 120, '{"en":"Dynamic import","uk":"Динамічний імпорт"}'::jsonb, '{"en":"What does `import(\"./editor.js\")` return, and why use it?","uk":"Що повертає `import(\"./editor.js\")` і навіщо його використовувати?"}'::jsonb, 'es-modules', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"A promise of the module namespace; it enables loading code on demand (code splitting)","uk":"Проміс простору імен модуля; дозволяє завантажувати код на вимогу (розділення коду)"}},{"id":"b","text":{"en":"The default export synchronously","uk":"Типовий експорт, синхронно"}},{"id":"c","text":{"en":"A CommonJS `module.exports` object","uk":"Об''єкт `module.exports` у стилі CommonJS"}},{"id":"d","text":{"en":"Nothing; it''s only valid in Node.js","uk":"Нічого; він працює лише в Node.js"}}]}'::jsonb, null::jsonb),
  ('esm-circular', 'quiz', 4, 150, '{"en":"Circular imports","uk":"Циклічні імпорти"}'::jsonb, '{"en":"`a.js` imports `b.js`, and `b.js` imports `a.js`. `b.js` reads a `const` from `a.js` at its top level. What typically happens when you load `a.js` first?","uk":"`a.js` імпортує `b.js`, а `b.js` імпортує `a.js`. `b.js` на верхньому рівні читає `const` з `a.js`. Що зазвичай станеться, якщо першим завантажити `a.js`?"}'::jsonb, 'es-modules', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"Everything works because modules are cached","uk":"Усе працює, бо модулі кешуються"}},{"id":"b","text":{"en":"`b.js` runs first and hits a ReferenceError (TDZ), because `a.js` hasn''t initialised its `const` yet","uk":"`b.js` виконується першим і отримує ReferenceError (TDZ), бо `a.js` ще не ініціалізував свій `const`"}},{"id":"c","text":{"en":"The bundler duplicates both modules","uk":"Збирач дублює обидва модулі"}},{"id":"d","text":{"en":"Node.js refuses to start","uk":"Node.js відмовляється запускатися"}}]}'::jsonb, null::jsonb),
  ('git-staging', 'quiz', 1, 60, '{"en":"Staging area","uk":"Індекс (staging)"}'::jsonb, '{"en":"You edited three files but want only one of them in the next commit. What do you do?","uk":"Ви змінили три файли, але в наступний коміт хочете лише один. Що робити?"}'::jsonb, 'git', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"`git add that-file` then `git commit`","uk":"`git add that-file`, потім `git commit`"}},{"id":"b","text":{"en":"`git commit -a`","uk":"`git commit -a`"}},{"id":"c","text":{"en":"`git push that-file`","uk":"`git push that-file`"}},{"id":"d","text":{"en":"`git stash` all three, then commit","uk":"Зробити `git stash` для всіх трьох, потім коміт"}}]}'::jsonb, null::jsonb),
  ('git-revert-vs-reset', 'quiz', 2, 90, '{"en":"Undoing a pushed commit","uk":"Скасування відправленого коміту"}'::jsonb, '{"en":"A bad commit is already on the shared `main` branch. What''s the safe way to undo it?","uk":"Поганий коміт уже в спільній гілці `main`. Як безпечно його скасувати?"}'::jsonb, 'git', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"`git revert <sha>` and push","uk":"`git revert <sha>` і push"}},{"id":"b","text":{"en":"`git reset --hard HEAD~1` and force-push","uk":"`git reset --hard HEAD~1` і force-push"}},{"id":"c","text":{"en":"Delete the branch and recreate it","uk":"Видалити гілку й створити заново"}},{"id":"d","text":{"en":"`git commit --amend`","uk":"`git commit --amend`"}}]}'::jsonb, null::jsonb),
  ('git-rebase-golden-rule', 'quiz', 3, 120, '{"en":"The golden rule of rebasing","uk":"Золоте правило rebase"}'::jsonb, '{"en":"Why shouldn''t you rebase a branch that teammates are also working on?","uk":"Чому не варто робити rebase гілки, з якою працюють і колеги?"}'::jsonb, 'git', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"Rebase rewrites commits with new hashes, so others'' copies diverge and they get duplicate or conflicting history","uk":"Rebase переписує коміти з новими хешами, тож копії інших розходяться, і в них з''являється дубльована чи конфліктна історія"}},{"id":"b","text":{"en":"Rebase deletes the branch on the remote","uk":"Rebase видаляє гілку на віддаленому сервері"}},{"id":"c","text":{"en":"Rebase only works on local branches","uk":"Rebase працює лише з локальними гілками"}},{"id":"d","text":{"en":"Rebase loses the file contents","uk":"Rebase втрачає вміст файлів"}}]}'::jsonb, null::jsonb),
  ('git-reflog', 'quiz', 3, 120, '{"en":"Recovering lost commits","uk":"Відновлення втрачених комітів"}'::jsonb, '{"en":"You ran `git reset --hard HEAD~3` by mistake. How can you get the commits back?","uk":"Ви помилково виконали `git reset --hard HEAD~3`. Як повернути коміти?"}'::jsonb, 'git', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"Find the previous HEAD in `git reflog` and `git reset --hard <sha>` (or create a branch there)","uk":"Знайти попередній HEAD у `git reflog` і виконати `git reset --hard <sha>` (або створити там гілку)"}},{"id":"b","text":{"en":"They''re gone forever","uk":"Вони втрачені назавжди"}},{"id":"c","text":{"en":"`git revert HEAD~3`","uk":"`git revert HEAD~3`"}},{"id":"d","text":{"en":"`git stash pop`","uk":"`git stash pop`"}}]}'::jsonb, null::jsonb),
  ('git-bisect', 'quiz', 4, 120, '{"en":"Finding the bad commit","uk":"Пошук поганого коміту"}'::jsonb, '{"en":"A bug appeared somewhere in the last 1,000 commits. About how many builds does `git bisect` need to find the culprit?","uk":"Помилка з''явилася десь в останніх 1000 комітах. Приблизно скільки збірок потрібно `git bisect`, щоб знайти винуватця?"}'::jsonb, 'git', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"About 10","uk":"Близько 10"}},{"id":"b","text":{"en":"About 100","uk":"Близько 100"}},{"id":"c","text":{"en":"About 500","uk":"Близько 500"}},{"id":"d","text":{"en":"All 1,000","uk":"Усі 1000"}}]}'::jsonb, null::jsonb),
  ('html-button-vs-div', 'quiz', 1, 60, '{"en":"Clickable div","uk":"Клікабельний div"}'::jsonb, '{"en":"Why is `<button>` better than `<div onclick>` for an action?","uk":"Чому `<button>` кращий за `<div onclick>` для дії?"}'::jsonb, 'html', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"It''s focusable, has a button role and activates with Enter and Space out of the box","uk":"Він отримує фокус, має роль кнопки й активується Enter і Space без додаткового коду"}},{"id":"b","text":{"en":"Divs can''t have click handlers in modern browsers","uk":"У сучасних браузерах div не може мати обробників кліку"}},{"id":"c","text":{"en":"Buttons render faster","uk":"Кнопки рендеряться швидше"}},{"id":"d","text":{"en":"There is no practical difference","uk":"Практичної різниці немає"}}]}'::jsonb, null::jsonb),
  ('html-defer-async', 'quiz', 2, 90, '{"en":"defer vs async","uk":"defer проти async"}'::jsonb, '{"en":"You have two scripts where `app.js` depends on `vendor.js`. Which attributes guarantee they don''t block parsing **and** run in order?","uk":"Є два скрипти, і `app.js` залежить від `vendor.js`. Які атрибути гарантують, що вони не блокують розбір **і** виконуються по порядку?"}'::jsonb, 'html', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"`async` on both","uk":"`async` на обох"}},{"id":"b","text":{"en":"`defer` on both","uk":"`defer` на обох"}},{"id":"c","text":{"en":"No attributes, placed in `<head>`","uk":"Без атрибутів, у `<head>`"}},{"id":"d","text":{"en":"`async` on vendor.js, `defer` on app.js","uk":"`async` на vendor.js, `defer` на app.js"}}]}'::jsonb, null::jsonb),
  ('html-button-default-type', 'quiz', 2, 90, '{"en":"Unexpected submit","uk":"Неочікуване надсилання"}'::jsonb, '{"en":"Clicking \"Show password\" reloads the page. Why?","uk":"Клік на «Show password» перезавантажує сторінку. Чому?"}'::jsonb, 'html', '{"mode":"single","code":"<form>\n  <input type=\"password\" id=\"pw\" />\n  <button onclick=\"toggle()\">Show password</button>\n  <button>Log in</button>\n</form>","codeLanguage":"html","options":[{"id":"a","text":{"en":"A `<button>` inside a `<form>` defaults to `type=\"submit\"`","uk":"`<button>` усередині `<form>` за замовчуванням має `type=\"submit\"`"}},{"id":"b","text":{"en":"`onclick` handlers always reload the page","uk":"Обробники `onclick` завжди перезавантажують сторінку"}},{"id":"c","text":{"en":"Password inputs submit forms when focused","uk":"Поля паролів надсилають форму під час фокусу"}},{"id":"d","text":{"en":"The form is missing an `action` attribute","uk":"У формі немає атрибута `action`"}}]}'::jsonb, null::jsonb),
  ('html-label-association', 'quiz', 2, 90, '{"en":"Labelling inputs","uk":"Мітки для полів"}'::jsonb, '{"en":"Which of these give the input an accessible name? Select all that apply.","uk":"Які з цих варіантів дають полю доступне ім''я? Оберіть усі правильні."}'::jsonb, 'html', '{"mode":"multi","codeLanguage":"ts","options":[{"id":"a","text":{"en":"`<label for=\"q\">Search</label><input id=\"q\">`","uk":"`<label for=\"q\">Search</label><input id=\"q\">`"}},{"id":"b","text":{"en":"`<label>Search <input></label>`","uk":"`<label>Search <input></label>`"}},{"id":"c","text":{"en":"`<input placeholder=\"Search\">` only","uk":"лише `<input placeholder=\"Search\">`"}},{"id":"d","text":{"en":"`<input aria-label=\"Search\">`","uk":"`<input aria-label=\"Search\">`"}}]}'::jsonb, null::jsonb),
  ('html-heading-order', 'quiz', 3, 120, '{"en":"Heading structure","uk":"Структура заголовків"}'::jsonb, '{"en":"A designer wants a small-looking heading right after the page `<h1>`. What should you use?","uk":"Дизайнер хоче дрібний на вигляд заголовок одразу після `<h1>` сторінки. Що використати?"}'::jsonb, 'html', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"`<h4>`, because it''s smaller by default","uk":"`<h4>`, бо він за замовчуванням менший"}},{"id":"b","text":{"en":"`<h2>` styled with CSS to look small","uk":"`<h2>`, стилізований CSS під дрібний вигляд"}},{"id":"c","text":{"en":"A `<div class=\"h4\">`","uk":"`<div class=\"h4\">`"}},{"id":"d","text":{"en":"`<strong>` inside a paragraph","uk":"`<strong>` усередині абзацу"}}]}'::jsonb, null::jsonb),
  ('html-semantic-signup-form', 'practice', 2, 900, '{"en":"Semantic sign-up form","uk":"Семантична форма реєстрації"}'::jsonb, '{"en":"Rewrite `index.html` so the sign-up page is semantic and accessible. Keep the `<script>` tag.\n\n- A `<main>` landmark with an `<h1>` \"Create your account\".\n- A real `<form>` with:\n  - an **Email** field: labelled, `type=\"email\"`, `autocomplete=\"email\"`, required;\n  - a **Password** field: labelled, `type=\"password\"`, `minlength=\"8\"`, required;\n  - a required checkbox labelled **I accept the terms**;\n  - a submit `<button>` \"Create account\".\n- No placeholder-only labels, no clickable divs.","uk":"Перепишіть `index.html`, щоб сторінка реєстрації була семантичною й доступною. Залиште тег `<script>`.\n\n- Орієнтир `<main>` із `<h1>` «Create your account».\n- Справжня `<form>` з:\n  - полем **Email**: з міткою, `type=\"email\"`, `autocomplete=\"email\"`, обов''язкове;\n  - полем **Password**: з міткою, `type=\"password\"`, `minlength=\"8\"`, обов''язкове;\n  - обов''язковим чекбоксом з міткою **I accept the terms**;\n  - кнопкою надсилання `<button>` «Create account».\n- Жодних міток лише через placeholder і жодних клікабельних div."}'::jsonb, 'html', null::jsonb, '{"framework":"vanilla-js","files":{"/index.html":"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <title>Sign up</title>\n</head>\n<body>\n  <div class=\"page\">\n    <div class=\"title\">Create your account</div>\n    <div class=\"form\">\n      <input placeholder=\"Email\" />\n      <input placeholder=\"Password\" />\n      <div><input /> I accept the terms</div>\n      <div class=\"btn\" onclick=\"alert(''sent'')\">Create account</div>\n    </div>\n  </div>\n\n  <script src=\"index.js\"></script>\n</body>\n</html>\n","/index.js":"import \"./styles.css\";\n\n// Prevent real navigation in the preview.\ndocument.addEventListener(\"submit\", (e) => e.preventDefault());\n"},"visibleFiles":["/index.html"],"activeFile":"/index.html","tests":"import { describe, it, expect, screen } from \"./test-kit\";\n\ndescribe(\"sign-up page\", () => {\n  it(\"has a main landmark and an h1\", () => {\n    expect(document.querySelector(\"main\")).toBeTruthy();\n    expect(screen.getByRole(\"heading\", { level: 1 })).toHaveTextContent(\"Create your account\");\n  });\n  it(\"uses a real form\", () => {\n    const email = screen.getByLabelText(\"Email\");\n    expect(email.closest(\"form\")).toBeTruthy();\n  });\n  it(\"has a labelled, required email field\", () => {\n    const email = screen.getByLabelText(\"Email\");\n    expect(email).toHaveAttribute(\"type\", \"email\");\n    expect(email).toHaveAttribute(\"autocomplete\", \"email\");\n    expect(email).toHaveAttribute(\"required\");\n  });\n  it(\"has a labelled password field with a minimum length\", () => {\n    const pw = screen.getByLabelText(\"Password\");\n    expect(pw).toHaveAttribute(\"type\", \"password\");\n    expect(pw).toHaveAttribute(\"minlength\", \"8\");\n    expect(pw).toHaveAttribute(\"required\");\n  });\n  it(\"has a required, labelled terms checkbox\", () => {\n    const box = screen.getByRole(\"checkbox\", { name: /accept the terms/i });\n    expect(box).toHaveAttribute(\"required\");\n  });\n  it(\"submits with a real button\", () => {\n    const button = screen.getByRole(\"button\", { name: \"Create account\" });\n    expect(button.tagName).toBe(\"BUTTON\");\n    expect(button.getAttribute(\"type\") ?? \"submit\").toBe(\"submit\");\n    expect(document.querySelector(\"[onclick]\")).toBeNull();\n  });\n});\n","testCount":6}'::jsonb),
  ('http-401-vs-403', 'quiz', 1, 60, '{"en":"401 or 403","uk":"401 чи 403"}'::jsonb, '{"en":"A signed-in user tries to delete another user''s post. Which status code fits?","uk":"Автентифікований користувач намагається видалити чужий допис. Який код стану підходить?"}'::jsonb, 'http-rest', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"401 Unauthorized","uk":"401 Unauthorized"}},{"id":"b","text":{"en":"403 Forbidden","uk":"403 Forbidden"}},{"id":"c","text":{"en":"404 Not Found","uk":"404 Not Found"}},{"id":"d","text":{"en":"400 Bad Request","uk":"400 Bad Request"}}]}'::jsonb, null::jsonb),
