  ('http-cors-preflight', 'quiz', 3, 120, '{"en":"CORS preflight","uk":"CORS preflight"}'::jsonb, '{"en":"Your app on `https://app.com` sends `PUT https://api.com/items/1` with `Content-Type: application/json`. What does the browser do first?","uk":"Ваш застосунок на `https://app.com` надсилає `PUT https://api.com/items/1` з `Content-Type: application/json`. Що браузер робить спершу?"}'::jsonb, 'http-rest', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"Sends an `OPTIONS` preflight and only sends the PUT if the response allows the method, headers and origin","uk":"Надсилає preflight `OPTIONS` і надсилає PUT лише якщо відповідь дозволяє метод, заголовки й джерело"}},{"id":"b","text":{"en":"Sends the PUT and hides the response if CORS headers are missing","uk":"Надсилає PUT і приховує відповідь, якщо немає заголовків CORS"}},{"id":"c","text":{"en":"Blocks the request: cross-origin PUT is never allowed","uk":"Блокує запит: PUT між різними джерелами ніколи не дозволено"}},{"id":"d","text":{"en":"Converts it to a POST","uk":"Перетворює його на POST"}}]}'::jsonb, null::jsonb),
  ('http-cache-control', 'quiz', 3, 120, '{"en":"Caching fingerprinted assets","uk":"Кешування ресурсів із відбитком"}'::jsonb, '{"en":"Your build outputs `app.3f9a1c.js` (a content hash in the name). Which header is best?","uk":"Збірка створює `app.3f9a1c.js` (хеш вмісту в назві). Який заголовок найкращий?"}'::jsonb, 'http-rest', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"`Cache-Control: no-store`","uk":"`Cache-Control: no-store`"}},{"id":"b","text":{"en":"`Cache-Control: public, max-age=31536000, immutable`","uk":"`Cache-Control: public, max-age=31536000, immutable`"}},{"id":"c","text":{"en":"`Cache-Control: no-cache`","uk":"`Cache-Control: no-cache`"}},{"id":"d","text":{"en":"`Expires: 0`","uk":"`Expires: 0`"}}]}'::jsonb, null::jsonb),
  ('http-rest-create', 'quiz', 2, 90, '{"en":"Creating a resource","uk":"Створення ресурсу"}'::jsonb, '{"en":"What is the most RESTful response to `POST /orders` that successfully creates order 42?","uk":"Яка відповідь на `POST /orders`, що успішно створив замовлення 42, найбільше відповідає REST?"}'::jsonb, 'http-rest', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"`200 OK` with `{ \"success\": true }`","uk":"`200 OK` з `{ \"success\": true }`"}},{"id":"b","text":{"en":"`201 Created` with `Location: /orders/42` and the order in the body","uk":"`201 Created` з `Location: /orders/42` і замовленням у тілі"}},{"id":"c","text":{"en":"`204 No Content`","uk":"`204 No Content`"}},{"id":"d","text":{"en":"`302 Found` redirecting to `/orders/42`","uk":"`302 Found` з переспрямуванням на `/orders/42`"}}]}'::jsonb, null::jsonb),
  ('js-typeof-null', 'quiz', 1, 45, '{"en":"typeof null","uk":"typeof null"}'::jsonb, '{"en":"What does `typeof null` return?","uk":"Що повертає `typeof null`?"}'::jsonb, 'javascript', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"`\"null\"`","uk":"`\"null\"`"}},{"id":"b","text":{"en":"`\"object\"`","uk":"`\"object\"`"}},{"id":"c","text":{"en":"`\"undefined\"`","uk":"`\"undefined\"`"}},{"id":"d","text":{"en":"It throws a TypeError","uk":"Кидає TypeError"}}]}'::jsonb, null::jsonb),
  ('js-reference-equality', 'quiz', 1, 60, '{"en":"Comparing objects","uk":"Порівняння об''єктів"}'::jsonb, '{"en":"What does this code log?","uk":"Що виведе цей код?"}'::jsonb, 'javascript', '{"mode":"single","code":"const a = { id: 1 };\nconst b = { id: 1 };\nconst c = a;\nconsole.log(a === b, a === c);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`true true`","uk":"`true true`"}},{"id":"b","text":{"en":"`false true`","uk":"`false true`"}},{"id":"c","text":{"en":"`false false`","uk":"`false false`"}},{"id":"d","text":{"en":"`true false`","uk":"`true false`"}}]}'::jsonb, null::jsonb),
  ('js-falsy-values', 'quiz', 2, 90, '{"en":"Falsy values","uk":"Хибні значення"}'::jsonb, '{"en":"Which of these values are **falsy**? Select all that apply.","uk":"Які з цих значень є **хибними (falsy)**? Оберіть усі правильні."}'::jsonb, 'javascript', '{"mode":"multi","codeLanguage":"ts","options":[{"id":"a","text":{"en":"`0`","uk":"`0`"}},{"id":"b","text":{"en":"`\"0\"`","uk":"`\"0\"`"}},{"id":"c","text":{"en":"`[]`","uk":"`[]`"}},{"id":"d","text":{"en":"`NaN`","uk":"`NaN`"}},{"id":"e","text":{"en":"`\"\"`","uk":"`\"\"`"}}]}'::jsonb, null::jsonb),
  ('js-this-callback', 'quiz', 3, 120, '{"en":"Lost `this`","uk":"Втрачений `this`"}'::jsonb, '{"en":"What happens when `setTimeout` calls `counter.inc` after 0 ms in strict mode?","uk":"Що станеться, коли `setTimeout` викличе `counter.inc` через 0 мс у strict mode?"}'::jsonb, 'javascript', '{"mode":"single","code":"\"use strict\";\nconst counter = {\n  count: 0,\n  inc() { this.count++; },\n};\nsetTimeout(counter.inc, 0);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`count` becomes 1","uk":"`count` стане 1"}},{"id":"b","text":{"en":"A TypeError is thrown because `this` is `undefined`","uk":"Буде TypeError, бо `this` дорівнює `undefined`"}},{"id":"c","text":{"en":"`count` becomes `NaN`","uk":"`count` стане `NaN`"}},{"id":"d","text":{"en":"Nothing, `setTimeout` ignores methods","uk":"Нічого, `setTimeout` ігнорує методи"}}]}'::jsonb, null::jsonb),
  ('js-prototype-lookup', 'quiz', 4, 150, '{"en":"Prototype chain","uk":"Ланцюжок прототипів"}'::jsonb, '{"en":"What does the last line log?","uk":"Що виведе останній рядок?"}'::jsonb, 'javascript', '{"mode":"single","code":"const base = { kind: \"base\" };\nconst child = Object.create(base);\nchild.kind = \"own\";\ndelete child.kind;\nconsole.log(child.kind);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`\"base\"`","uk":"`\"base\"`"}},{"id":"b","text":{"en":"`\"own\"`","uk":"`\"own\"`"}},{"id":"c","text":{"en":"`undefined`","uk":"`undefined`"}},{"id":"d","text":{"en":"It throws","uk":"Кидає помилку"}}]}'::jsonb, null::jsonb),
  ('js-group-by', 'practice', 2, 600, '{"en":"Implement groupBy","uk":"Реалізуйте groupBy"}'::jsonb, '{"en":"Implement `groupBy(items, keyFn)`. It returns a plain object whose keys are the results of `keyFn(item)` and whose values are arrays of items with that key, **in their original order**. Don''t mutate `items`.\n\n```js\ngroupBy([1.2, 1.7, 2.3], Math.floor) // { 1: [1.2, 1.7], 2: [2.3] }\n```","uk":"Реалізуйте `groupBy(items, keyFn)`. Функція повертає звичайний об''єкт, ключі якого є результатами `keyFn(item)`, а значення є масивами елементів із цим ключем **у початковому порядку**. Не змінюйте `items`.\n\n```js\ngroupBy([1.2, 1.7, 2.3], Math.floor) // { 1: [1.2, 1.7], 2: [2.3] }\n```"}'::jsonb, 'javascript', null::jsonb, '{"framework":"vanilla-js","files":{"/src/groupBy.js":"/**\n * @template T\n * @param {T[]} items\n * @param {(item: T) => string | number} keyFn\n * @returns {Record<string, T[]>}\n */\nexport function groupBy(items, keyFn) {\n  // TODO\n  return {};\n}\n","/index.js":"import \"./styles.css\";\nimport { groupBy } from \"./src/groupBy\";\n\nconst people = [\n  { name: \"Ada\", team: \"core\" },\n  { name: \"Linus\", team: \"infra\" },\n  { name: \"Grace\", team: \"core\" },\n];\nconst groups = groupBy(people, (p) => p.team);\n\ndocument.getElementById(\"app\").innerHTML =\n  \"<h1>Teams</h1>\" +\n  Object.entries(groups)\n    .map(([team, list]) => `<h2>${team}</h2><ul>${list.map((p) => `<li>${p.name}</li>`).join(\"\")}</ul>`)\n    .join(\"\");\n"},"visibleFiles":["/src/groupBy.js","/index.js"],"activeFile":"/src/groupBy.js","tests":"import { describe, it, expect, screen } from \"./test-kit\";\nimport { groupBy } from \"../src/groupBy\";\n\ndescribe(\"groupBy\", () => {\n  it(\"groups by the key function\", () => {\n    expect(groupBy([1.2, 1.7, 2.3], Math.floor)).toEqual({ 1: [1.2, 1.7], 2: [2.3] });\n  });\n  it(\"keeps the original order inside groups\", () => {\n    const words = [\"apple\", \"bob\", \"avocado\", \"banana\"];\n    expect(groupBy(words, (w) => w[0])).toEqual({ a: [\"apple\", \"avocado\"], b: [\"bob\", \"banana\"] });\n  });\n  it(\"returns an empty object for an empty array\", () => expect(groupBy([], (x) => x)).toEqual({}));\n  it(\"does not mutate the input\", () => {\n    const input = [3, 1, 2];\n    groupBy(input, (n) => n % 2);\n    expect(input).toEqual([3, 1, 2]);\n  });\n  it(\"renders the teams demo\", async () => {\n    await screen.findByRole(\"heading\", { name: \"core\" });\n    expect(screen.getAllByRole(\"listitem\")).toHaveLength(3);\n  });\n});\n","testCount":5}'::jsonb),
  ('node-blocking', 'quiz', 1, 60, '{"en":"Blocking the event loop","uk":"Блокування циклу подій"}'::jsonb, '{"en":"An Express route runs a CPU-heavy loop for 2 seconds. What happens to other incoming requests meanwhile?","uk":"Маршрут Express виконує CPU-важкий цикл 2 секунди. Що в цей час відбувається з іншими вхідними запитами?"}'::jsonb, 'nodejs', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"They wait: the single JavaScript thread is busy","uk":"Вони чекають: єдиний потік JavaScript зайнятий"}},{"id":"b","text":{"en":"Node automatically runs them on other threads","uk":"Node автоматично виконує їх в інших потоках"}},{"id":"c","text":{"en":"They are rejected with 503","uk":"Їх відхиляють з кодом 503"}},{"id":"d","text":{"en":"Nothing, async/await prevents blocking","uk":"Нічого, async/await запобігає блокуванню"}}]}'::jsonb, null::jsonb),
  ('node-microtask-order', 'quiz', 3, 120, '{"en":"nextTick and promises","uk":"nextTick і проміси"}'::jsonb, '{"en":"What do the first two lines printed by this script say?","uk":"Що виведуть перші два рядки цього скрипта?"}'::jsonb, 'nodejs', '{"mode":"single","code":"setTimeout(() => console.log(\"timeout\"), 0);\nsetImmediate(() => console.log(\"immediate\"));\nPromise.resolve().then(() => console.log(\"promise\"));\nprocess.nextTick(() => console.log(\"nextTick\"));","codeLanguage":"js","options":[{"id":"a","text":{"en":"`nextTick` then `promise`","uk":"`nextTick`, потім `promise`"}},{"id":"b","text":{"en":"`promise` then `nextTick`","uk":"`promise`, потім `nextTick`"}},{"id":"c","text":{"en":"`timeout` then `nextTick`","uk":"`timeout`, потім `nextTick`"}},{"id":"d","text":{"en":"The order is random","uk":"Порядок випадковий"}}]}'::jsonb, null::jsonb),
  ('node-streams', 'quiz', 2, 90, '{"en":"Large files","uk":"Великі файли"}'::jsonb, '{"en":"You need to gzip a 5 GB log file on a server with 1 GB of RAM. What''s the right approach?","uk":"Треба стиснути gzip-ом файл журналу на 5 ГБ на сервері з 1 ГБ пам''яті. Який підхід правильний?"}'::jsonb, 'nodejs', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"Stream it: `pipeline(createReadStream, createGzip(), createWriteStream)`","uk":"Обробити потоково: `pipeline(createReadStream, createGzip(), createWriteStream)`"}},{"id":"b","text":{"en":"`fs.readFile` the whole file, then `zlib.gzipSync`","uk":"Прочитати весь файл через `fs.readFile`, потім `zlib.gzipSync`"}},{"id":"c","text":{"en":"Split it into 5 `readFileSync` calls","uk":"Розбити на 5 викликів `readFileSync`"}},{"id":"d","text":{"en":"Increase the Node heap to 6 GB","uk":"Збільшити купу Node до 6 ГБ"}}]}'::jsonb, null::jsonb),
  ('node-unhandled-rejection', 'quiz', 3, 120, '{"en":"Unhandled rejections","uk":"Необроблені відхилення"}'::jsonb, '{"en":"In current Node.js versions, what happens by default when a promise rejects and nobody handles it?","uk":"Що за замовчуванням відбувається в сучасних версіях Node.js, коли проміс відхиляється й ніхто цього не обробляє?"}'::jsonb, 'nodejs', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"The process logs the error and exits with a non-zero code","uk":"Процес записує помилку в журнал і завершується з ненульовим кодом"}},{"id":"b","text":{"en":"Nothing, the rejection is silently ignored","uk":"Нічого, відхилення тихо ігнорується"}},{"id":"c","text":{"en":"The promise is retried automatically","uk":"Проміс автоматично повторюється"}},{"id":"d","text":{"en":"Only a deprecation warning is printed","uk":"Друкується лише попередження про застарілість"}}]}'::jsonb, null::jsonb),
  ('node-scaling-cores', 'quiz', 4, 150, '{"en":"Using all cores","uk":"Використання всіх ядер"}'::jsonb, '{"en":"A Node API runs on an 8-core machine but CPU usage never exceeds ~12%. What''s the standard way to use the whole machine?","uk":"Node API працює на 8-ядерній машині, але завантаження CPU не перевищує ~12%. Який стандартний спосіб використати всю машину?"}'::jsonb, 'nodejs', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"Run several stateless processes (cluster, PM2 or containers) behind a load balancer","uk":"Запустити кілька процесів без стану (cluster, PM2 або контейнери) за балансувальником навантаження"}},{"id":"b","text":{"en":"Set `UV_THREADPOOL_SIZE=8`","uk":"Встановити `UV_THREADPOOL_SIZE=8`"}},{"id":"c","text":{"en":"Use more `async` functions","uk":"Використати більше `async`-функцій"}},{"id":"d","text":{"en":"Switch to `setImmediate` everywhere","uk":"Скрізь перейти на `setImmediate`"}}]}'::jsonb, null::jsonb),
  ('react-state-snapshot', 'quiz', 2, 90, '{"en":"Batched updates","uk":"Групування оновлень"}'::jsonb, '{"en":"`count` is `0`. What is it after one click?","uk":"`count` дорівнює `0`. Яким він стане після одного кліку?"}'::jsonb, 'react', '{"mode":"single","code":"function onClick() {\n  setCount(count + 1);\n  setCount(count + 1);\n  setCount((c) => c + 1);\n}","codeLanguage":"tsx","options":[{"id":"a","text":{"en":"1","uk":"1"}},{"id":"b","text":{"en":"2","uk":"2"}},{"id":"c","text":{"en":"3","uk":"3"}},{"id":"d","text":{"en":"0","uk":"0"}}]}'::jsonb, null::jsonb),
  ('react-keys-index', 'quiz', 2, 90, '{"en":"Keys in lists","uk":"Ключі у списках"}'::jsonb, '{"en":"Why is the array index a poor `key` for a list where items can be inserted at the top?","uk":"Чому індекс масиву — поганий `key` для списку, куди елементи додаються згори?"}'::jsonb, 'react', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"React throws a warning and refuses to render","uk":"React показує попередження й відмовляється рендерити"}},{"id":"b","text":{"en":"Keys shift, so React reuses the wrong components and their state/DOM sticks to other items","uk":"Ключі зсуваються, тож React перевикористовує не ті компоненти, і їхній стан/DOM «прилипає» до інших елементів"}},{"id":"c","text":{"en":"Indexes are numbers and keys must be strings","uk":"Індекси є числами, а ключі мають бути рядками"}},{"id":"d","text":{"en":"It makes the list render twice","uk":"Через це список рендериться двічі"}}]}'::jsonb, null::jsonb),
  ('react-effect-cleanup', 'quiz', 3, 120, '{"en":"Effect cleanup","uk":"Очищення ефекту"}'::jsonb, '{"en":"When does React run the cleanup function returned from this effect? Select all that apply.","uk":"Коли React викликає функцію очищення, яку повертає цей ефект? Оберіть усі правильні."}'::jsonb, 'react', '{"mode":"multi","code":"useEffect(() => {\n  const conn = connect(roomId);\n  return () => conn.disconnect();\n}, [roomId]);","codeLanguage":"tsx","options":[{"id":"a","text":{"en":"Before the effect re-runs because `roomId` changed","uk":"Перед повторним запуском ефекту через зміну `roomId`"}},{"id":"b","text":{"en":"When the component unmounts","uk":"Коли компонент демонтується"}},{"id":"c","text":{"en":"After every render, even if `roomId` didn''t change","uk":"Після кожного рендеру, навіть якщо `roomId` не змінився"}},{"id":"d","text":{"en":"Only when the page is reloaded","uk":"Лише при перезавантаженні сторінки"}}]}'::jsonb, null::jsonb),
  ('react-derived-state', 'quiz', 3, 120, '{"en":"You might not need an effect","uk":"Ефект може бути зайвим"}'::jsonb, '{"en":"What is the best way to show `visible` todos in this component?","uk":"Як найкраще показати `visible` у цьому компоненті?"}'::jsonb, 'react', '{"mode":"single","code":"const [visible, setVisible] = useState<Todo[]>([]);\nuseEffect(() => {\n  setVisible(todos.filter((t) => t.text.includes(query)));\n}, [todos, query]);","codeLanguage":"tsx","options":[{"id":"a","text":{"en":"Compute `const visible = todos.filter(...)` during render (with `useMemo` only if it''s measurably slow)","uk":"Обчислити `const visible = todos.filter(...)` під час рендеру (з `useMemo` лише якщо це помітно повільно)"}},{"id":"b","text":{"en":"Keep the current effect: it''s the idiomatic way","uk":"Залишити поточний ефект, це ідіоматичний спосіб"}},{"id":"c","text":{"en":"Move `setVisible` into `useLayoutEffect` to avoid flicker","uk":"Перенести `setVisible` у `useLayoutEffect`, щоб уникнути мерехтіння"}},{"id":"d","text":{"en":"Store `visible` in a ref and update it in the effect","uk":"Зберігати `visible` у ref і оновлювати в ефекті"}}]}'::jsonb, null::jsonb),
  ('react-memo-callback', 'quiz', 4, 150, '{"en":"memo and inline callbacks","uk":"memo та вбудовані колбеки"}'::jsonb, '{"en":"`Row` is wrapped in `memo`. Why does it still re-render whenever `List` renders, and what fixes it?","uk":"`Row` обгорнуто в `memo`. Чому він усе одно ререндериться разом зі `List`, і як це виправити?"}'::jsonb, 'react', '{"mode":"single","code":"const Row = memo(function Row({ item, onSelect }: Props) { /* ... */ });\n\nfunction List({ items }: { items: Item[] }) {\n  const [selected, setSelected] = useState<string | null>(null);\n  return items.map((item) => (\n    <Row key={item.id} item={item} onSelect={(id) => setSelected(id)} />\n  ));\n}","codeLanguage":"tsx","options":[{"id":"a","text":{"en":"`onSelect` is a new function each render; wrap it in `useCallback` (with correct deps)","uk":"`onSelect` щоразу є новою функцією; обгорніть її в `useCallback` (з правильними залежностями)"}},{"id":"b","text":{"en":"`memo` only works for class components","uk":"`memo` працює лише для класових компонентів"}},{"id":"c","text":{"en":"`key` must be a string to enable memoisation","uk":"Для мемоізації `key` має бути рядком"}},{"id":"d","text":{"en":"Rows always re-render when their parent does; nothing helps","uk":"Рядки завжди ререндеряться разом із батьком, нічого не допоможе"}}]}'::jsonb, null::jsonb),
  ('react-searchable-list', 'practice', 3, 900, '{"en":"Searchable list","uk":"Список із пошуком"}'::jsonb, '{"en":"Finish the `App` component:\n\n1. Add a **labelled** text input (label text: `Search`) that filters `FRUITS` case-insensitively as you type.\n2. Show matching fruits in a `<ul>`.\n3. When nothing matches, show `No results` instead of the list.\n4. Show the count in an element with `data-testid=\"count\"`, e.g. `3 of 6`.\n\nDerive the filtered list during render; you don''t need `useEffect`.","uk":"Завершіть компонент `App`:\n\n1. Додайте текстове поле **з міткою** (текст мітки: `Search`), що фільтрує `FRUITS` без урахування регістру під час введення.\n2. Показуйте відповідні фрукти в `<ul>`.\n3. Коли збігів немає, показуйте `No results` замість списку.\n4. Показуйте кількість в елементі з `data-testid=\"count\"`, наприклад `3 of 6`.\n\nОбчислюйте відфільтрований список під час рендеру; `useEffect` не потрібен."}'::jsonb, 'react', null::jsonb, '{"framework":"react-ts","files":{"/App.tsx":"import { useState } from \"react\";\n\nexport const FRUITS = [\"Apple\", \"Apricot\", \"Banana\", \"Cherry\", \"Grape\", \"Mango\"];\n\nexport default function App() {\n  // TODO: query state, labelled input, filtered list, count, empty state\n  return (\n    <main>\n      <h1>Fruits</h1>\n      <ul>\n        {FRUITS.map((f) => (\n          <li key={f}>{f}</li>\n        ))}\n      </ul>\n    </main>\n  );\n}\n"},"activeFile":"/App.tsx","tests":"import { describe, it, expect, screen, user } from \"./test-kit\";\n\ndescribe(\"searchable list\", () => {\n  it(\"shows all fruits initially with a count\", async () => {\n    expect(await screen.findAllByRole(\"listitem\")).toHaveLength(6);\n    expect(screen.getByTestId(\"count\")).toHaveTextContent(\"6 of 6\");\n  });\n  it(\"filters case-insensitively\", async () => {\n    await user.type(await screen.findByLabelText(\"Search\"), \"ap\");\n    const items = screen.getAllByRole(\"listitem\").map((li) => li.textContent);\n    expect(items).toEqual([\"Apple\", \"Apricot\", \"Grape\"]);\n    expect(screen.getByTestId(\"count\")).toHaveTextContent(\"3 of 6\");\n  });\n  it(\"shows an empty state\", async () => {\n    const input = await screen.findByLabelText(\"Search\");\n    await user.clear(input);\n    await user.type(input, \"zzz\");\n    expect(screen.getByText(\"No results\")).toBeInTheDocument();\n    expect(screen.queryAllByRole(\"listitem\")).toHaveLength(0);\n  });\n});\n","testCount":3}'::jsonb),
  ('rec-base-case', 'quiz', 1, 60, '{"en":"Missing base case","uk":"Відсутній базовий випадок"}'::jsonb, '{"en":"What happens when you call `countdown(3)`?","uk":"Що станеться під час виклику `countdown(3)`?"}'::jsonb, 'recursion', '{"mode":"single","code":"function countdown(n) {\n  console.log(n);\n  countdown(n - 1);\n}","codeLanguage":"js","options":[{"id":"a","text":{"en":"Logs 3, 2, 1, 0 and stops","uk":"Виведе 3, 2, 1, 0 і зупиниться"}},{"id":"b","text":{"en":"Logs forever (negative numbers) until `RangeError: Maximum call stack size exceeded`","uk":"Виводить безкінечно (від''ємні числа), доки не буде `RangeError: Maximum call stack size exceeded`"}},{"id":"c","text":{"en":"Logs only 3","uk":"Виведе лише 3"}},{"id":"d","text":{"en":"Throws a SyntaxError","uk":"Кине SyntaxError"}}]}'::jsonb, null::jsonb),
  ('rec-fib-complexity', 'quiz', 2, 90, '{"en":"Naive Fibonacci","uk":"Наївне Фібоначчі"}'::jsonb, '{"en":"What is the time complexity of this `fib(n)`?","uk":"Яка часова складність цього `fib(n)`?"}'::jsonb, 'recursion', '{"mode":"single","code":"const fib = (n) => (n < 2 ? n : fib(n - 1) + fib(n - 2));","codeLanguage":"js","options":[{"id":"a","text":{"en":"O(n)","uk":"O(n)"}},{"id":"b","text":{"en":"O(n log n)","uk":"O(n log n)"}},{"id":"c","text":{"en":"O(2ⁿ) (exponential)","uk":"O(2ⁿ) (експоненційна)"}},{"id":"d","text":{"en":"O(n²)","uk":"O(n²)"}}]}'::jsonb, null::jsonb),
  ('rec-stack-depth', 'quiz', 3, 120, '{"en":"Deep recursion","uk":"Глибока рекурсія"}'::jsonb, '{"en":"A recursive `length(node)` crashes on a linked list with 200,000 nodes. What''s the most robust fix in JavaScript?","uk":"Рекурсивна `length(node)` падає на зв''язному списку з 200 000 вузлів. Яке виправлення в JavaScript найнадійніше?"}'::jsonb, 'recursion', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"Rewrite it as a loop (or use an explicit stack)","uk":"Переписати як цикл (або використати явний стек)"}},{"id":"b","text":{"en":"Make it a tail call: engines optimise it","uk":"Зробити хвостовий виклик: рушії його оптимізують"}},{"id":"c","text":{"en":"Wrap the call in `try/catch`","uk":"Обгорнути виклик у `try/catch`"}},{"id":"d","text":{"en":"Use `async` recursion","uk":"Використати `async`-рекурсію"}}]}'::jsonb, null::jsonb),
  ('rec-subsets-count', 'quiz', 3, 120, '{"en":"Counting subsets","uk":"Кількість підмножин"}'::jsonb, '{"en":"A backtracking function generates every subset of an array of 20 items. Roughly how many subsets does it produce?","uk":"Функція з пошуком із поверненням генерує всі підмножини масиву з 20 елементів. Приблизно скільки підмножин вона створить?"}'::jsonb, 'recursion', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"20","uk":"20"}},{"id":"b","text":{"en":"400","uk":"400"}},{"id":"c","text":{"en":"About a million (2²⁰)","uk":"Близько мільйона (2²⁰)"}},{"id":"d","text":{"en":"20! ≈ 2.4 × 10¹⁸","uk":"20! ≈ 2.4 × 10¹⁸"}}]}'::jsonb, null::jsonb),
  ('rec-tree-traversal', 'quiz', 4, 150, '{"en":"Tree traversal order","uk":"Порядок обходу дерева"}'::jsonb, '{"en":"For a binary **search** tree, which traversal visits the values in ascending order?","uk":"Який обхід бінарного дерева **пошуку** відвідує значення в порядку зростання?"}'::jsonb, 'recursion', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"Pre-order (node, left, right)","uk":"Прямий (вузол, ліве, праве)"}},{"id":"b","text":{"en":"In-order (left, node, right)","uk":"Симетричний (ліве, вузол, праве)"}},{"id":"c","text":{"en":"Post-order (left, right, node)","uk":"Зворотний (ліве, праве, вузол)"}},{"id":"d","text":{"en":"Level-order (BFS)","uk":"За рівнями (BFS)"}}]}'::jsonb, null::jsonb),
  ('rec-flatten-depth', 'practice', 2, 720, '{"en":"Flatten nested arrays","uk":"Розгорніть вкладені масиви"}'::jsonb, '{"en":"Implement `flatten(array, depth = Infinity)` **recursively**, without `Array.prototype.flat`:\n\n- Nested arrays are flattened up to `depth` levels.\n- `depth = 0` returns a shallow copy.\n- Don''t mutate the input.\n\n```js\nflatten([1, [2, [3, [4]]]])    // [1, 2, 3, 4]\nflatten([1, [2, [3, [4]]]], 1) // [1, 2, [3, [4]]]\n```","uk":"Реалізуйте `flatten(array, depth = Infinity)` **рекурсивно**, без `Array.prototype.flat`:\n\n- Вкладені масиви розгортаються на глибину до `depth` рівнів.\n- `depth = 0` повертає поверхневу копію.\n- Не змінюйте вхідні дані.\n\n```js\nflatten([1, [2, [3, [4]]]])    // [1, 2, 3, 4]\nflatten([1, [2, [3, [4]]]], 1) // [1, 2, [3, [4]]]\n```"}'::jsonb, 'recursion', null::jsonb, '{"framework":"vanilla-js","files":{"/src/flatten.js":"export function flatten(array, depth = Infinity) {\n  // TODO: recursive, no Array.prototype.flat\n  return array;\n}\n","/index.js":"import \"./styles.css\";\nimport { flatten } from \"./src/flatten\";\n\nconst nested = [1, [2, [3, [4, [5]]]], 6];\ndocument.getElementById(\"app\").innerHTML =\n  \"<h1>Flatten</h1>\" +\n  \"<p>Input: <code>\" + JSON.stringify(nested) + \"</code></p>\" +\n  \"<p>Full: <output id=\\\"full\\\">\" + JSON.stringify(flatten(nested)) + \"</output></p>\" +\n  \"<p>Depth 1: <output id=\\\"one\\\">\" + JSON.stringify(flatten(nested, 1)) + \"</output></p>\";\n"},"visibleFiles":["/src/flatten.js","/index.js"],"activeFile":"/src/flatten.js","tests":"import { describe, it, expect, screen } from \"./test-kit\";\nimport { flatten } from \"../src/flatten\";\n\ndescribe(\"flatten\", () => {\n  it(\"flattens completely by default\", () => {\n    expect(flatten([1, [2, [3, [4]]], 5])).toEqual([1, 2, 3, 4, 5]);\n  });\n  it(\"respects depth\", () => {\n    expect(flatten([1, [2, [3, [4]]]], 1)).toEqual([1, 2, [3, [4]]]);\n    expect(flatten([1, [2, [3, [4]]]], 2)).toEqual([1, 2, 3, [4]]);\n  });\n  it(\"returns a shallow copy for depth 0\", () => {\n    const input = [1, [2]];\n    const out = flatten(input, 0);\n    expect(out).toEqual([1, [2]]);\n    expect(out === input).toBe(false);\n  });\n  it(\"does not mutate the input\", () => {\n    const input = [1, [2, [3]]];\n    flatten(input);\n    expect(input).toEqual([1, [2, [3]]]);\n  });\n  it(\"does not use Array.prototype.flat\", () => {\n    const original = Array.prototype.flat;\n    Array.prototype.flat = function () { throw new Error(\"flat() is not allowed\"); };\n    try {\n      expect(flatten([[1], [[2]]])).toEqual([1, 2]);\n    } finally {\n      Array.prototype.flat = original;\n    }\n  });\n  it(\"renders the demo\", async () => {\n    expect((await screen.findByText(\"[1,2,3,4,5,6]\")).id).toBe(\"full\");\n  });\n});\n","testCount":6}'::jsonb),
  ('rx-cold-http', 'quiz', 2, 90, '{"en":"Cold observables","uk":"Холодні observable"}'::jsonb, '{"en":"A template uses `user$ | async` twice, where `user$ = http.get(''/api/me'')`. How many HTTP requests are made?","uk":"Шаблон двічі використовує `user$ | async`, де `user$ = http.get(''/api/me'')`. Скільки HTTP-запитів буде зроблено?"}'::jsonb, 'rxjs', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"One, observables are cached","uk":"Один, observable кешуються"}},{"id":"b","text":{"en":"Two, each subscription runs the cold observable again","uk":"Два, кожна підписка знову запускає холодний observable"}},{"id":"c","text":{"en":"Zero until `.toPromise()` is called","uk":"Нуль, доки не викликано `.toPromise()`"}},{"id":"d","text":{"en":"It depends on change detection","uk":"Залежить від виявлення змін"}}]}'::jsonb, null::jsonb),
  ('rx-switchmap-search', 'quiz', 2, 90, '{"en":"Typeahead operator","uk":"Оператор для пошуку"}'::jsonb, '{"en":"For a search box where only the latest query''s results matter, which operator should map queries to requests?","uk":"Для поля пошуку, де важливі лише результати останнього запиту, який оператор має перетворювати запити на HTTP-запити?"}'::jsonb, 'rxjs', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"`mergeMap`","uk":"`mergeMap`"}},{"id":"b","text":{"en":"`concatMap`","uk":"`concatMap`"}},{"id":"c","text":{"en":"`switchMap`","uk":"`switchMap`"}},{"id":"d","text":{"en":"`exhaustMap`","uk":"`exhaustMap`"}}]}'::jsonb, null::jsonb),
  ('rx-exhaustmap-submit', 'quiz', 3, 120, '{"en":"Double submit","uk":"Подвійне надсилання"}'::jsonb, '{"en":"Users double-click \"Pay\" and get charged twice. Which operator on `click$` prevents a second request while the first is in flight?","uk":"Користувачі двічі клікають «Оплатити», і з них знімають гроші двічі. Який оператор на `click$` не дасть зробити другий запит, поки триває перший?"}'::jsonb, 'rxjs', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"`switchMap`","uk":"`switchMap`"}},{"id":"b","text":{"en":"`exhaustMap`","uk":"`exhaustMap`"}},{"id":"c","text":{"en":"`mergeMap`","uk":"`mergeMap`"}},{"id":"d","text":{"en":"`map`","uk":"`map`"}}]}'::jsonb, null::jsonb),
  ('rx-behaviorsubject', 'quiz', 3, 120, '{"en":"Subjects","uk":"Subject"}'::jsonb, '{"en":"Which Subject gives a late subscriber the **current** value immediately, and always has one?","uk":"Який Subject одразу дає пізньому підписнику **поточне** значення й завжди його має?"}'::jsonb, 'rxjs', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"`Subject`","uk":"`Subject`"}},{"id":"b","text":{"en":"`BehaviorSubject`","uk":"`BehaviorSubject`"}},{"id":"c","text":{"en":"`AsyncSubject`","uk":"`AsyncSubject`"}},{"id":"d","text":{"en":"`ReplaySubject(0)`","uk":"`ReplaySubject(0)`"}}]}'::jsonb, null::jsonb),
  ('rx-catcherror-placement', 'quiz', 4, 150, '{"en":"Where to catch errors","uk":"Де перехоплювати помилки"}'::jsonb, '{"en":"After one failed request this typeahead never searches again. Why?","uk":"Після одного невдалого запиту цей пошук більше ніколи не шукає. Чому?"}'::jsonb, 'rxjs', '{"mode":"single","code":"results$ = query$.pipe(\n  debounceTime(300),\n  switchMap((q) => search(q)),\n  catchError(() => of([])),\n);","codeLanguage":"ts","options":[{"id":"a","text":{"en":"`catchError` on the outer stream replaces it with `of([])`, which completes, so the subscription ends","uk":"`catchError` на зовнішньому потоці замінює його на `of([])`, який завершується, тож підписка закінчується"}},{"id":"b","text":{"en":"`switchMap` can''t handle errors","uk":"`switchMap` не вміє обробляти помилки"}},{"id":"c","text":{"en":"`debounceTime` swallows later values","uk":"`debounceTime` поглинає пізніші значення"}},{"id":"d","text":{"en":"HTTP errors close the input element","uk":"HTTP-помилки закривають поле введення"}}]}'::jsonb, null::jsonb),
  ('rx-typeahead', 'practice', 4, 1200, '{"en":"Typeahead pipeline","uk":"Конвеєр пошуку під час введення"}'::jsonb, '{"en":"Implement `createTypeahead(query$, search, debounceMs)` returning an `Observable<string[]>`:\n\n- Trim queries and wait `debounceMs` after the user stops typing.\n- Skip queries shorter than 2 characters and repeated identical queries.\n- Call `search(q)` (returns an Observable) and **cancel** the previous search when a new query arrives.\n- If a search errors, emit `[]` for that query and **keep working** for the next ones.","uk":"Реалізуйте `createTypeahead(query$, search, debounceMs)`, що повертає `Observable<string[]>`:\n\n- Обрізайте пробіли в запитах і чекайте `debounceMs` після того, як користувач перестав друкувати.\n- Пропускайте запити коротші за 2 символи й повтори однакових запитів.\n- Викликайте `search(q)` (повертає Observable) і **скасовуйте** попередній пошук, коли надходить новий запит.\n- Якщо пошук завершився помилкою, видайте `[]` для цього запиту й **продовжуйте працювати** для наступних."}'::jsonb, 'rxjs', null::jsonb, '{"framework":"vanilla-ts","files":{"/src/typeahead.ts":"import { Observable } from \"rxjs\";\nimport { map } from \"rxjs/operators\";\n\nexport function createTypeahead(\n  query$: Observable<string>,\n  search: (q: string) => Observable<string[]>,\n  debounceMs: number,\n): Observable<string[]> {\n  // TODO: trim, debounce, min length, distinct, switch to the latest search, recover from errors\n  return query$.pipe(map(() => []));\n}\n","/index.ts":"import \"./styles.css\";\nimport { fromEvent, of } from \"rxjs\";\nimport { delay, map } from \"rxjs/operators\";\nimport { createTypeahead } from \"./src/typeahead\";\n\nconst LANGS = [\"JavaScript\", \"Java\", \"TypeScript\", \"Python\", \"Rust\", \"Ruby\", \"Go\", \"Kotlin\"];\nconst app = document.getElementById(\"app\")!;\napp.innerHTML = `<h1>Typeahead</h1><label for=\"q\">Language</label> <input id=\"q\" autocomplete=\"off\" /><ul id=\"results\"></ul>`;\nconst input = document.getElementById(\"q\") as HTMLInputElement;\nconst list = document.getElementById(\"results\")!;\n\nconst search = (q: string) => of(LANGS.filter((l) => l.toLowerCase().includes(q.toLowerCase()))).pipe(delay(150));\ncreateTypeahead(fromEvent(input, \"input\").pipe(map(() => input.value)), search, 250).subscribe((items) => {\n  list.innerHTML = items.map((i) => `<li>${i}</li>`).join(\"\");\n});\n"},"visibleFiles":["/src/typeahead.ts","/index.ts"],"activeFile":"/src/typeahead.ts","tests":"import { describe, it, expect, sleep } from \"./test-kit\";\nimport { Observable, Subject, of, throwError, timer } from \"rxjs\";\nimport { map } from \"rxjs/operators\";\nimport { createTypeahead } from \"../src/typeahead\";\n\nfunction harness(search: (q: string) => Observable<string[]>, debounceMs = 30) {\n  const query$ = new Subject<string>();\n  const results: string[][] = [];\n  const sub = createTypeahead(query$, search, debounceMs).subscribe((r) => results.push(r));\n  return { query$, results, sub };\n}\n\ndescribe(\"createTypeahead\", () => {\n  it(\"debounces and searches the trimmed query\", async () => {\n    const calls: string[] = [];\n    const { query$, results, sub } = harness((q) => { calls.push(q); return of([q.toUpperCase()]); });\n    query$.next(\"r\");\n    query$.next(\"re\");\n    query$.next(\" rea \");\n    await sleep(60);\n    expect(calls).toEqual([\"rea\"]);\n    expect(results).toEqual([[\"REA\"]]);\n    sub.unsubscribe();\n  });\n  it(\"ignores short and repeated queries\", async () => {\n    const calls: string[] = [];\n    const { query$, sub } = harness((q) => { calls.push(q); return of([q]); });\n    query$.next(\"a\");\n    await sleep(50);\n    query$.next(\"ab\");\n    await sleep(50);\n    query$.next(\"ab \");\n    await sleep(50);\n    expect(calls).toEqual([\"ab\"]);\n    sub.unsubscribe();\n  });\n  it(\"cancels the previous search when a new query arrives\", async () => {\n    const { query$, results, sub } = harness((q) => timer(q === \"slow\" ? 120 : 10).pipe(map(() => [q])), 10);\n    query$.next(\"slow\");\n    await sleep(40);\n    query$.next(\"fast\");\n    await sleep(200);\n    expect(results).toEqual([[\"fast\"]]);\n    sub.unsubscribe();\n  });\n  it(\"recovers from a failed search\", async () => {\n    const { query$, results, sub } = harness((q) => (q === \"boom\" ? throwError(() => new Error(\"500\")) : of([q])), 10);\n    query$.next(\"boom\");\n    await sleep(40);\n    query$.next(\"next\");\n    await sleep(40);\n    expect(results).toEqual([[], [\"next\"]]);\n    sub.unsubscribe();\n  });\n});\n","testCount":4,"dependencies":{"rxjs":"7.8.1"}}'::jsonb),
  ('search-binary-precondition', 'quiz', 1, 60, '{"en":"Binary search precondition","uk":"Передумова бінарного пошуку"}'::jsonb, '{"en":"What must be true about an array before you can use binary search on it?","uk":"Що має бути правдою щодо масиву, щоб до нього можна було застосувати бінарний пошук?"}'::jsonb, 'searching-algorithms', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"It must be sorted by the key you search for","uk":"Він має бути відсортований за ключем пошуку"}},{"id":"b","text":{"en":"It must contain no duplicates","uk":"У ньому не має бути дублікатів"}},{"id":"c","text":{"en":"Its length must be a power of two","uk":"Його довжина має бути степенем двійки"}},{"id":"d","text":{"en":"It must contain only numbers","uk":"Він має містити лише числа"}}]}'::jsonb, null::jsonb),
  ('search-binary-complexity', 'quiz', 1, 45, '{"en":"Binary search cost","uk":"Вартість бінарного пошуку"}'::jsonb, '{"en":"Roughly how many comparisons does binary search need in the worst case for a sorted array of 1,000,000 elements?","uk":"Приблизно скільки порівнянь у найгіршому випадку потрібно бінарному пошуку для відсортованого масиву з 1 000 000 елементів?"}'::jsonb, 'searching-algorithms', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"About 20","uk":"Близько 20"}},{"id":"b","text":{"en":"About 1,000","uk":"Близько 1 000"}},{"id":"c","text":{"en":"About 500,000","uk":"Близько 500 000"}},{"id":"d","text":{"en":"About 1,000,000","uk":"Близько 1 000 000"}}]}'::jsonb, null::jsonb),
  ('search-infinite-loop-bug', 'quiz', 3, 120, '{"en":"Spot the infinite loop","uk":"Знайдіть нескінченний цикл"}'::jsonb, '{"en":"This lower-bound implementation sometimes never terminates. Which change fixes it?","uk":"Ця реалізація нижньої межі іноді ніколи не завершується. Яка зміна це виправить?"}'::jsonb, 'searching-algorithms', '{"mode":"single","code":"function lowerBound(a: number[], x: number) {\n  let lo = 0, hi = a.length;\n  while (lo < hi) {\n    const mid = (lo + hi) >> 1;\n    if (a[mid] < x) lo = mid;\n    else hi = mid;\n  }\n  return lo;\n}","codeLanguage":"ts","options":[{"id":"a","text":{"en":"Replace `lo = mid` with `lo = mid + 1`","uk":"Замінити `lo = mid` на `lo = mid + 1`"}},{"id":"b","text":{"en":"Replace `hi = mid` with `hi = mid - 1`","uk":"Замінити `hi = mid` на `hi = mid - 1`"}},{"id":"c","text":{"en":"Use `while (lo <= hi)`","uk":"Використати `while (lo <= hi)`"}},{"id":"d","text":{"en":"Compute `mid` with `Math.ceil`","uk":"Обчислювати `mid` через `Math.ceil`"}}]}'::jsonb, null::jsonb),
  ('search-many-lookups', 'quiz', 2, 90, '{"en":"Many lookups in unsorted data","uk":"Багато пошуків у невідсортованих даних"}'::jsonb, '{"en":"You have an unsorted array of 100,000 user IDs and need to check 50,000 incoming IDs for membership. What is the most efficient approach?","uk":"Є невідсортований масив зі 100 000 ідентифікаторів користувачів, і потрібно перевірити належність 50 000 вхідних ID. Який підхід найефективніший?"}'::jsonb, 'searching-algorithms', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"Call `array.includes(id)` for every incoming ID","uk":"Викликати `array.includes(id)` для кожного вхідного ID"}},{"id":"b","text":{"en":"Build a `Set` once, then use `set.has(id)`","uk":"Один раз побудувати `Set`, потім використовувати `set.has(id)`"}},{"id":"c","text":{"en":"Sort the array before every lookup, then binary search","uk":"Сортувати масив перед кожним пошуком, потім шукати бінарно"}},{"id":"d","text":{"en":"Use `array.find` because it stops early","uk":"Використати `array.find`, бо він зупиняється раніше"}}]}'::jsonb, null::jsonb),
  ('search-two-pointers', 'quiz', 3, 120, '{"en":"Pair sum in a sorted array","uk":"Пара з сумою у відсортованому масиві"}'::jsonb, '{"en":"Which statements about the two-pointer technique for finding a pair with sum `S` in a **sorted** array are true? Select all that apply.","uk":"Які твердження про техніку двох вказівників для пошуку пари з сумою `S` у **відсортованому** масиві правильні? Оберіть усі правильні."}'::jsonb, 'searching-algorithms', '{"mode":"multi","codeLanguage":"ts","options":[{"id":"a","text":{"en":"It runs in O(n) time and O(1) extra space","uk":"Працює за O(n) часу та O(1) додаткової пам''яті"}},{"id":"b","text":{"en":"If the current sum is too small, move the left pointer right","uk":"Якщо поточна сума замала, зсуваємо лівий вказівник праворуч"}},{"id":"c","text":{"en":"It also works on unsorted arrays","uk":"Це працює й на невідсортованих масивах"}},{"id":"d","text":{"en":"Each step can safely discard one candidate element","uk":"Кожен крок безпечно відкидає одного кандидата"}}]}'::jsonb, null::jsonb),
  ('search-on-answer', 'quiz', 4, 150, '{"en":"Binary search on the answer","uk":"Бінарний пошук за відповіддю"}'::jsonb, '{"en":"Packages with weights `w[]` must ship in order within `D` days. You need the minimum ship capacity. Why is binary search over the capacity valid?","uk":"Посилки з вагами `w[]` треба відправити по черзі за `D` днів. Потрібно знайти мінімальну місткість корабля. Чому тут коректний бінарний пошук за місткістю?"}'::jsonb, 'searching-algorithms', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"Feasibility is monotonic: if capacity C works, every capacity above C also works","uk":"Здійсненність монотонна: якщо місткість C підходить, то й будь-яка більша теж"}},{"id":"b","text":{"en":"The weights array is sorted","uk":"Масив ваг відсортований"}},{"id":"c","text":{"en":"Capacity can only take powers of two","uk":"Місткість може бути лише степенем двійки"}},{"id":"d","text":{"en":"The number of days is always less than log₂(n)","uk":"Кількість днів завжди менша за log₂(n)"}}]}'::jsonb, null::jsonb),
  ('search-implement-binary-search', 'practice', 2, 600, '{"en":"Implement binary search","uk":"Реалізуйте бінарний пошук"}'::jsonb, '{"en":"Implement `binarySearch(items, target)` in **O(log n)**. `items` is sorted ascending. Return the index of `target`, or `-1` if it is absent. Don''t use `indexOf`, `includes` or `findIndex`.\n\nThe preview shows a few sample searches; tests run automatically after every change.","uk":"Реалізуйте `binarySearch(items, target)` за **O(log n)**. `items` відсортовано за зростанням. Поверніть індекс `target` або `-1`, якщо його немає. Не використовуйте `indexOf`, `includes` чи `findIndex`.\n\nУ попередньому перегляді — кілька прикладів пошуку; тести запускаються автоматично після кожної зміни."}'::jsonb, 'searching-algorithms', null::jsonb, '{"framework":"vanilla-ts","files":{"/src/binarySearch.ts":"/**\n * Returns the index of `target` in the ascending array `items`, or -1.\n * Must run in O(log n).\n */\nexport function binarySearch(items: number[], target: number): number {\n  // TODO\n  return -1;\n}\n","/index.ts":"import \"./styles.css\";\nimport { binarySearch } from \"./src/binarySearch\";\n\nconst data = [2, 3, 5, 7, 11, 13, 17, 19, 23];\nconst rows = [7, 2, 23, 4]\n  .map((t) => `<li>binarySearch(data, ${t}) → <output>${binarySearch(data, t)}</output></li>`)\n  .join(\"\");\n\ndocument.getElementById(\"app\")!.innerHTML = `\n  <h1>Binary search</h1>\n  <p><code>[${data.join(\", \")}]</code></p>\n  <ul>${rows}</ul>\n`;\n"},"visibleFiles":["/src/binarySearch.ts","/index.ts"],"activeFile":"/src/binarySearch.ts","tests":"import { describe, it, expect } from \"./test-kit\";\nimport { binarySearch } from \"../src/binarySearch\";\n\nconst primes = [2, 3, 5, 7, 11, 13, 17, 19, 23];\n\ndescribe(\"binarySearch\", () => {\n  it(\"finds an element in the middle\", () => expect(binarySearch(primes, 11)).toBe(4));\n  it(\"finds the first and last elements\", () => {\n    expect(binarySearch(primes, 2)).toBe(0);\n    expect(binarySearch(primes, 23)).toBe(8);\n  });\n  it(\"returns -1 for a missing element\", () => {\n    expect(binarySearch(primes, 4)).toBe(-1);\n    expect(binarySearch(primes, 100)).toBe(-1);\n    expect(binarySearch(primes, -5)).toBe(-1);\n  });\n  it(\"handles empty and single-element arrays\", () => {\n    expect(binarySearch([], 1)).toBe(-1);\n    expect(binarySearch([5], 5)).toBe(0);\n    expect(binarySearch([5], 6)).toBe(-1);\n  });\n  it(\"runs in logarithmic time\", () => {\n    const big = Array.from({ length: 1 << 20 }, (_, i) => i * 2);\n    let reads = 0;\n    const spy = new Proxy(big, {\n      get(target, prop, receiver) {\n        if (typeof prop === \"string\" && /^\\d+$/.test(prop)) reads++;\n        return Reflect.get(target, prop, receiver);\n      },\n    });\n    expect(binarySearch(spy, 777_776)).toBe(388_888);\n    expect(reads).toBeLessThan(64);\n  });\n});\n","testCount":5}'::jsonb),
  ('search-count-occurrences', 'practice', 4, 900, '{"en":"Count occurrences in O(log n)","uk":"Кількість входжень за O(log n)"}'::jsonb, '{"en":"Implement `countOccurrences(sorted, x)`, which returns how many times `x` appears in an ascending array that may contain duplicates. It must make **O(log n)** reads, so a linear scan over the duplicates is not allowed. Hint: two lower-bound searches.","uk":"Реалізуйте `countOccurrences(sorted, x)`, що повертає, скільки разів `x` трапляється у відсортованому за зростанням масиві з можливими дублікатами. Функція має робити **O(log n)** звертань до масиву, тож лінійний прохід по дублікатах заборонено. Підказка: два пошуки нижньої межі."}'::jsonb, 'searching-algorithms', null::jsonb, '{"framework":"vanilla-ts","files":{"/src/count.ts":"/** Number of times `x` occurs in the ascending array `sorted`. O(log n). */\nexport function countOccurrences(sorted: number[], x: number): number {\n  // TODO\n  return 0;\n}\n","/index.ts":"import \"./styles.css\";\nimport { countOccurrences } from \"./src/count\";\n\nconst data = [1, 2, 2, 2, 3, 5, 5, 8];\ndocument.getElementById(\"app\")!.innerHTML = `\n  <h1>Count occurrences</h1>\n  <p><code>[${data.join(\", \")}]</code></p>\n  <p>2 occurs <output id=\"two\">${countOccurrences(data, 2)}</output> times,\n     5 occurs <output id=\"five\">${countOccurrences(data, 5)}</output> times.</p>\n`;\n"},"visibleFiles":["/src/count.ts","/index.ts"],"activeFile":"/src/count.ts","tests":"import { describe, it, expect } from \"./test-kit\";\nimport { countOccurrences } from \"../src/count\";\n\ndescribe(\"countOccurrences\", () => {\n  it(\"counts a run of duplicates\", () => expect(countOccurrences([1, 2, 2, 2, 3], 2)).toBe(3));\n  it(\"counts single and missing values\", () => {\n    expect(countOccurrences([1, 2, 2, 2, 3], 3)).toBe(1);\n    expect(countOccurrences([1, 2, 2, 2, 3], 4)).toBe(0);\n    expect(countOccurrences([], 1)).toBe(0);\n  });\n  it(\"handles runs at both ends\", () => {\n    expect(countOccurrences([7, 7, 7, 8, 9, 9], 7)).toBe(3);\n    expect(countOccurrences([7, 7, 7, 8, 9, 9], 9)).toBe(2);\n  });\n  it(\"uses a logarithmic number of reads\", () => {\n    const big = new Array(1 << 20).fill(42);\n    let reads = 0;\n    const spy = new Proxy(big, {\n      get(target, prop, receiver) {\n        if (typeof prop === \"string\" && /^\\d+$/.test(prop)) reads++;\n        return Reflect.get(target, prop, receiver);\n      },\n    });\n    expect(countOccurrences(spy, 42)).toBe(1 << 20);\n    expect(reads).toBeLessThan(100);\n  });\n});\n","testCount":4}'::jsonb),
  ('sort-stability', 'quiz', 2, 90, '{"en":"Stable sorting","uk":"Стабільне сортування"}'::jsonb, '{"en":"What does it mean that a sort is **stable**?","uk":"Що означає, що сортування **стабільне**?"}'::jsonb, 'sorting-algorithms', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"Elements that compare equal keep their original relative order","uk":"Елементи, що порівнюються як рівні, зберігають початковий взаємний порядок"}},{"id":"b","text":{"en":"It always runs in O(n log n)","uk":"Воно завжди працює за O(n log n)"}},{"id":"c","text":{"en":"It never uses extra memory","uk":"Воно ніколи не використовує додаткової пам''яті"}},{"id":"d","text":{"en":"It produces the same output on every browser","uk":"Воно дає однаковий результат у всіх браузерах"}}]}'::jsonb, null::jsonb),
  ('sort-quick-worst', 'quiz', 3, 120, '{"en":"Quicksort worst case","uk":"Найгірший випадок quicksort"}'::jsonb, '{"en":"When does quicksort with \"always pick the first element as pivot\" hit O(n²)?","uk":"Коли quicksort з правилом «завжди брати перший елемент як опорний» потрапляє в O(n²)?"}'::jsonb, 'sorting-algorithms', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"On already sorted (or reverse-sorted) input","uk":"На вже відсортованих (або відсортованих у зворотному порядку) даних"}},{"id":"b","text":{"en":"On random input","uk":"На випадкових даних"}},{"id":"c","text":{"en":"When the array has an even length","uk":"Коли довжина масиву парна"}},{"id":"d","text":{"en":"Never; quicksort is always O(n log n)","uk":"Ніколи; quicksort завжди O(n log n)"}}]}'::jsonb, null::jsonb),
  ('sort-lower-bound', 'quiz', 3, 120, '{"en":"Beating n log n","uk":"Швидше за n log n"}'::jsonb, '{"en":"You must sort 10 million exam scores, all integers from 0 to 100. What is the fastest asymptotic approach?","uk":"Треба відсортувати 10 мільйонів екзаменаційних балів, усі цілі від 0 до 100. Який підхід асимптотично найшвидший?"}'::jsonb, 'sorting-algorithms', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"Merge sort, O(n log n)","uk":"Злиттям, O(n log n)"}},{"id":"b","text":{"en":"Counting sort, O(n + k) with k = 101","uk":"Підрахунком, O(n + k) при k = 101"}},{"id":"c","text":{"en":"Quicksort with a random pivot","uk":"Quicksort з випадковим опорним елементом"}},{"id":"d","text":{"en":"Binary-insertion sort","uk":"Вставками з бінарним пошуком"}}]}'::jsonb, null::jsonb),
  ('sort-multi-key', 'quiz', 2, 90, '{"en":"Sorting by two keys","uk":"Сортування за двома ключами"}'::jsonb, '{"en":"Which comparator sorts users by `age` ascending, and by `name` alphabetically for equal ages?","uk":"Який компаратор сортує користувачів за `age` за зростанням, а при рівному віці за `name` за абеткою?"}'::jsonb, 'sorting-algorithms', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"`(a, b) => a.age - b.age || a.name.localeCompare(b.name)`","uk":"`(a, b) => a.age - b.age || a.name.localeCompare(b.name)`"}},{"id":"b","text":{"en":"`(a, b) => a.age > b.age && a.name > b.name`","uk":"`(a, b) => a.age > b.age && a.name > b.name`"}},{"id":"c","text":{"en":"`(a, b) => a.name.localeCompare(b.name) - a.age`","uk":"`(a, b) => a.name.localeCompare(b.name) - a.age`"}},{"id":"d","text":{"en":"`(a, b) => a.age - b.age && a.name.localeCompare(b.name)`","uk":"`(a, b) => a.age - b.age && a.name.localeCompare(b.name)`"}}]}'::jsonb, null::jsonb),
  ('sort-merge-memory', 'quiz', 4, 120, '{"en":"Merge vs heap sort","uk":"Злиттям чи пірамідальне"}'::jsonb, '{"en":"You need a guaranteed O(n log n) sort on an embedded device with very little free memory, and stability doesn''t matter. Which fits best?","uk":"Потрібне гарантоване сортування за O(n log n) на вбудованому пристрої з дуже малим обсягом вільної пам''яті, а стабільність не важлива. Що підходить найкраще?"}'::jsonb, 'sorting-algorithms', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"Merge sort","uk":"Злиттям"}},{"id":"b","text":{"en":"Heapsort","uk":"Пірамідальне (heapsort)"}},{"id":"c","text":{"en":"Quicksort","uk":"Швидке (quicksort)"}},{"id":"d","text":{"en":"Counting sort","uk":"Підрахунком"}}]}'::jsonb, null::jsonb),
  ('sort-merge-sort', 'practice', 3, 1080, '{"en":"Stable merge sort","uk":"Стабільне сортування злиттям"}'::jsonb, '{"en":"Implement `mergeSort(items, compare)`:\n\n- Returns a **new** sorted array and doesn''t mutate `items`.\n- Must be **stable**: equal elements keep their input order.\n- O(n log n). Don''t call `Array.prototype.sort`.","uk":"Реалізуйте `mergeSort(items, compare)`:\n\n- Повертає **новий** відсортований масив і не змінює `items`.\n- Має бути **стабільним**: рівні елементи зберігають порядок вхідних даних.\n- O(n log n). Не викликайте `Array.prototype.sort`."}'::jsonb, 'sorting-algorithms', null::jsonb, '{"framework":"vanilla-ts","files":{"/src/mergeSort.ts":"export function mergeSort<T>(items: T[], compare: (a: T, b: T) => number): T[] {\n  // TODO: divide, sort halves recursively, merge (stable!)\n  return items;\n}\n","/index.ts":"import \"./styles.css\";\nimport { mergeSort } from \"./src/mergeSort\";\n\nconst people = [\n  { name: \"Ada\", age: 36 },\n  { name: \"Linus\", age: 28 },\n  { name: \"Grace\", age: 36 },\n  { name: \"Tim\", age: 28 },\n];\nconst sorted = mergeSort(people, (a, b) => a.age - b.age);\ndocument.getElementById(\"app\")!.innerHTML =\n  \"<h1>By age (stable)</h1><ol>\" + sorted.map((p) => `<li>${p.name} (${p.age})</li>`).join(\"\") + \"</ol>\";\n"},"visibleFiles":["/src/mergeSort.ts","/index.ts"],"activeFile":"/src/mergeSort.ts","tests":"import { describe, it, expect, screen } from \"./test-kit\";\nimport { mergeSort } from \"../src/mergeSort\";\n\nconst num = (a: number, b: number) => a - b;\n\ndescribe(\"mergeSort\", () => {\n  it(\"sorts numbers\", () => {\n    expect(mergeSort([5, 1, 4, 2, 3], num)).toEqual([1, 2, 3, 4, 5]);\n    expect(mergeSort([10, 9, 100, 1], num)).toEqual([1, 9, 10, 100]);\n  });\n  it(\"handles empty and single-element arrays\", () => {\n    expect(mergeSort([], num)).toEqual([]);\n    expect(mergeSort([7], num)).toEqual([7]);\n  });\n  it(\"does not mutate the input\", () => {\n    const input = [3, 1, 2];\n    const out = mergeSort(input, num);\n    expect(input).toEqual([3, 1, 2]);\n    expect(out === input).toBe(false);\n  });\n  it(\"is stable\", () => {\n    const rows = [\n      { k: 1, id: \"a\" }, { k: 0, id: \"b\" }, { k: 1, id: \"c\" }, { k: 0, id: \"d\" }, { k: 1, id: \"e\" },\n    ];\n    expect(mergeSort(rows, (x, y) => x.k - y.k).map((r) => r.id)).toEqual([\"b\", \"d\", \"a\", \"c\", \"e\"]);\n  });\n  it(\"does not use Array.prototype.sort\", () => {\n    const original = Array.prototype.sort;\n    let used = false;\n    Array.prototype.sort = function (this: unknown[], ...args: unknown[]) {\n      used = true;\n      return original.apply(this, args as never);\n    } as typeof original;\n    try {\n      mergeSort([3, 2, 1], num);\n    } finally {\n      Array.prototype.sort = original;\n    }\n    expect(used).toBe(false);\n  });\n  it(\"handles large inputs quickly\", () => {\n    const big = Array.from({ length: 50000 }, (_, i) => (i * 7919) % 50000);\n    const t0 = Date.now();\n    const out = mergeSort(big, num);\n    expect(Date.now() - t0).toBeLessThan(1500);\n    expect(out[0]).toBe(0);\n    expect(out[49999]).toBe(49999);\n  });\n  it(\"renders the demo\", async () => {\n    const items = await screen.findAllByRole(\"listitem\");\n    expect(items.map((li) => li.textContent)).toEqual([\"Linus (28)\", \"Tim (28)\", \"Ada (36)\", \"Grace (36)\"]);\n  });\n});\n","testCount":7}'::jsonb),
  ('state-derive-not-store', 'quiz', 1, 60, '{"en":"Derived data","uk":"Похідні дані"}'::jsonb, '{"en":"A cart stores `items` and also `total` in state. What''s the main risk?","uk":"Кошик зберігає в стані `items` і окремо `total`. Який головний ризик?"}'::jsonb, 'state-management', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"`total` can get out of sync with `items`; derive it from `items` instead","uk":"`total` може розійтися з `items`; краще обчислювати його з `items`"}},{"id":"b","text":{"en":"Numbers can''t be stored in state","uk":"Числа не можна зберігати в стані"}},{"id":"c","text":{"en":"It makes the bundle larger","uk":"Це збільшує розмір бандла"}},{"id":"d","text":{"en":"There''s no risk; it''s the recommended pattern","uk":"Ризику немає; це рекомендований патерн"}}]}'::jsonb, null::jsonb),
  ('state-mutation-bug', 'quiz', 2, 90, '{"en":"Mutation in a reducer","uk":"Мутація в редʼюсері"}'::jsonb, '{"en":"The UI doesn''t update after `toggle`. Why?","uk":"Після `toggle` інтерфейс не оновлюється. Чому?"}'::jsonb, 'state-management', '{"mode":"single","code":"function reducer(state, action) {\n  if (action.type === \"toggle\") {\n    const todo = state.todos.find((t) => t.id === action.id);\n    todo.done = !todo.done;\n    return state;\n  }\n  return state;\n}","codeLanguage":"js","options":[{"id":"a","text":{"en":"The reducer mutates the todo and returns the same `state`, so the reference doesn''t change","uk":"Редʼюсер змінює todo й повертає той самий `state`, тож посилання не змінюється"}},{"id":"b","text":{"en":"`find` doesn''t work on arrays of objects","uk":"`find` не працює з масивами об''єктів"}},{"id":"c","text":{"en":"Reducers must be async","uk":"Редʼюсери мають бути асинхронними"}},{"id":"d","text":{"en":"`done` must be a string","uk":"`done` має бути рядком"}}]}'::jsonb, null::jsonb),
  ('state-server-cache', 'quiz', 3, 120, '{"en":"Server state","uk":"Серверний стан"}'::jsonb, '{"en":"Where should a list of products fetched from the API usually live in a modern React app?","uk":"Де в сучасному React-застосунку зазвичай має жити список товарів, отриманий з API?"}'::jsonb, 'state-management', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"In a server-state cache (TanStack Query / RTK Query) with loading, error and stale handling","uk":"У кеші серверного стану (TanStack Query / RTK Query) з обробкою завантаження, помилок і застарілості"}},{"id":"b","text":{"en":"Copied into a global Redux slice by a `useEffect` in every page","uk":"Скопійованим у глобальний Redux-слайс через `useEffect` на кожній сторінці"}},{"id":"c","text":{"en":"In localStorage","uk":"У localStorage"}},{"id":"d","text":{"en":"In a module-level variable","uk":"У змінній на рівні модуля"}}]}'::jsonb, null::jsonb),
  ('state-url-state', 'quiz', 2, 90, '{"en":"URL state","uk":"Стан в URL"}'::jsonb, '{"en":"Users want to share a link to a filtered, sorted product list. Where should the filters live?","uk":"Користувачі хочуть ділитися посиланням на відфільтрований і відсортований список товарів. Де мають жити фільтри?"}'::jsonb, 'state-management', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"In the URL query string","uk":"У рядку запиту URL"}},{"id":"b","text":{"en":"In component state","uk":"У стані компонента"}},{"id":"c","text":{"en":"In sessionStorage","uk":"У sessionStorage"}},{"id":"d","text":{"en":"In a global store only","uk":"Лише в глобальному сторі"}}]}'::jsonb, null::jsonb),
  ('state-memoized-selector', 'quiz', 4, 150, '{"en":"Selector re-renders","uk":"Ререндери через селектор"}'::jsonb, '{"en":"`useSelector(state => state.items.filter(i => i.visible))` makes the component re-render on every store update, even unrelated ones. Why, and what''s the fix?","uk":"`useSelector(state => state.items.filter(i => i.visible))` змушує компонент ререндеритися при кожному оновленні стору, навіть непов''язаному. Чому й як це виправити?"}'::jsonb, 'state-management', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"`filter` returns a new array each time, so the reference check fails; use a memoised selector (`createSelector`)","uk":"`filter` щоразу повертає новий масив, тож перевірка посилань не проходить; використайте мемоізований селектор (`createSelector`)"}},{"id":"b","text":{"en":"`useSelector` always re-renders","uk":"`useSelector` завжди спричиняє ререндер"}},{"id":"c","text":{"en":"The store must be split into several stores","uk":"Стор треба розділити на кілька"}},{"id":"d","text":{"en":"Arrays can''t be selected","uk":"Масиви не можна вибирати"}}]}'::jsonb, null::jsonb),
  ('state-cart-reducer', 'practice', 3, 1020, '{"en":"Immutable cart reducer","uk":"Незмінний редʼюсер кошика"}'::jsonb, '{"en":"Implement `cartReducer(state, action)` as a **pure, immutable** function:\n\n- `add` `{ item }`: add with `qty: 1`, or increment `qty` if the id exists.\n- `remove` `{ id }`: remove the line.\n- `setQty` `{ id, qty }`: set the quantity; `qty <= 0` removes the line.\n- `clear`: empty the cart.\n- Never mutate `state` or its items. Return the **same** state object for unknown actions or no-op changes (e.g. removing a missing id).\n\nAlso implement `selectTotal(state)`, the sum of `price × qty`.","uk":"Реалізуйте `cartReducer(state, action)` як **чисту, незмінну** функцію:\n\n- `add` `{ item }`: додати з `qty: 1` або збільшити `qty`, якщо такий id уже є.\n- `remove` `{ id }`: прибрати рядок.\n- `setQty` `{ id, qty }`: встановити кількість; `qty <= 0` прибирає рядок.\n- `clear`: очистити кошик.\n- Ніколи не змінюйте `state` чи його елементи. Повертайте **той самий** об''єкт стану для невідомих дій і змін, що нічого не роблять (наприклад, видалення відсутнього id).\n\nТакож реалізуйте `selectTotal(state)`: суму `price × qty`."}'::jsonb, 'state-management', null::jsonb, '{"framework":"vanilla-ts","files":{"/src/cart.ts":"export type Item = { id: string; name: string; price: number };\nexport type Line = Item & { qty: number };\nexport type Cart = { items: Line[] };\nexport type Action =\n  | { type: \"add\"; item: Item }\n  | { type: \"remove\"; id: string }\n  | { type: \"setQty\"; id: string; qty: number }\n  | { type: \"clear\" };\n\nexport const initialCart: Cart = { items: [] };\n\nexport function cartReducer(state: Cart, action: Action): Cart {\n  // TODO: pure and immutable\n  if (action.type === \"add\") {\n    state.items.push({ ...action.item, qty: 1 });\n  }\n  return state;\n}\n\nexport function selectTotal(state: Cart): number {\n  return 0;\n}\n","/index.ts":"import \"./styles.css\";\nimport { cartReducer, initialCart, selectTotal, type Action } from \"./src/cart\";\n\nconst actions: Action[] = [\n  { type: \"add\", item: { id: \"tea\", name: \"Tea\", price: 4 } },\n  { type: \"add\", item: { id: \"cake\", name: \"Cake\", price: 6 } },\n  { type: \"add\", item: { id: \"tea\", name: \"Tea\", price: 4 } },\n  { type: \"setQty\", id: \"cake\", qty: 3 },\n];\nconst cart = actions.reduce(cartReducer, initialCart);\ndocument.getElementById(\"app\")!.innerHTML = `<h1>Cart</h1><ul>${cart.items\n  .map((l) => `<li>${l.name} × ${l.qty}</li>`)\n  .join(\"\")}</ul><p>Total: <output id=\"total\">${selectTotal(cart)}</output></p>`;\n"},"visibleFiles":["/src/cart.ts","/index.ts"],"activeFile":"/src/cart.ts","tests":"import { describe, it, expect, screen } from \"./test-kit\";\nimport { cartReducer, initialCart, selectTotal } from \"../src/cart\";\n\nconst tea = { id: \"tea\", name: \"Tea\", price: 4 };\nconst cake = { id: \"cake\", name: \"Cake\", price: 6 };\nconst freeze = (o) => { Object.freeze(o); Object.values(o).forEach((v) => v && typeof v === \"object\" && freeze(v)); return o; };\n\ndescribe(\"cartReducer\", () => {\n  it(\"adds items and increments quantity\", () => {\n    let s = cartReducer(initialCart, { type: \"add\", item: tea });\n    s = cartReducer(s, { type: \"add\", item: tea });\n    s = cartReducer(s, { type: \"add\", item: cake });\n    expect(s.items).toEqual([{ ...tea, qty: 2 }, { ...cake, qty: 1 }]);\n  });\n  it(\"never mutates the previous state\", () => {\n    const before = freeze({ items: [{ ...tea, qty: 1 }] });\n    const after = cartReducer(before, { type: \"add\", item: tea });\n    expect(after.items[0].qty).toBe(2);\n    expect(before.items[0].qty).toBe(1);\n    expect(after === before).toBe(false);\n  });\n  it(\"keeps unchanged lines by reference\", () => {\n    const s = freeze({ items: [{ ...tea, qty: 1 }, { ...cake, qty: 1 }] });\n    const next = cartReducer(s, { type: \"setQty\", id: \"cake\", qty: 5 });\n    expect(next.items[0] === s.items[0]).toBe(true);\n    expect(next.items[1].qty).toBe(5);\n  });\n  it(\"removes lines, including via setQty <= 0\", () => {\n    const s = freeze({ items: [{ ...tea, qty: 1 }, { ...cake, qty: 2 }] });\n    expect(cartReducer(s, { type: \"remove\", id: \"tea\" }).items).toEqual([{ ...cake, qty: 2 }]);\n    expect(cartReducer(s, { type: \"setQty\", id: \"cake\", qty: 0 }).items).toEqual([{ ...tea, qty: 1 }]);\n  });\n  it(\"clears the cart\", () => {\n    const s = freeze({ items: [{ ...tea, qty: 1 }] });\n    expect(cartReducer(s, { type: \"clear\" })).toEqual({ items: [] });\n  });\n  it(\"returns the same state for unknown actions and no-ops\", () => {\n    const s = freeze({ items: [{ ...tea, qty: 1 }] });\n    expect(cartReducer(s, { type: \"unknown\" } as never) === s).toBe(true);\n    expect(cartReducer(s, { type: \"remove\", id: \"missing\" }) === s).toBe(true);\n  });\n  it(\"computes the total\", () => {\n    expect(selectTotal({ items: [{ ...tea, qty: 2 }, { ...cake, qty: 3 }] })).toBe(26);\n    expect(selectTotal(initialCart)).toBe(0);\n  });\n  it(\"renders the demo\", async () => {\n    expect((await screen.findByText(\"26\")).id).toBe(\"total\");\n  });\n});\n","testCount":8}'::jsonb),
  ('ts-unknown-vs-any', 'quiz', 1, 60, '{"en":"unknown vs any","uk":"unknown проти any"}'::jsonb, '{"en":"What is the key difference between `unknown` and `any`?","uk":"У чому головна різниця між `unknown` і `any`?"}'::jsonb, 'typescript', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"`unknown` must be narrowed before you can use it; `any` disables type checking","uk":"`unknown` треба звузити перед використанням; `any` вимикає перевірку типів"}},{"id":"b","text":{"en":"`unknown` only accepts `null` and `undefined`","uk":"`unknown` приймає лише `null` і `undefined`"}},{"id":"c","text":{"en":"`any` is a runtime type, `unknown` is compile-time only","uk":"`any` є типом часу виконання, а `unknown` існує лише під час компіляції"}},{"id":"d","text":{"en":"There is no difference, they are aliases","uk":"Різниці немає, це синоніми"}}]}'::jsonb, null::jsonb),
  ('ts-structural-typing', 'quiz', 2, 90, '{"en":"Structural typing","uk":"Структурна типізація"}'::jsonb, '{"en":"Which line is a **compile error**?","uk":"Який рядок дає **помилку компіляції**?"}'::jsonb, 'typescript', '{"mode":"single","code":"type Point = { x: number; y: number };\nconst p = { x: 1, y: 2, z: 3 };\nconst a: Point = p;                    // line 3\nconst b: Point = { x: 1, y: 2, z: 3 }; // line 4","codeLanguage":"ts","options":[{"id":"a","text":{"en":"Line 3","uk":"Рядок 3"}},{"id":"b","text":{"en":"Line 4","uk":"Рядок 4"}},{"id":"c","text":{"en":"Both","uk":"Обидва"}},{"id":"d","text":{"en":"Neither","uk":"Жоден"}}]}'::jsonb, null::jsonb),
  ('ts-generic-constraint', 'quiz', 3, 120, '{"en":"Generic constraint","uk":"Обмеження дженерика"}'::jsonb, '{"en":"What does `K extends keyof T` guarantee in this signature?","uk":"Що гарантує `K extends keyof T` у цій сигнатурі?"}'::jsonb, 'typescript', '{"mode":"single","code":"function get<T, K extends keyof T>(obj: T, key: K): T[K] {\n  return obj[key];\n}","codeLanguage":"ts","options":[{"id":"a","text":{"en":"`K` is one of the property names of `T`","uk":"`K` є однією з назв властивостей `T`"}},{"id":"b","text":{"en":"`T` inherits from `K`","uk":"`T` наслідує `K`"}},{"id":"c","text":{"en":"`K` is a string","uk":"`K` є рядком"}},{"id":"d","text":{"en":"`obj[key]` exists at runtime","uk":"`obj[key]` існує під час виконання"}}]}'::jsonb, null::jsonb),
  ('ts-utility-types', 'quiz', 3, 120, '{"en":"Utility types","uk":"Утилітні типи"}'::jsonb, '{"en":"You need the type of an update payload: every field of `User` except `id`, and all of them optional. Which type expresses this?","uk":"Потрібен тип для оновлення: усі поля `User`, крім `id`, і всі необов''язкові. Який тип це виражає?"}'::jsonb, 'typescript', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"`Partial<Omit<User, \"id\">>`","uk":"`Partial<Omit<User, \"id\">>`"}},{"id":"b","text":{"en":"`Omit<Partial<User>, \"id\" | undefined>`","uk":"`Omit<Partial<User>, \"id\" | undefined>`"}},{"id":"c","text":{"en":"`Pick<User, \"id\">`","uk":"`Pick<User, \"id\">`"}},{"id":"d","text":{"en":"`Required<Omit<User, \"id\">>`","uk":"`Required<Omit<User, \"id\">>`"}}]}'::jsonb, null::jsonb),
  ('ts-exhaustive-never', 'quiz', 4, 150, '{"en":"Exhaustiveness with never","uk":"Повнота перевірки через never"}'::jsonb, '{"en":"A new variant `{ kind: \"triangle\"; a: number }` is added to `Shape`. What happens to this function?","uk":"До `Shape` додали новий варіант `{ kind: \"triangle\"; a: number }`. Що станеться з цією функцією?"}'::jsonb, 'typescript', '{"mode":"single","code":"type Shape = { kind: \"circle\"; r: number } | { kind: \"square\"; s: number };\n\nfunction area(s: Shape) {\n  switch (s.kind) {\n    case \"circle\": return Math.PI * s.r ** 2;\n    case \"square\": return s.s ** 2;\n    default: {\n      const unreachable: never = s;\n      return unreachable;\n    }\n  }\n}","codeLanguage":"ts","options":[{"id":"a","text":{"en":"It returns `undefined` for triangles at runtime, silently","uk":"Вона непомітно повертає `undefined` для трикутників під час виконання"}},{"id":"b","text":{"en":"Compilation fails on the `never` assignment until a `triangle` case is added","uk":"Компіляція падає на присвоєнні `never`, доки не додати випадок `triangle`"}},{"id":"c","text":{"en":"TypeScript adds the missing case automatically","uk":"TypeScript автоматично додасть відсутній випадок"}},{"id":"d","text":{"en":"It throws `TypeError` when called","uk":"Під час виклику кидається `TypeError`"}}]}'::jsonb, null::jsonb),
  ('ts-typed-event-emitter', 'practice', 3, 900, '{"en":"Typed event emitter","uk":"Типізований емітер подій"}'::jsonb, '{"en":"Implement `createEmitter<Events>()`, which returns `{ on, off, emit }`:\n\n- `on(event, handler)` subscribes and **returns an unsubscribe function**.\n- `off(event, handler)` removes that handler.\n- `emit(event, payload)` calls the event''s handlers in subscription order. A handler that unsubscribes during `emit` must not break the loop.\n\nThe types already restrict event names and payloads. Focus on the behaviour.","uk":"Реалізуйте `createEmitter<Events>()`, що повертає `{ on, off, emit }`:\n\n- `on(event, handler)` підписує й **повертає функцію відписки**.\n- `off(event, handler)` прибирає цей обробник.\n- `emit(event, payload)` викликає обробники події в порядку підписки. Обробник, який відписується під час `emit`, не повинен ламати цикл.\n\nТипи вже обмежують назви подій і дані. Зосередьтеся на поведінці."}'::jsonb, 'typescript', null::jsonb, '{"framework":"vanilla-ts","files":{"/src/emitter.ts":"type Handler<P> = (payload: P) => void;\n\nexport function createEmitter<Events extends Record<string, unknown>>() {\n  // TODO: store handlers per event\n\n  function on<E extends keyof Events>(event: E, handler: Handler<Events[E]>): () => void {\n    return () => {};\n  }\n\n  function off<E extends keyof Events>(event: E, handler: Handler<Events[E]>): void {}\n\n  function emit<E extends keyof Events>(event: E, payload: Events[E]): void {}\n\n  return { on, off, emit };\n}\n","/index.ts":"import \"./styles.css\";\nimport { createEmitter } from \"./src/emitter\";\n\ntype Events = { message: string; count: number };\nconst bus = createEmitter<Events>();\nconst log: string[] = [];\nbus.on(\"message\", (text) => log.push(`message: ${text}`));\nbus.on(\"count\", (n) => log.push(`count: ${n}`));\nbus.emit(\"message\", \"hello\");\nbus.emit(\"count\", 3);\n\ndocument.getElementById(\"app\")!.innerHTML = `<h1>Event log</h1><ul>${log.map((l) => `<li>${l}</li>`).join(\"\")}</ul>`;\n"},"visibleFiles":["/src/emitter.ts","/index.ts"],"activeFile":"/src/emitter.ts","tests":"import { describe, it, expect, fn, screen } from \"./test-kit\";\nimport { createEmitter } from \"../src/emitter\";\n\ntype E = { ping: number; text: string };\n\ndescribe(\"createEmitter\", () => {\n  it(\"calls handlers with the payload, in order\", () => {\n    const bus = createEmitter<E>();\n    const calls: string[] = [];\n    bus.on(\"ping\", (n) => calls.push(\"a\" + n));\n    bus.on(\"ping\", (n) => calls.push(\"b\" + n));\n    bus.emit(\"ping\", 1);\n    expect(calls).toEqual([\"a1\", \"b1\"]);\n  });\n  it(\"only calls handlers of the emitted event\", () => {\n    const bus = createEmitter<E>();\n    const h = fn();\n    bus.on(\"text\", h);\n    bus.emit(\"ping\", 1);\n    expect(h).toHaveBeenCalledTimes(0);\n  });\n  it(\"returns an unsubscribe function\", () => {\n    const bus = createEmitter<E>();\n    const h = fn();\n    const stop = bus.on(\"ping\", h);\n    stop();\n    bus.emit(\"ping\", 1);\n    expect(h).toHaveBeenCalledTimes(0);\n  });\n  it(\"supports off()\", () => {\n    const bus = createEmitter<E>();\n    const h = fn();\n    bus.on(\"ping\", h);\n    bus.off(\"ping\", h);\n    bus.emit(\"ping\", 2);\n    expect(h).toHaveBeenCalledTimes(0);\n  });\n  it(\"survives a handler that unsubscribes during emit\", () => {\n    const bus = createEmitter<E>();\n    const second = fn();\n    const stop = bus.on(\"ping\", () => stop());\n    bus.on(\"ping\", second);\n    bus.emit(\"ping\", 1);\n    expect(second).toHaveBeenCalledTimes(1);\n  });\n  it(\"renders the demo log\", async () => {\n    await screen.findByText(\"message: hello\");\n    expect(screen.getAllByRole(\"listitem\")).toHaveLength(2);\n  });\n});\n","testCount":6}'::jsonb),
  ('test-missing-await', 'quiz', 2, 90, '{"en":"A test that always passes","uk":"Тест, що завжди проходить"}'::jsonb, '{"en":"This test passes even when `loadUser` rejects. Why?","uk":"Цей тест проходить, навіть коли `loadUser` відхиляється. Чому?"}'::jsonb, 'unit-testing', '{"mode":"single","code":"it(\"loads the user\", () => {\n  loadUser(1).then((user) => {\n    expect(user).toEqual({ id: 1, name: \"Ada\" });\n  });\n});","codeLanguage":"ts","options":[{"id":"a","text":{"en":"The promise isn''t awaited or returned, so the test finishes before the assertion runs","uk":"Проміс не очікується й не повертається, тож тест завершується раніше за перевірку"}},{"id":"b","text":{"en":"`expect` doesn''t work inside `.then`","uk":"`expect` не працює всередині `.then`"}},{"id":"c","text":{"en":"Rejected promises are ignored by test runners","uk":"Тестові раннери ігнорують відхилені проміси"}},{"id":"d","text":{"en":"`toEqual` always passes for objects","uk":"`toEqual` завжди проходить для об''єктів"}}]}'::jsonb, null::jsonb),
  ('test-doubles', 'quiz', 2, 90, '{"en":"Mocks, stubs and fakes","uk":"Моки, стаби й фейки"}'::jsonb, '{"en":"You replace the database with an in-memory `Map`-based repository that really stores and returns data. What kind of test double is that?","uk":"Ви замінюєте базу даних репозиторієм у пам''яті на основі `Map`, що справді зберігає й повертає дані. Що це за тестовий дублер?"}'::jsonb, 'unit-testing', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"A stub","uk":"Stub (заглушка)"}},{"id":"b","text":{"en":"A spy","uk":"Spy (шпигун)"}},{"id":"c","text":{"en":"A fake","uk":"Fake (фейк)"}},{"id":"d","text":{"en":"A fixture","uk":"Fixture (фікстура)"}}]}'::jsonb, null::jsonb),
  ('test-query-priority', 'quiz', 2, 90, '{"en":"Choosing queries","uk":"Вибір запитів"}'::jsonb, '{"en":"In Testing Library, which query best reflects how a user finds the submit button?","uk":"Який запит у Testing Library найкраще відображає, як користувач знаходить кнопку надсилання?"}'::jsonb, 'unit-testing', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"`getByRole(\"button\", { name: \"Submit\" })`","uk":"`getByRole(\"button\", { name: \"Submit\" })`"}},{"id":"b","text":{"en":"`container.querySelector(\".btn-primary\")`","uk":"`container.querySelector(\".btn-primary\")`"}},{"id":"c","text":{"en":"`getByTestId(\"submit\")`","uk":"`getByTestId(\"submit\")`"}},{"id":"d","text":{"en":"`getAllByTagName(\"button\")[2]`","uk":"`getAllByTagName(\"button\")[2]`"}}]}'::jsonb, null::jsonb),
  ('test-fake-timers', 'quiz', 3, 120, '{"en":"Testing time-based code","uk":"Тестування коду, що залежить від часу"}'::jsonb, '{"en":"How should you test a function that retries after 30 seconds?","uk":"Як тестувати функцію, що повторює спробу через 30 секунд?"}'::jsonb, 'unit-testing', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"Use fake timers and advance time programmatically","uk":"Використати фейкові таймери й просувати час програмно"}},{"id":"b","text":{"en":"Wait 30 real seconds in the test","uk":"Чекати 30 справжніх секунд у тесті"}},{"id":"c","text":{"en":"Skip the test in CI","uk":"Пропускати тест у CI"}},{"id":"d","text":{"en":"Set the test timeout to 60 seconds","uk":"Встановити тайм-аут тесту на 60 секунд"}}]}'::jsonb, null::jsonb),
  ('test-coverage-meaning', 'quiz', 4, 120, '{"en":"What coverage tells you","uk":"Що показує покриття"}'::jsonb, '{"en":"A module has 100% line coverage. What can you conclude?","uk":"Модуль має 100% покриття рядків. Який висновок можна зробити?"}'::jsonb, 'unit-testing', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"Every line ran during tests, but not that the behaviour was asserted correctly","uk":"Кожен рядок виконувався під час тестів, але це не означає, що поведінку перевірено правильно"}},{"id":"b","text":{"en":"The module has no bugs","uk":"У модулі немає помилок"}},{"id":"c","text":{"en":"Every branch and edge case is tested","uk":"Кожну гілку й граничний випадок протестовано"}},{"id":"d","text":{"en":"The tests are fast","uk":"Тести швидкі"}}]}'::jsonb, null::jsonb),
  ('test-injectable-reminders', 'practice', 3, 900, '{"en":"Design for testability","uk":"Проєктування для тестованості"}'::jsonb, '{"en":"Implement `sendReminders(users, deps)` so it can be tested without real time or email:\n\n- `deps` provides `now(): number` (ms) and `send(email, message): Promise<void>`.\n- Send `\"We miss you!\"` to every user whose `lastActiveAt` is **more than 30 days** before `now()` and who hasn''t opted out (`optOut: true`).\n- Send them **sequentially**, in input order.\n- If one `send` fails, continue with the rest.\n- Resolve with `{ sent: string[], failed: string[] }` (emails).\n\nThe tests use mocks for `send` and a fixed clock.","uk":"Реалізуйте `sendReminders(users, deps)` так, щоб її можна було тестувати без справжнього часу й пошти:\n\n- `deps` надає `now(): number` (мс) і `send(email, message): Promise<void>`.\n- Надішліть `\"We miss you!\"` кожному користувачу, чий `lastActiveAt` **більш ніж на 30 днів** раніший за `now()` і хто не відмовився від розсилки (`optOut: true`).\n- Надсилайте **послідовно**, в порядку вхідних даних.\n- Якщо один `send` падає, продовжуйте з рештою.\n- Поверніть `{ sent: string[], failed: string[] }` (адреси).\n\nТести використовують моки для `send` і фіксований годинник."}'::jsonb, 'unit-testing', null::jsonb, '{"framework":"vanilla-ts","files":{"/src/reminders.ts":"export type User = { email: string; lastActiveAt: number; optOut?: boolean };\nexport type Deps = { now: () => number; send: (email: string, message: string) => Promise<void> };\n\nexport const DAY = 24 * 60 * 60 * 1000;\n\nexport async function sendReminders(users: User[], deps: Deps): Promise<{ sent: string[]; failed: string[] }> {\n  // TODO\n  return { sent: [], failed: [] };\n}\n","/index.ts":"import \"./styles.css\";\nimport { DAY, sendReminders } from \"./src/reminders\";\n\nconst now = Date.now();\nconst users = [\n  { email: \"ada@example.com\", lastActiveAt: now - 45 * DAY },\n  { email: \"linus@example.com\", lastActiveAt: now - 2 * DAY },\n  { email: \"grace@example.com\", lastActiveAt: now - 90 * DAY, optOut: true },\n];\nconst outbox: string[] = [];\nsendReminders(users, { now: () => now, send: async (email) => { outbox.push(email); } }).then((r) => {\n  document.getElementById(\"app\")!.innerHTML = `<h1>Reminders</h1><p>Sent: <output id=\"sent\">${r.sent.join(\", \") || \"none\"}</output></p>`;\n});\n"},"visibleFiles":["/src/reminders.ts","/index.ts"],"activeFile":"/src/reminders.ts","tests":"import { describe, it, expect, fn, screen } from \"./test-kit\";\nimport { DAY, sendReminders } from \"../src/reminders\";\n\nconst NOW = 1_000 * DAY;\nconst users = [\n  { email: \"old@x.com\", lastActiveAt: NOW - 31 * DAY },\n  { email: \"recent@x.com\", lastActiveAt: NOW - 29 * DAY },\n  { email: \"edge@x.com\", lastActiveAt: NOW - 30 * DAY },\n  { email: \"optout@x.com\", lastActiveAt: NOW - 100 * DAY, optOut: true },\n  { email: \"older@x.com\", lastActiveAt: NOW - 400 * DAY },\n];\n\ndescribe(\"sendReminders\", () => {\n  it(\"sends only to users inactive for more than 30 days who did not opt out\", async () => {\n    const send = fn(async () => {});\n    const result = await sendReminders(users, { now: () => NOW, send });\n    expect(result).toEqual({ sent: [\"old@x.com\", \"older@x.com\"], failed: [] });\n    expect(send).toHaveBeenCalledWith(\"old@x.com\", \"We miss you!\");\n    expect(send).toHaveBeenCalledTimes(2);\n  });\n  it(\"uses the injected clock\", async () => {\n    const send = fn(async () => {});\n    await sendReminders(users, { now: () => NOW - 10 * DAY, send });\n    expect(send.mock.calls.map((c) => c[0])).toEqual([\"older@x.com\"]);\n  });\n  it(\"sends sequentially, in order\", async () => {\n    let active = 0;\n    let peak = 0;\n    const order: string[] = [];\n    const send = fn(async (email: string) => {\n      active++;\n      peak = Math.max(peak, active);\n      await new Promise((r) => setTimeout(r, 5));\n      order.push(email);\n      active--;\n    });\n    await sendReminders(users, { now: () => NOW, send });\n    expect(peak).toBe(1);\n    expect(order).toEqual([\"old@x.com\", \"older@x.com\"]);\n  });\n  it(\"continues after a failure and reports it\", async () => {\n    const send = fn(async (email: string) => {\n      if (email === \"old@x.com\") throw new Error(\"SMTP down\");\n    });\n    const result = await sendReminders(users, { now: () => NOW, send });\n    expect(result).toEqual({ sent: [\"older@x.com\"], failed: [\"old@x.com\"] });\n  });\n  it(\"renders the demo\", async () => {\n    expect(await screen.findByText(\"ada@example.com\")).toBeInTheDocument();\n  });\n});\n","testCount":5}'::jsonb),
  ('a11y-first-rule', 'quiz', 1, 60, '{"en":"The first rule of ARIA","uk":"Перше правило ARIA"}'::jsonb, '{"en":"What does adding `role=\"button\"` to a `<div>` give you?","uk":"Що дає додавання `role=\"button\"` до `<div>`?"}'::jsonb, 'web-accessibility', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"Screen readers announce it as a button, but it still isn''t focusable or keyboard-operable","uk":"Зчитувачі оголошують його як кнопку, але він досі не отримує фокус і не працює з клавіатури"}},{"id":"b","text":{"en":"Full button behaviour, including Enter and Space","uk":"Повну поведінку кнопки, включно з Enter і Space"}},{"id":"c","text":{"en":"Native form submission","uk":"Нативне надсилання форми"}},{"id":"d","text":{"en":"Nothing; roles are ignored on divs","uk":"Нічого; ролі на div ігноруються"}}]}'::jsonb, null::jsonb),
  ('a11y-icon-button', 'quiz', 1, 60, '{"en":"Icon-only buttons","uk":"Кнопки лише з іконкою"}'::jsonb, '{"en":"How do you give an icon-only \"close\" button an accessible name?","uk":"Як дати доступне ім''я кнопці «закрити», що містить лише іконку?"}'::jsonb, 'web-accessibility', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"`<button aria-label=\"Close\"><svg aria-hidden=\"true\">…</svg></button>`","uk":"`<button aria-label=\"Close\"><svg aria-hidden=\"true\">…</svg></button>`"}},{"id":"b","text":{"en":"`<button title=\"\"><svg>…</svg></button>`","uk":"`<button title=\"\"><svg>…</svg></button>`"}},{"id":"c","text":{"en":"`<div class=\"close-icon\"></div>`","uk":"`<div class=\"close-icon\"></div>`"}},{"id":"d","text":{"en":"Rely on the icon''s shape","uk":"Покластися на форму іконки"}}]}'::jsonb, null::jsonb),
  ('a11y-contrast', 'quiz', 2, 90, '{"en":"Contrast requirements","uk":"Вимоги до контрасту"}'::jsonb, '{"en":"Under WCAG 2.x level AA, what is the minimum contrast ratio for normal-size body text?","uk":"Який мінімальний коефіцієнт контрасту для основного тексту звичайного розміру вимагає WCAG 2.x на рівні AA?"}'::jsonb, 'web-accessibility', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"3:1","uk":"3:1"}},{"id":"b","text":{"en":"4.5:1","uk":"4,5:1"}},{"id":"c","text":{"en":"7:1","uk":"7:1"}},{"id":"d","text":{"en":"2:1","uk":"2:1"}}]}'::jsonb, null::jsonb),
  ('a11y-modal-focus', 'quiz', 3, 120, '{"en":"Modal focus management","uk":"Керування фокусом у модальному вікні"}'::jsonb, '{"en":"Which behaviours does an accessible modal dialog need? Select all that apply.","uk":"Яка поведінка потрібна доступному модальному діалогу? Оберіть усі правильні."}'::jsonb, 'web-accessibility', '{"mode":"multi","codeLanguage":"ts","options":[{"id":"a","text":{"en":"Move focus into the dialog when it opens","uk":"Перенести фокус у діалог під час відкриття"}},{"id":"b","text":{"en":"Keep Tab focus inside the dialog while it''s open","uk":"Утримувати фокус Tab усередині діалогу, поки він відкритий"}},{"id":"c","text":{"en":"Close on Escape and return focus to the element that opened it","uk":"Закриватися на Escape й повертати фокус на елемент, що його відкрив"}},{"id":"d","text":{"en":"Remove the focus outline so the design stays clean","uk":"Прибрати обведення фокусу, щоб дизайн був чистим"}}]}'::jsonb, null::jsonb),
  ('a11y-live-region', 'quiz', 4, 150, '{"en":"Announcing updates","uk":"Оголошення оновлень"}'::jsonb, '{"en":"After \"Add to cart\", a small badge updates silently. How do you let screen-reader users know without moving focus?","uk":"Після «Додати в кошик» маленький бейдж оновлюється мовчки. Як повідомити користувачам зчитувачів екрана, не переносячи фокус?"}'::jsonb, 'web-accessibility', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"Render a status message in an element with `role=\"status\"` (aria-live=\"polite\") that exists before the update","uk":"Виводити повідомлення в елемент із `role=\"status\"` (aria-live=\"polite\"), що існує ще до оновлення"}},{"id":"b","text":{"en":"Use `alert()`","uk":"Використати `alert()`"}},{"id":"c","text":{"en":"Add `aria-hidden=\"false\"` to the badge","uk":"Додати бейджу `aria-hidden=\"false\"`"}},{"id":"d","text":{"en":"Change the badge colour to red","uk":"Змінити колір бейджа на червоний"}}]}'::jsonb, null::jsonb),
  ('a11y-accessible-switch', 'practice', 3, 900, '{"en":"Make a custom switch accessible","uk":"Зробіть власний перемикач доступним"}'::jsonb, '{"en":"The design uses `<div class=\"switch\" data-label=\"…\">` toggles. Implement `enhanceSwitch(el, onChange)` so each one behaves like a real switch:\n\n- Role `switch`, named by `data-label` (`aria-label`), reachable with **Tab**.\n- `aria-checked` reflects the state, starting as `\"false\"`.\n- Toggles on **click**, **Space** and **Enter**. Space must not scroll the page (`preventDefault`).\n- Calls `onChange(checked)` after each toggle.","uk":"Дизайн використовує перемикачі `<div class=\"switch\" data-label=\"…\">`. Реалізуйте `enhanceSwitch(el, onChange)`, щоб кожен поводився як справжній перемикач:\n\n- Роль `switch`, ім''я з `data-label` (`aria-label`), доступний через **Tab**.\n- `aria-checked` відображає стан і спершу дорівнює `\"false\"`.\n- Перемикається **кліком**, **Space** і **Enter**. Space не повинен прокручувати сторінку (`preventDefault`).\n- Викликає `onChange(checked)` після кожного перемикання."}'::jsonb, 'web-accessibility', null::jsonb, '{"framework":"vanilla-js","files":{"/src/switch.js":"/**\n * @param {HTMLElement} el\n * @param {(checked: boolean) => void} onChange\n */\nexport function enhanceSwitch(el, onChange) {\n  // TODO: role, name, focusability, state, click + keyboard\n  el.addEventListener(\"click\", () => {\n    el.classList.toggle(\"on\");\n    onChange(el.classList.contains(\"on\"));\n  });\n}\n","/index.js":"import \"./styles.css\";\nimport { enhanceSwitch } from \"./src/switch\";\n\nconst app = document.getElementById(\"app\");\napp.innerHTML = `\n  <h1>Settings</h1>\n  <div class=\"switch\" data-label=\"Dark mode\"></div>\n  <div class=\"switch\" data-label=\"Email notifications\"></div>\n  <p id=\"status\" role=\"status\"></p>`;\nconst status = document.getElementById(\"status\");\nfor (const el of document.querySelectorAll(\".switch\")) {\n  enhanceSwitch(el, (on) => (status.textContent = `${el.dataset.label}: ${on ? \"on\" : \"off\"}`));\n}\n","/styles.css":".switch {\n  display: inline-block;\n  width: 44px;\n  height: 24px;\n  margin: 8px 0;\n  border-radius: 999px;\n  background: #9aa;\n  cursor: pointer;\n  position: relative;\n}\n.switch::after {\n  content: \"\";\n  position: absolute;\n  top: 3px;\n  left: 3px;\n  width: 18px;\n  height: 18px;\n  border-radius: 50%;\n  background: white;\n  transition: transform 0.2s;\n}\n.switch.on,\n.switch[aria-checked=\"true\"] {\n  background: #0b5a43;\n}\n.switch.on::after,\n.switch[aria-checked=\"true\"]::after {\n  transform: translateX(20px);\n}\n.switch:focus-visible {\n  outline: 3px solid #c9a227;\n  outline-offset: 2px;\n}\n"},"visibleFiles":["/src/switch.js","/index.js"],"activeFile":"/src/switch.js","tests":"import { describe, it, expect, fn, screen, user } from \"./test-kit\";\nimport { enhanceSwitch } from \"../src/switch\";\n\nfunction make(label = \"Wi-Fi\") {\n  const el = document.createElement(\"div\");\n  el.className = \"switch\";\n  el.dataset.label = label;\n  document.body.append(el);\n  return el;\n}\nfunction key(el, k) {\n  const e = new KeyboardEvent(\"keydown\", { key: k, bubbles: true, cancelable: true });\n  el.dispatchEvent(e);\n  return e;\n}\n\ndescribe(\"enhanceSwitch\", () => {\n  it(\"exposes role, name and initial state, and is focusable\", () => {\n    const el = make();\n    enhanceSwitch(el, () => {});\n    expect(el).toHaveAttribute(\"role\", \"switch\");\n    expect(el).toHaveAttribute(\"aria-label\", \"Wi-Fi\");\n    expect(el).toHaveAttribute(\"aria-checked\", \"false\");\n    expect(el.tabIndex).toBe(0);\n    el.remove();\n  });\n  it(\"toggles on click and reports the state\", () => {\n    const el = make();\n    const onChange = fn();\n    enhanceSwitch(el, onChange);\n    el.click();\n    expect(el).toHaveAttribute(\"aria-checked\", \"true\");\n    el.click();\n    expect(el).toHaveAttribute(\"aria-checked\", \"false\");\n    expect(onChange.mock.calls).toEqual([[true], [false]]);\n    el.remove();\n  });\n  it(\"toggles with Space and Enter, and Space doesn''t scroll\", () => {\n    const el = make();\n    const onChange = fn();\n    enhanceSwitch(el, onChange);\n    const space = key(el, \" \");\n    expect(el).toHaveAttribute(\"aria-checked\", \"true\");\n    expect(space.defaultPrevented).toBe(true);\n    key(el, \"Enter\");\n    expect(el).toHaveAttribute(\"aria-checked\", \"false\");\n    key(el, \"a\");\n    expect(onChange).toHaveBeenCalledTimes(2);\n    el.remove();\n  });\n  it(\"works in the settings demo\", async () => {\n    const dark = screen.getByRole(\"switch\", { name: \"Dark mode\" });\n    await user.click(dark);\n    expect(screen.getByRole(\"status\")).toHaveTextContent(\"Dark mode: on\");\n  });\n});\n","testCount":4}'::jsonb),
  ('perf-core-web-vitals', 'quiz', 1, 60, '{"en":"Core Web Vitals","uk":"Core Web Vitals"}'::jsonb, '{"en":"Which metric measures how quickly the page responds visually to a click or key press?","uk":"Яка метрика вимірює, наскільки швидко сторінка візуально реагує на клік чи натискання клавіші?"}'::jsonb, 'web-performance', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"LCP","uk":"LCP"}},{"id":"b","text":{"en":"INP","uk":"INP"}},{"id":"c","text":{"en":"CLS","uk":"CLS"}},{"id":"d","text":{"en":"TTFB","uk":"TTFB"}}]}'::jsonb, null::jsonb),
  ('perf-transform-animation', 'quiz', 2, 90, '{"en":"Cheap animations","uk":"Дешеві анімації"}'::jsonb, '{"en":"Which property change is the cheapest to animate at 60 fps?","uk":"Зміну якої властивості найдешевше анімувати з частотою 60 кадрів/с?"}'::jsonb, 'web-performance', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"`left`","uk":"`left`"}},{"id":"b","text":{"en":"`width`","uk":"`width`"}},{"id":"c","text":{"en":"`transform: translateX()`","uk":"`transform: translateX()`"}},{"id":"d","text":{"en":"`margin-left`","uk":"`margin-left`"}}]}'::jsonb, null::jsonb),
  ('perf-cls-images', 'quiz', 2, 90, '{"en":"Layout shift","uk":"Зсув розкладки"}'::jsonb, '{"en":"Text jumps down when images load. What''s the simplest fix?","uk":"Текст зсувається донизу, коли завантажуються зображення. Яке найпростіше виправлення?"}'::jsonb, 'web-performance', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"Set `width` and `height` (or `aspect-ratio`) on the images so space is reserved","uk":"Задати `width` і `height` (або `aspect-ratio`) зображенням, щоб резервувати місце"}},{"id":"b","text":{"en":"Add `loading=\"lazy\"`","uk":"Додати `loading=\"lazy\"`"}},{"id":"c","text":{"en":"Convert the images to WebP","uk":"Конвертувати зображення у WebP"}},{"id":"d","text":{"en":"Load the images with JavaScript","uk":"Завантажувати зображення через JavaScript"}}]}'::jsonb, null::jsonb),
  ('perf-debounce-vs-throttle', 'quiz', 3, 120, '{"en":"Debounce or throttle","uk":"Debounce чи throttle"}'::jsonb, '{"en":"You update a \"back to top\" button based on scroll position and want it to react smoothly while the user scrolls, without running on every event. What do you use?","uk":"Ви оновлюєте кнопку «нагору» залежно від позиції прокрутки й хочете, щоб вона плавно реагувала під час прокрутки, але не на кожну подію. Що використати?"}'::jsonb, 'web-performance', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"Debounce: runs once after scrolling stops","uk":"Debounce: виконується один раз після зупинки прокрутки"}},{"id":"b","text":{"en":"Throttle: runs at most once per interval while scrolling continues","uk":"Throttle: виконується не частіше за раз на інтервал, поки прокрутка триває"}},{"id":"c","text":{"en":"Neither: `scroll` events are already throttled to once per second","uk":"Жоден: події `scroll` уже обмежені до одного разу на секунду"}},{"id":"d","text":{"en":"setInterval polling every 1 ms","uk":"Опитування через setInterval кожну 1 мс"}}]}'::jsonb, null::jsonb),
  ('perf-long-task', 'quiz', 4, 150, '{"en":"Long tasks and INP","uk":"Довгі задачі та INP"}'::jsonb, '{"en":"Clicking \"Export\" freezes the page for 800 ms while a big array is processed. Which changes improve responsiveness? Select all that apply.","uk":"Клік на «Export» заморожує сторінку на 800 мс, поки обробляється великий масив. Які зміни покращать чутливість? Оберіть усі правильні."}'::jsonb, 'web-performance', '{"mode":"multi","codeLanguage":"ts","options":[{"id":"a","text":{"en":"Move the processing into a Web Worker","uk":"Перенести обробку у Web Worker"}},{"id":"b","text":{"en":"Split the work into chunks and yield to the main thread between them","uk":"Розбити роботу на частини й поступатися головним потоком між ними"}},{"id":"c","text":{"en":"Wrap the loop in `async function` without any `await`","uk":"Обгорнути цикл в `async function` без жодного `await`"}},{"id":"d","text":{"en":"Show feedback (spinner) before starting the heavy work","uk":"Показати відгук (спінер) перед початком важкої роботи"}}]}'::jsonb, null::jsonb),
  ('perf-debounce', 'practice', 3, 900, '{"en":"Debounce with cancel","uk":"Debounce зі скасуванням"}'::jsonb, '{"en":"Implement `debounce(fn, wait)`:\n\n- Returns a function that delays calling `fn` until `wait` ms have passed **since the last call**.\n- `fn` receives the **latest** arguments and the caller''s `this`.\n- The returned function has a `cancel()` method that drops a pending call.\n\nThe demo search box logs a \"search\" only after you stop typing.","uk":"Реалізуйте `debounce(fn, wait)`:\n\n- Повертає функцію, яка відкладає виклик `fn`, доки не мине `wait` мс **від останнього виклику**.\n- `fn` отримує **останні** аргументи й `this` того, хто викликав.\n- Повернена функція має метод `cancel()`, що скасовує відкладений виклик.\n\nДемо-поле пошуку записує «search» лише після того, як ви перестанете друкувати."}'::jsonb, 'web-performance', null::jsonb, '{"framework":"vanilla-ts","files":{"/src/debounce.ts":"export type Debounced<A extends unknown[]> = ((...args: A) => void) & { cancel(): void };\n\nexport function debounce<A extends unknown[]>(fn: (...args: A) => void, wait: number): Debounced<A> {\n  // TODO\n  const debounced = ((...args: A) => fn(...args)) as Debounced<A>;\n  debounced.cancel = () => {};\n  return debounced;\n}\n","/index.ts":"import \"./styles.css\";\nimport { debounce } from \"./src/debounce\";\n\nconst app = document.getElementById(\"app\")!;\napp.innerHTML = `<h1>Debounced search</h1>\n<label for=\"q\">Search</label> <input id=\"q\" />\n<ol id=\"log\"></ol>`;\nconst log = document.getElementById(\"log\")!;\nconst search = debounce((q: string) => log.insertAdjacentHTML(\"beforeend\", `<li>search: ${q}</li>`), 300);\ndocument.getElementById(\"q\")!.addEventListener(\"input\", (e) => search((e.target as HTMLInputElement).value));\n"},"visibleFiles":["/src/debounce.ts","/index.ts"],"activeFile":"/src/debounce.ts","tests":"import { describe, it, expect, fn, sleep, screen, user } from \"./test-kit\";\nimport { debounce } from \"../src/debounce\";\n\ndescribe(\"debounce\", () => {\n  it(\"waits before calling\", async () => {\n    const spy = fn();\n    const d = debounce(spy, 50);\n    d();\n    expect(spy).toHaveBeenCalledTimes(0);\n    await sleep(80);\n    expect(spy).toHaveBeenCalledTimes(1);\n  });\n  it(\"collapses a burst into one call with the latest arguments\", async () => {\n    const spy = fn();\n    const d = debounce(spy, 50);\n    d(\"a\");\n    d(\"ab\");\n    d(\"abc\");\n    await sleep(90);\n    expect(spy).toHaveBeenCalledTimes(1);\n    expect(spy).toHaveBeenCalledWith(\"abc\");\n  });\n  it(\"restarts the timer on every call\", async () => {\n    const spy = fn();\n    const d = debounce(spy, 60);\n    d();\n    await sleep(40);\n    d();\n    await sleep(40);\n    expect(spy).toHaveBeenCalledTimes(0);\n    await sleep(50);\n    expect(spy).toHaveBeenCalledTimes(1);\n  });\n  it(\"preserves this\", async () => {\n    let seen: unknown;\n    const obj = { name: \"box\", run: debounce(function (this: { name: string }) { seen = this.name; }, 20) };\n    obj.run();\n    await sleep(40);\n    expect(seen).toBe(\"box\");\n  });\n  it(\"cancel() drops the pending call\", async () => {\n    const spy = fn();\n    const d = debounce(spy, 30);\n    d();\n    d.cancel();\n    await sleep(60);\n    expect(spy).toHaveBeenCalledTimes(0);\n  });\n  it(\"debounces the demo search box\", async () => {\n    await user.type(screen.getByLabelText(\"Search\"), \"react\");\n    await sleep(400);\n    const items = screen.getAllByRole(\"listitem\");\n    expect(items).toHaveLength(1);\n    expect(items[0]).toHaveTextContent(\"search: react\");\n  });\n});\n","testCount":6}'::jsonb)
) as v(slug, kind, complexity, est_seconds, title, prompt, lecture_slug, quiz, practice)
left join public.lectures l on l.slug = v.lecture_slug
on conflict (slug) do update set kind = excluded.kind, complexity = excluded.complexity, est_seconds = excluded.est_seconds,
  title = excluded.title, prompt = excluded.prompt, lecture_id = excluded.lecture_id, quiz = excluded.quiz,
  practice = excluded.practice, published = true, updated_at = now();

