insert into public.task_skills (task_id, skill_id, weight)
select t.id, s.id, v.weight from (values
  ('ng-binding-syntax', 'angular', 1::real),
  ('ng-oninit-vs-constructor', 'angular', 1::real),
  ('ng-onpush-mutation', 'angular', 1::real),
  ('ng-onpush-mutation', 'state-management', 0.5::real),
  ('ng-provider-scope', 'angular', 1::real),
  ('ng-async-pipe', 'angular', 1::real),
  ('ng-async-pipe', 'rxjs', 0.5::real),
  ('ng-quantity-stepper', 'angular', 1::real),
  ('arr-default-sort', 'arrays-strings', 1::real),
  ('arr-default-sort', 'javascript', 0.5::real),
  ('arr-mutating-methods', 'arrays-strings', 1::real),
  ('arr-reduce-initial', 'arrays-strings', 1::real),
  ('arr-dedupe-complexity', 'arrays-strings', 1::real),
  ('arr-dedupe-complexity', 'big-o', 0.5::real),
  ('str-emoji-reverse', 'arrays-strings', 1::real),
  ('str-group-anagrams', 'arrays-strings', 1::real),
  ('str-group-anagrams', 'data-structures', 0.5::real),
  ('async-event-loop-order', 'async-javascript', 1::real),
  ('async-event-loop-order', 'javascript', 0.5::real),
  ('async-all-settled', 'async-javascript', 1::real),
  ('async-foreach-await', 'async-javascript', 1::real),
  ('async-sequential-vs-parallel', 'async-javascript', 1::real),
  ('async-sequential-vs-parallel', 'web-performance', 0.5::real),
